extends Node3D
## One car: arcade rally physics, visuals (suspension, body roll, wheels, flames, lights), dust/splash/skids and sound.

const CarModel = preload("res://scripts/carmodel.gd")
const CarBake = preload("res://scripts/carbake.gd")
const Mk = preload("res://scripts/mk.gd")

const GRAV := 16.0
# surface: [grip, drag, top speed factor, loose]
const SURF := [
	[1.0, 0.3, 1.0, 0.0],    # tarmac
	[0.84, 0.45, 0.97, 1.0],  # gravel
	[0.86, 0.5, 0.96, 1.0],   # dirt
	[0.72, 1.1, 0.88, 1.0],   # sand
	[0.78, 0.85, 0.9, 1.0],   # grass
	[0.86, 0.6, 0.92, 0.5],   # rock
	[0.62, 4.0, 0.42, 1.0],   # water
	[0.62, 0.7, 0.9, 1.0],    # snow
]

var world
var fx
var def := {}
var car_id := ""
var paint := Color.WHITE
var model := {}
var is_player := false
var skill := 1.0
var tag := ""
var ghost := false

var pos := Vector3.ZERO
var vel := Vector3.ZERO
var yaw := 0.0
var yaw_rate := 0.0
var grounded := true
var n_s := Vector3.UP
var vf := 0.0
var vr := 0.0
var speed := 0.0
var slip := 0.0
var drifting := false
var drift_exit := 0.0
var neutral_t := 0.0
var hb_prev := false
var steer_s := 0.0
var air_t := 0.0
var air_spin := 0.0
var air_peak := 0.0
var takeoff := Vector3.ZERO
var surface := 0
var nitro := 0.6
var nitro_on := false
var frozen := false
var long_acc := 0.0
var depth := 0.0
var wet := 0.0
var edge_r := 980.0

var in_t := 0.0
var in_b := 0.0
var in_s := 0.0
var in_hb := false
var in_nitro := false

var ev_land := 0.0
var ev_landed := false
var ev_air := 0.0
var ev_spin := 0.0
var ev_peak := 0.0
var ev_hit := 0.0
var ev_splash := false

var half_len := 2.2
var half_w := 1.0
var cam_h := 1.3
var roll := 0.0
var pitch := 0.0
var bob := 0.0
var bob_v := 0.0
var w_off := [0.0, 0.0, 0.0, 0.0]
var shadow: MeshInstance3D
var skid_last := [Vector3.ZERO, Vector3.ZERO]
var skid_on := [false, false]
var dust_acc := 0.0
var fx_near := true
var was_water := false
var lights_on := false
var heads := []
var head_glow: MeshInstance3D

var eng: Node
var skid_p: AudioStreamPlayer
var sand_p: AudioStreamPlayer
var wind_p: AudioStreamPlayer
var nos_p: AudioStreamPlayer
var rpm := 0.2
var gear := 1
var safe_pos := Vector3.ZERO
var safe_yaw := 0.0
var safe_t := 0.0


func setup(w, f, id: String, col: Color, player: bool) -> void:
	world = w
	fx = f
	is_player = player
	set_car(id, col)
	shadow = MeshInstance3D.new()
	var q := QuadMesh.new()
	q.size = Vector2(1, 1)
	q.orientation = PlaneMesh.FACE_Y
	shadow.mesh = q
	var sm := StandardMaterial3D.new()
	sm.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	sm.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	sm.albedo_texture = G.tex("puff")
	sm.albedo_color = Color(0, 0, 0, 0.5)
	sm.render_priority = -1
	shadow.material_override = sm
	shadow.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	shadow.top_level = true
	add_child(shadow)
	if not ghost:
		_audio()


func set_car(id: String, col: Color) -> void:
	car_id = id
	paint = col
	def = G.car_def(id)
	if model.has("root") and is_instance_valid(model.root):
		model.root.queue_free()
	var high := int(G.data.gfx) > 0
	if is_player or ghost:
		model = CarModel.build(id, col, is_player and high, false)
		if is_player:
			CarBake.merge_static(model)
	else:
		model = CarBake.build(id, col, high)
	add_child(model.root)
	half_len = model.half_len
	half_w = model.half_w
	cam_h = model.cam_h
	if eng is AudioStreamPlayer or eng is AudioStreamPlayer3D:
		eng.stream = G.loop_stream("engine")
	_headlights()


func _headlights() -> void:
	for h in heads:
		if is_instance_valid(h):
			h.queue_free()
	heads.clear()
	if not is_player:
		return
	for s: float in [-1.0, 1.0]:
		var sp := SpotLight3D.new()
		sp.light_color = Color(1.0, 0.93, 0.8)
		sp.light_energy = 6.0
		sp.spot_range = 70.0
		sp.spot_angle = 32.0
		sp.spot_attenuation = 0.6
		sp.spot_angle_attenuation = 1.4
		sp.position = Vector3(s * half_w * 0.6, 0.75, -half_len + 0.2)
		sp.rotation.x = -0.06
		sp.shadow_enabled = false
		sp.visible = lights_on
		model.body.add_child(sp)
		heads.append(sp)
	# soft glow cone in front of the car (fake light shafts in rain / at night)
	var cm := StandardMaterial3D.new()
	cm.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	cm.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	cm.blend_mode = BaseMaterial3D.BLEND_MODE_ADD
	cm.cull_mode = BaseMaterial3D.CULL_DISABLED
	cm.albedo_color = Color(1.0, 0.95, 0.8, 0.035)
	head_glow = MeshInstance3D.new()
	head_glow.mesh = Mk.cyl(4.5, 0.3, 26.0, 16)
	head_glow.material_override = cm
	head_glow.rotation.x = PI / 2
	head_glow.position = Vector3(0, 0.75, -half_len - 13.0)
	head_glow.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	head_glow.visible = lights_on
	model.body.add_child(head_glow)
	heads.append(head_glow)


func set_lights(on: bool) -> void:
	lights_on = on
	for h in heads:
		if is_instance_valid(h):
			h.visible = on


func _audio() -> void:
	if is_player:
		var p := AudioStreamPlayer.new()
		p.stream = G.loop_stream("engine")
		p.volume_db = -8.0
		add_child(p)
		eng = p
		skid_p = _loop("skid")
		sand_p = _loop("gravel")
		wind_p = _loop("wind")
		nos_p = _loop("nitro_loop")
	else:
		var p := AudioStreamPlayer3D.new()
		p.stream = G.loop_stream("engine")
		p.unit_size = 9.0
		p.max_db = -6.0
		p.volume_db = -10.0
		p.max_distance = 140.0
		add_child(p)
		eng = p


func _loop(n: String) -> AudioStreamPlayer:
	var p := AudioStreamPlayer.new()
	p.stream = G.loop_stream(n)
	p.volume_db = -80.0
	add_child(p)
	return p


func start_audio() -> void:
	if G.headless:
		return
	for p in [eng, skid_p, sand_p, wind_p, nos_p]:
		if p != null and not p.playing:
			p.play()


func stop_audio() -> void:
	for p in [eng, skid_p, sand_p, wind_p, nos_p]:
		if p != null:
			p.stop()


func place(p: Vector3, heading: float) -> void:
	pos = p
	pos.y = world.ground(p.x, p.z) + 0.05
	yaw = heading
	vel = Vector3.ZERO
	yaw_rate = 0.0
	drifting = false
	grounded = true
	air_t = 0.0
	n_s = world.normal_at(pos.x, pos.z)
	steer_s = 0.0
	safe_pos = pos
	safe_yaw = yaw
	skid_on = [false, false]
	update_visual(0.0)


func set_input(t: float, b: float, s: float, hb: bool, nos: bool) -> void:
	in_t = t
	in_b = b
	in_s = s
	in_hb = hb
	in_nitro = nos


func fwd_flat() -> Vector3:
	return Vector3(-sin(yaw), 0, -cos(yaw))


# ------------------------------------------------------------------ physics
func step(dt: float) -> void:
	ev_land = 0.0
	ev_landed = false
	ev_hit = 0.0
	ev_splash = false
	var s_target := in_s
	var rate := 4.5 if absf(s_target) > absf(steer_s) else 8.0
	steer_s = move_toward(steer_s, s_target, rate * dt)
	if frozen:
		vel = Vector3.ZERO
		yaw_rate = 0.0
		speed = 0.0
		vf = 0.0
		return
	nitro_on = in_nitro and nitro > 0.0
	if nitro_on:
		nitro = maxf(0.0, nitro - dt * 0.24)
	var h: float = world.ground(pos.x, pos.z, pos.y)
	var gap := pos.y - h
	var contact := gap < (0.3 if grounded else 0.06)
	if contact:
		var n: Vector3 = world.normal_at(pos.x, pos.z, pos.y)
		if not grounded:
			_land(n)
		grounded = true
		surface = world.surface_at(pos.x, pos.z, h)
		_ground(dt, n, gap)
	else:
		if grounded:
			takeoff = pos
			air_t = 0.0
			air_spin = 0.0
			air_peak = 0.0
		grounded = false
		_air(dt)
	yaw += yaw_rate * dt
	pos += vel * dt
	var h2: float = world.ground(pos.x, pos.z, pos.y)
	if pos.y < h2:
		pos.y = h2
		var n2: Vector3 = world.normal_at(pos.x, pos.z, pos.y)
		if not grounded:
			_land(n2)
			grounded = true
		var vn := vel.dot(n2)
		if vn < 0.0:
			vel -= n2 * vn
	elif not grounded:
		air_peak = maxf(air_peak, pos.y - h2)
	# soft world edge (island)
	if edge_r > 0.0:
		var r := Vector2(pos.x, pos.z).length()
		if r > edge_r:
			var inward := Vector3(-pos.x, 0, -pos.z).normalized()
			pos += inward * (r - edge_r) * 0.5
			var vo := vel.dot(-inward)
			if vo > 0.0:
				vel += inward * vo * 1.2
				ev_hit = maxf(ev_hit, vo * 0.5)
	# static obstacles: two circles along the car
	var f := fwd_flat()
	for off in [half_len * 0.5, -half_len * 0.5]:
		var res: Array = world.collide(self, pos + f * off, half_w * 0.95)
		if res[0] > ev_hit:
			ev_hit = res[0]
	if ev_hit > 3.0:
		yaw_rate += randf_range(-1.0, 1.0) * minf(ev_hit, 12.0) * 0.08
	speed = Vector2(vel.x, vel.z).length()
	depth = world.water_depth(pos.x, pos.z)
	if grounded and surface != 6 and speed > 3.0 and depth < 0.0:
		safe_t += dt
		if safe_t > 1.0:
			safe_t = 0.0
			safe_pos = pos
			safe_yaw = yaw
	var in_water: bool = depth > 0.05 and pos.y < 0.4
	if in_water and not was_water and speed > 4.0:
		ev_splash = true
	was_water = in_water


func _ground(dt: float, n: Vector3, gap: float) -> void:
	var sp: Array = SURF[surface]
	var loose: bool = float(sp[3]) > 0.5
	var lb := float(def.loose) if loose else 1.0
	var grip_s: float = float(sp[0]) * lb * (1.0 - wet * 0.12 * (1.0 - float(sp[3])))
	var f0 := fwd_flat()
	var f := (f0 - n * f0.dot(n)).normalized()
	var r := f.cross(n)
	vf = vel.dot(f)
	vr = vel.dot(r)
	var vn := vel.dot(n)
	var g := Vector3(0, -GRAV, 0)
	vf += g.dot(f) * dt
	vr += g.dot(r) * dt * 0.6
	vn += g.dot(n) * dt
	if gap > 0.0:
		vn -= 24.0 * clampf(gap / 0.3, 0.0, 1.0) * dt
	var vmax: float = float(def.vmax) * skill * float(sp[2]) * (lerpf(1.0, lb, 0.6) if loose else 1.0)
	var amax: float = float(def.accel) * skill
	if nitro_on:
		vmax += 15.0
		amax *= 1.8
	var acc := 0.0
	if in_t > 0.01:
		if vf < -1.0:
			acc += 20.0 * in_t
		else:
			var ratio := clampf(vf / vmax, 0.0, 1.3)
			acc += amax * in_t * clampf(1.0 - ratio * ratio, -0.6, 1.0)
	if in_b > 0.01:
		if vf > 1.0:
			acc -= 24.0 * in_b * (0.8 if loose else 1.0)
		else:
			acc -= 9.0 * in_b * clampf(1.0 + vf / 14.0, 0.0, 1.0)
	if in_hb:
		acc = acc * 0.65 - signf(vf) * 2.5
	acc -= vf * (0.012 + 0.03 * float(sp[1]))
	if in_t < 0.01 and in_b < 0.01:
		acc -= signf(vf) * minf(absf(vf) / maxf(dt, 0.001), 0.8 + 1.0 * float(sp[1]))
	vf += acc * dt
	long_acc = lerpf(long_acc, acc, 1.0 - exp(-6.0 * dt))
	var sh := sqrt(vf * vf + vr * vr)
	slip = atan2(vr, absf(vf) + 0.5) if vf > -0.5 else 0.0
	var hb_press := in_hb and not hb_prev
	hb_prev = in_hb
	if hb_press and sh > 6.0:
		var dir := 0.0
		if absf(steer_s) > 0.15:
			dir = -signf(steer_s)
		elif absf(yaw_rate) > 0.15:
			dir = signf(yaw_rate)
		yaw_rate += dir * 1.5
		drifting = true
		drift_exit = 0.0
	if not drifting and sh > 11.0 and absf(slip) > 0.3:
		drifting = true
		drift_exit = 0.0
	if drifting:
		if sh < 4.0 or vf < 0.0:
			drifting = false
		elif absf(slip) < 0.11 and not in_hb:
			drift_exit += dt
			if drift_exit > 0.3:
				drifting = false
		else:
			drift_exit = 0.0
	var k := clampf(absf(vf) / 6.0, 0.0, 1.0)
	var hi := clampf((sh - 12.0) / 28.0, 0.0, 1.0)
	var dirm := 1.0 if vf > -0.5 else -1.0
	var grip: float = float(def.grip) * grip_s
	if drifting:
		grip = float(def.dgrip) * grip_s * (0.6 if in_hb else 1.0)
		var ds := signf(slip) if absf(slip) > 0.06 else (-signf(steer_s) if absf(steer_s) > 0.1 else 1.0)
		var want := 0.3 * exp(-neutral_t * 1.4)
		neutral_t += dt
		if absf(steer_s) > 0.1:
			neutral_t = 0.0
			if signf(-steer_s) == ds:
				want = lerpf(0.42, 0.85, absf(steer_s))
			else:
				want = lerpf(0.25, 0.0, absf(steer_s))
		if in_hb:
			want += 0.12
		var donut := in_hb and absf(steer_s) > 0.75 and in_t > 0.5 and sh < 24.0
		if donut:
			want = 1.2
			ds = -signf(steer_s)
			grip = 3.6
			if sh > 9.0:
				var k2 := exp(-1.4 * dt)
				vf *= k2
				vr *= k2
		var vel_yaw := atan2(-(vel.x), -(vel.z))
		var err := wrapf(vel_yaw + ds * want - yaw, -PI, PI)
		var target := err * 4.2
		yaw_rate = lerpf(yaw_rate, target, 1.0 - exp(-5.0 * dt))
		if absf(slip) > 1.45 and not donut:
			grip += (absf(slip) - 1.45) * 8.0
	else:
		var target := -steer_s * float(def.steer) * k * lerpf(1.0, 0.48, hi) * dirm
		if in_hb:
			grip *= 0.5
		yaw_rate = lerpf(yaw_rate, target, 1.0 - exp(-10.0 * dt))
	var vr_new := vr * exp(-grip * dt)
	if vf > 0.0:
		vf += (absf(vr) - absf(vr_new)) * (0.35 if drifting else 0.12)
	vr = vr_new
	vel = f * vf + r * vr + n * vn
	n_s = n_s.lerp(n, 1.0 - exp(-14.0 * dt)).normalized()


func _air(dt: float) -> void:
	air_t += dt
	vel.y -= GRAV * dt
	vel *= exp(-0.03 * dt)
	var target := -in_s * 4.4
	yaw_rate = lerpf(yaw_rate, target, 1.0 - exp(-3.0 * dt))
	air_spin += yaw_rate * dt
	n_s = n_s.lerp(Vector3.UP, 1.0 - exp(-1.2 * dt)).normalized()
	hb_prev = in_hb


func _land(n: Vector3) -> void:
	var vn := vel.dot(n)
	var impact := maxf(0.0, -vn)
	if vn < 0.0:
		vel -= n * vn
	if impact > 9.0:
		vel += n * impact * 0.12
	ev_land = impact
	ev_landed = true
	ev_air = air_t
	ev_spin = air_spin
	ev_peak = air_peak
	bob_v -= impact * 0.06
	var hv := Vector3(vel.x, 0, vel.z)
	if hv.length() > 8.0:
		var vy := atan2(-hv.x, -hv.z)
		var d := wrapf(yaw - vy, -PI, PI)
		if absf(d) > 0.35 and absf(d) < 2.4:
			drifting = true
			drift_exit = 0.0
		elif absf(d) >= 2.4:
			yaw = vy + signf(d) * 0.6
			drifting = true
	air_t = 0.0
	yaw_rate *= 0.5


func reset_to_safe() -> void:
	place(safe_pos, safe_yaw)


# ------------------------------------------------------------------ visuals, effects, audio
func update_visual(dt: float) -> void:
	var up := n_s
	var fw := fwd_flat()
	var right := fw.cross(up).normalized()
	fw = up.cross(right).normalized()
	var b := Basis(right, up, -fw)
	if not grounded:
		var p := clampf(atan2(vel.y, maxf(speed, 1.0)) * 0.45, -0.45, 0.35)
		b = b * Basis(Vector3.RIGHT, p)
	transform = Transform3D(b, pos)
	if dt <= 0.0:
		return
	var roll_t := clampf(yaw_rate * speed * 0.0045, -0.1, 0.1) if grounded else 0.0
	var pitch_t := clampf(long_acc * 0.005, -0.06, 0.07) if grounded else 0.0
	roll = lerpf(roll, roll_t, 1.0 - exp(-6.0 * dt))
	pitch = lerpf(pitch, pitch_t, 1.0 - exp(-6.0 * dt))
	bob_v += (-bob * 140.0 - bob_v * 12.0) * dt
	# gravel and dirt make the body chatter a little
	if grounded and surface in [1, 2, 4, 5] and speed > 6.0:
		bob_v += randf_range(-1.0, 1.0) * minf(speed, 40.0) * 0.012
	bob += bob_v * dt
	bob = clampf(bob, -0.25, 0.2)
	model.body.rotation = Vector3(pitch, 0, roll)
	model.body.position.y = bob
	var wa := -steer_s * 0.5
	if drifting:
		wa = clampf(-slip * 0.9, -0.6, 0.6)
	for i in 4:
		var w: Dictionary = model.wheels[i]
		if w.front:
			w.pivot.rotation.y = wa
		var spin_rate: float = vf / w.r
		if not w.front and (drifting or (in_t > 0.8 and absf(vf) < 9.0 and grounded)):
			spin_rate = maxf(spin_rate, 25.0)
		w.spin.rotation.x = wrapf(w.spin.rotation.x - spin_rate * dt, -PI, PI)
		var off := -0.14
		if grounded:
			var wp: Vector3 = transform * Vector3(w.pos.x, 0.0, w.pos.z)
			var gh: float = world.ground(wp.x, wp.z, pos.y + 0.8)
			off = clampf(gh - wp.y, -0.22, 0.28)
		w_off[i] = lerpf(w_off[i], off, 1.0 - exp(-22.0 * dt))
		w.pivot.position.y = w.pos.y + w_off[i]
	if model.has("rig"):
		model.rig.update(self, dt)
	model.brake.emission_energy_multiplier = 4.0 if in_b > 0.1 and vf > 0.5 else (1.6 if lights_on else 0.9)
	var fl := nitro_on and in_nitro
	for f in model.flames:
		f.visible = fl
		if fl:
			f.scale = Vector3.ONE * randf_range(0.8, 1.25)
	var gy: float = world.ground(pos.x, pos.z, pos.y + 0.5)
	var hgt := maxf(0.0, pos.y - gy)
	shadow.global_transform = Transform3D(Basis(right, up, -fw).scaled(Vector3(half_w * 2.6, 1, half_len * 2.3) * (1.0 + hgt * 0.08)), Vector3(pos.x, gy + 0.06, pos.z))
	shadow.transparency = clampf(hgt / 8.0, 0.0, 0.9)


func effects(dt: float) -> void:
	if not fx_near or ghost:
		return
	var f := fwd_flat()
	var rt := Vector3(cos(yaw), 0, -sin(yaw))
	var sliding: bool = grounded and (absf(vr) > 3.5 or drifting or (in_hb and speed > 4.0))
	var spin: bool = grounded and in_t > 0.8 and vf > -1.0 and vf < 9.0
	var braking: bool = grounded and in_b > 0.5 and vf > 8.0
	var rate := 0.0
	var col := Color(0.8, 0.72, 0.6, 0.5)
	var skid_col := Color(0.3, 0.24, 0.18, 0.5)
	var light: Color = fx.light
	match surface:
		0:
			rate = (40.0 if sliding else 0.0) + (25.0 if spin else 0.0)
			col = Color(0.9, 0.9, 0.92, 0.45)
			skid_col = Color(0.05, 0.05, 0.06, 0.55)
			if wet > 0.5:
				rate += speed * 0.6
				col = Color(0.82, 0.86, 0.9, 0.22)
		1:
			rate = speed * 0.55 + (40.0 if sliding else 0.0) + (20.0 if spin else 0.0)
			col = Color(0.72, 0.66, 0.58, 0.5)
			skid_col = Color(0.32, 0.28, 0.22, 0.5)
		2:
			rate = speed * 0.6 + (45.0 if sliding else 0.0) + (25.0 if spin else 0.0)
			col = Color(0.62, 0.48, 0.34, 0.5)
			skid_col = Color(0.26, 0.18, 0.11, 0.55)
			if wet > 0.5:
				col = Color(0.4, 0.3, 0.2, 0.55)
		3:
			rate = speed * 0.9 + (45.0 if sliding else 0.0) + (25.0 if spin else 0.0)
			col = Color(0.92, 0.85, 0.68, 0.5)
			skid_col = Color(0.6, 0.5, 0.36, 0.5)
		4:
			rate = (25.0 if sliding else 0.0) + speed * 0.12
			col = Color(0.45, 0.5, 0.3, 0.35)
			skid_col = Color(0.2, 0.26, 0.1, 0.5)
		5:
			rate = (20.0 if sliding else 0.0) + speed * 0.2
			col = Color(0.7, 0.68, 0.66, 0.4)
		6:
			rate = speed * 3.0 + 10.0
			col = Color(0.88, 0.95, 1.0, 0.65)
		7:
			rate = speed * 0.8 + (40.0 if sliding else 0.0)
			col = Color(0.95, 0.97, 1.0, 0.6)
			skid_col = Color(0.6, 0.65, 0.72, 0.4)
	if not grounded:
		rate = 0.0
	col = Color(col.r * light.r, col.g * light.g, col.b * light.b, col.a)
	if nitro_on:
		for ex in model.flames:
			if randf() < 0.5:
				fx.puff(ex.global_position + f * -0.3, -f * 3.0 + Vector3(0, 0.5, 0), 0.4, 1.5, 0.5, Color(0.5, 0.5, 0.55, 0.3))
	dust_acc += rate * dt
	var wheels: Array = model.wheels
	var n := 0
	while dust_acc >= 1.0 and n < 8:
		dust_acc -= 1.0
		n += 1
		var w: Dictionary = wheels[2 + randi() % 2]
		var wp: Vector3 = w.pivot.global_position
		var v := -f * speed * 0.18 + rt * randf_range(-2.5, 2.5) + Vector3(0, randf_range(1.0, 2.5), 0)
		if surface == 6:
			v = Vector3(randf_range(-3, 3), randf_range(3, 6), randf_range(-3, 3)) + vel * 0.3
		fx.puff(wp + Vector3(0, -0.2, 0), v, randf_range(0.8, 1.5), randf_range(1.8, 3.2), randf_range(1.0, 1.8), col)
	# gravel / dirt stones kicked up
	if grounded and surface in [1, 2] and speed > 10.0 and fx_near and randf() < speed * 0.02:
		var w2: Dictionary = wheels[2 + randi() % 2]
		fx.spark(w2.pivot.global_position, -f * speed * 0.25 + Vector3(randf_range(-2, 2), randf_range(2, 5), randf_range(-2, 2)), 0.12, 0.8, Color(0.35, 0.3, 0.25, 1.0) * Color(light.r, light.g, light.b), 18.0)
	var marking: bool = (sliding or spin or braking) and surface != 6
	for i in 2:
		var w: Dictionary = wheels[2 + i]
		var wp: Vector3 = w.pivot.global_position
		wp.y = world.ground(wp.x, wp.z, pos.y + 0.5)
		if marking:
			if skid_on[i]:
				if wp.distance_to(skid_last[i]) > 0.6:
					fx.skid(skid_last[i], wp, n_s, 0.32, skid_col)
					skid_last[i] = wp
			else:
				skid_on[i] = true
				skid_last[i] = wp
		else:
			skid_on[i] = false
	if ev_splash:
		for k in 36:
			fx.puff(pos + Vector3(randf_range(-1.5, 1.5), 0.3, randf_range(-1.5, 1.5)), Vector3(randf_range(-4, 4), randf_range(4, 9), randf_range(-4, 4)) + vel * 0.2, 0.9, 2.0, 1.2, Color(0.9, 0.97, 1.0, 0.7))


func audio(dt: float) -> void:
	if eng == null:
		return
	var vmax: float = float(def.vmax)
	var frac := clampf(absf(vf) / vmax, 0.0, 1.25)
	var gears := [0.0, 0.18, 0.34, 0.5, 0.67, 0.84, 1.3]
	var g := 0
	while g < gears.size() - 2 and frac > gears[g + 1]:
		g += 1
	gear = g + 1
	var lo: float = gears[g]
	var hi2: float = gears[g + 1]
	var target := clampf((frac - lo) / (hi2 - lo), 0.0, 1.0) * 0.8 + 0.2
	if frozen or (in_t > 0.5 and (drifting or not grounded or absf(vf) < 9.0)):
		target = maxf(target, 0.55 + in_t * 0.4)
	if in_t < 0.05 and absf(vf) < 1.0:
		target = 0.12
	rpm = lerpf(rpm, target, 1.0 - exp(-(9.0 if target > rpm else 5.0) * dt))
	var pitch_s := float(def.engine) * (0.55 + rpm * 0.95) * (1.08 if nitro_on else 1.0)
	eng.pitch_scale = clampf(pitch_s, 0.3, 3.0)
	var vol := lerpf(-12.0, -3.0, clampf(in_t * 0.7 + rpm * 0.3, 0.0, 1.0))
	if eng is AudioStreamPlayer3D:
		eng.volume_db = vol - 2.0
	else:
		eng.volume_db = vol
	if not is_player:
		return
	var slide := absf(vr) + (6.0 if drifting else 0.0)
	var hard := grounded and surface in [0, 5]
	var loose := grounded and surface in [1, 2, 3, 4, 7]
	var sk := clampf((slide - 2.5) / 8.0, 0.0, 1.0) if hard and wet < 0.5 else 0.0
	var sa := clampf((slide - 2.0) / 8.0, 0.0, 1.0) if loose else 0.0
	sa = maxf(sa, clampf(speed / 50.0, 0.0, 0.45) if loose else 0.0)
	if grounded and surface == 0 and wet > 0.5:
		sa = maxf(sa, clampf(speed / 60.0, 0.0, 0.35))
	skid_p.volume_db = linear_to_db(maxf(sk * 0.7, 0.0001))
	skid_p.pitch_scale = 0.9 + clampf(speed / 50.0, 0.0, 0.3)
	sand_p.volume_db = linear_to_db(maxf(sa * 0.8, 0.0001))
	sand_p.pitch_scale = 0.9 + clampf(speed / 60.0, 0.0, 0.4)
	wind_p.volume_db = linear_to_db(maxf(clampf((speed - 8.0) / 45.0, 0.0, 1.0) * 0.45 + (0.25 if not grounded else 0.0), 0.0001))
	nos_p.volume_db = linear_to_db(0.6 if nitro_on and in_nitro else 0.0001)

