extends RefCounted
## Bakes a detailed car model into a few merged meshes for AI cars: all plain-coloured parts become vertex
## colours on two shared materials (matte / metal), the paint keeps its own material (so each car gets its
## colour), textured, glass and light parts are merged per material. Wheels are baked one mesh each.
## The result has the same layout as CarModel.build() so car.gd can drive it. Cached per car id.

const CarModel = preload("res://scripts/carmodel.gd")
const BH = preload("res://scripts/buggy_hq.gd")

static var _cache := {}
static var _vc := {}

const VC_SHADER := """
shader_type spatial;
uniform float metal = 0.0;
uniform float emis = 0.0;
void fragment() {
	ALBEDO = COLOR.rgb * (1.0 - emis * 0.8);
	ROUGHNESS = COLOR.a;
	METALLIC = metal;
	SPECULAR = 0.5;
	EMISSION = COLOR.rgb * emis * 2.0;
}
"""
static var _avg := {}


static func _tex_avg(t: Texture2D) -> Color:
	if _avg.has(t):
		return _avg[t]
	var img := t.get_image()
	var c := Color(0.5, 0.5, 0.5)
	if img != null:
		img = img.duplicate()
		if img.is_compressed():
			img.decompress()
		img.clear_mipmaps()
		img.resize(1, 1, Image.INTERPOLATE_BILINEAR)
		c = img.get_pixel(0, 0)
	_avg[t] = c
	return c


static func _vc_mat(kind: String) -> ShaderMaterial:
	if _vc.has(kind):
		return _vc[kind]
	var sh := Shader.new()
	sh.code = VC_SHADER
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("metal", 1.0 if kind == "metal" else 0.0)
	m.set_shader_parameter("emis", 1.0 if kind == "emis" else 0.0)
	_vc[kind] = m
	return m


class Group:
	var mat: Material
	var st := SurfaceTool.new()
	var cols: Array = []
	var vcol := false
	var started := false


static func build(id: String, col: Color, mid := true) -> Dictionary:
	var key := id + ("_mid" if mid else "_low")
	if not _cache.has(key):
		var src: Dictionary = CarModel.build(id, Color(0.5, 0.5, 0.5), false, mid)
		_cache[key] = _bake(src)
		src.root.free()
	return _instance(_cache[key], col)


static func _bake(src: Dictionary) -> Dictionary:
	var out := {"half_len": src.half_len, "half_w": src.half_w, "cam_h": src.cam_h, "wheels": [], "flames": []}
	var body: Node3D = src.body
	var root: Node3D = src.root
	var skip := {}
	for f in src.flames:
		skip[f] = true
	var paint_src: Material = null
	# body: everything under body except flames
	var groups := {}
	paint_src = _collect(body, body.transform, groups, skip, src.brake)
	out.body_mesh = _commit(groups)
	out.body_xf = body.transform
	out.brake_src = src.brake
	out.paint_src = paint_src
	for w in src.wheels:
		var wg := {}
		_collect(w.spin, Transform3D(), wg, {}, null, true)
		out.wheels.append({"mesh": _commit(wg), "pos": w.pos, "r": w.r, "front": w.front, "pivot_xf": w.pivot.transform})
	for f in src.flames:
		out.flames.append({"node": f.duplicate(), "xf": f.transform})
	return out


## Walks the subtree; returns the paint material it saw (to be replaced per car).
## Geometry is merged natively with SurfaceTool.append_from; vertex colours are stitched per part.
static func _collect(n: Node, xf: Transform3D, groups: Dictionary, skip: Dictionary, brake: Material, one := false) -> Material:
	var paint: Material = null
	if skip.has(n):
		return null
	if n is MeshInstance3D and n.mesh != null and n.visible:
		var mi: MeshInstance3D = n
		for s in mi.mesh.get_surface_count():
			var m: Material = mi.get_surface_override_material(s)
			if m == null:
				m = mi.material_override
			if m == null:
				m = mi.mesh.surface_get_material(s)
			var key = null
			var col := Color(1, 1, 1, 0.6)
			var use_vcol := false
			if m is ShaderMaterial and m.shader == BH._paint_shader:
				key = "paint"
				paint = m
			elif m is ShaderMaterial and m.get_shader_parameter("metal") != null:
				key = "metal" if float(m.get_shader_parameter("metal")) > 0.5 else "diel"
				use_vcol = true
			elif m is StandardMaterial3D:
				var sm: StandardMaterial3D = m
				if m == brake:
					key = m
				elif sm.emission_enabled:
					var ec := (sm.emission * sm.emission_energy_multiplier).srgb_to_linear()
					col = Color(ec.r, ec.g, ec.b, 0.3)
					key = "emis"
				elif sm.albedo_texture != null and (sm.albedo_texture == BH.T("car_livery") or sm.albedo_texture == BH.T("car_decals")):
					key = m
				else:
					var ac := sm.albedo_color
					if sm.albedo_texture != null:
						ac = ac * _tex_avg(sm.albedo_texture)
					var lc := ac.srgb_to_linear()
					col = Color(lc.r, lc.g, lc.b, sm.roughness)
					key = "metal" if sm.metallic > 0.5 or sm.transparency != BaseMaterial3D.TRANSPARENCY_DISABLED else "diel"
			else:
				key = m
			if key == null:
				continue
			if one and key is String:
				key = "diel"
			if not groups.has(key):
				var g := Group.new()
				if key is String:
					g.mat = _vc_mat(key) if key != "paint" else m
					g.vcol = key != "paint"
				else:
					g.mat = m
				g.st.begin(Mesh.PRIMITIVE_TRIANGLES)
				groups[key] = g
			var gr: Group = groups[key]
			gr.st.append_from(mi.mesh, s, xf)
			if gr.vcol:
				var nv: int = mi.mesh.surface_get_array_len(s)
				var vc = null
				if use_vcol:
					vc = mi.mesh.surface_get_arrays(s)[Mesh.ARRAY_COLOR]
				if vc != null and vc.size() == nv:
					gr.cols.append(vc)
				else:
					var ca := PackedColorArray()
					ca.resize(nv)
					ca.fill(col)
					gr.cols.append(ca)
	for c in n.get_children():
		if c is Node3D:
			var p := _collect(c, xf * c.transform, groups, skip, brake, one)
			if p != null:
				paint = p
	return paint


static func _commit(groups: Dictionary) -> ArrayMesh:
	var m := ArrayMesh.new()
	for key in groups:
		var g: Group = groups[key]
		var tmp := g.st.commit()
		if tmp.get_surface_count() == 0:
			continue
		var arr := tmp.surface_get_arrays(0)
		if g.vcol:
			var cc := PackedColorArray()
			for ca in g.cols:
				cc.append_array(ca)
			var nv: int = (arr[Mesh.ARRAY_VERTEX] as PackedVector3Array).size()
			if cc.size() == nv:
				arr[Mesh.ARRAY_COLOR] = cc
		m.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
		m.surface_set_material(m.get_surface_count() - 1, g.mat)
	return m


static func _instance(t: Dictionary, col: Color) -> Dictionary:
	var root := Node3D.new()
	var body := Node3D.new()
	body.name = "body"
	body.transform = t.body_xf
	root.add_child(body)
	var mi := MeshInstance3D.new()
	mi.mesh = t.body_mesh
	var paint := BH.paint(col)
	var brake: StandardMaterial3D = t.brake_src.duplicate()
	for s in t.body_mesh.get_surface_count():
		var m: Material = t.body_mesh.surface_get_material(s)
		if m == t.paint_src and t.paint_src != null:
			mi.set_surface_override_material(s, paint)
		elif m == t.brake_src:
			mi.set_surface_override_material(s, brake)
	body.add_child(mi)
	var wheels := []
	for w in t.wheels:
		var pivot := Node3D.new()
		pivot.transform = w.pivot_xf
		var spin := Node3D.new()
		pivot.add_child(spin)
		var wm := MeshInstance3D.new()
		wm.mesh = w.mesh
		wm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		spin.add_child(wm)
		root.add_child(pivot)
		wheels.append({"pivot": pivot, "spin": spin, "pos": w.pos, "r": w.r, "front": w.front})
	var flames := []
	for f in t.flames:
		var fn: Node3D = f.node.duplicate()
		fn.transform = f.xf
		fn.visible = false
		body.add_child(fn)
		flames.append(fn)
	return {"root": root, "body": body, "wheels": wheels, "brake": brake, "flames": flames,
		"half_len": t.half_len, "half_w": t.half_w, "cam_h": t.cam_h}


## Player car: merge the static mesh children of the body by material (keeps every material and all animated
## nodes: steering wheel, driver, aerial, flames). Cuts draw calls without changing the look.
static func merge_static(model: Dictionary) -> void:
	var body: Node3D = model.body
	var groups := {}
	var order := []
	var remove := []
	for c in body.get_children():
		if not (c is MeshInstance3D) or c.mesh == null or not c.visible:
			continue
		# named nodes are animated (steering wheel, driver arms, head, aerial); only auto-named ones are static
		if not String(c.name).begins_with("@"):
			continue
		var mi: MeshInstance3D = c
		var shadow := mi.cast_shadow != GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		for s in mi.mesh.get_surface_count():
			var m: Material = mi.get_surface_override_material(s)
			if m == null:
				m = mi.material_override
			if m == null:
				m = mi.mesh.surface_get_material(s)
			var key := [m, shadow]
			var k2 := str(m.get_instance_id() if m != null else 0) + ("s" if shadow else "n")
			if not groups.has(k2):
				var st := SurfaceTool.new()
				st.begin(Mesh.PRIMITIVE_TRIANGLES)
				groups[k2] = {"st": st, "mat": m, "shadow": shadow}
				order.append(k2)
			groups[k2].st.append_from(mi.mesh, s, mi.transform)
		remove.append(mi)
	if remove.size() <= 1:
		return
	var meshes := {true: ArrayMesh.new(), false: ArrayMesh.new()}
	for k2 in order:
		var g: Dictionary = groups[k2]
		var tmp: ArrayMesh = g.st.commit()
		if tmp.get_surface_count() == 0:
			continue
		var am: ArrayMesh = meshes[g.shadow]
		am.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, tmp.surface_get_arrays(0))
		am.surface_set_material(am.get_surface_count() - 1, g.mat)
	for mi in remove:
		body.remove_child(mi)
		mi.queue_free()
	for sh in [true, false]:
		var am: ArrayMesh = meshes[sh]
		if am.get_surface_count() == 0:
			continue
		var nm := MeshInstance3D.new()
		nm.mesh = am
		nm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if sh else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		body.add_child(nm)

files.scripts/cars_hq.gd:
extends RefCounted
## High-detail versions of the closed cars (Patrol, Drifter, Muscle, Rally, Falcon).
## Bodies are smooth lofts (monotone-cubic between sections) with carved wheel arches, flared fenders,
## see-through windows with an interior, seams, lights, grilles, liveries and detailed wheels.
## full = true for the player's car (interior + driver + all trim); false is the lighter AI version.

const Mk = preload("res://scripts/mk.gd")
const BH = preload("res://scripts/buggy_hq.gd")

const A_LO := -PI / 2
const A_HI := PI * 1.5


# ================================================================== body shape
class Shape extends RefCounted:
	var secs := []
	var arches := []
	var flare := 0.0
	var hump := 0.0
	var z0 := 0.0
	var z1 := 0.0
	var slopes := []
	var upper := false

	func setup(s: Array) -> Shape:
		secs = s.duplicate()
		secs.sort_custom(func(a, b): return a[0] < b[0])
		z0 = secs[0][0]
		z1 = secs[secs.size() - 1][0]
		var n := secs.size()
		slopes = []
		for k in range(1, 6):
			var m := []
			var d := []
			for i in n - 1:
				d.append((float(secs[i + 1][k]) - float(secs[i][k])) / (float(secs[i + 1][0]) - float(secs[i][0])))
			for i in n:
				if i == 0:
					m.append(d[0])
				elif i == n - 1:
					m.append(d[n - 2])
				elif d[i - 1] * d[i] <= 0.0:
					m.append(0.0)
				else:
					var h0: float = float(secs[i][0]) - float(secs[i - 1][0])
					var h1: float = float(secs[i + 1][0]) - float(secs[i][0])
					var w1 := 2.0 * h1 + h0
					var w2 := h1 + 2.0 * h0
					m.append((w1 + w2) / (w1 / d[i - 1] + w2 / d[i]))
			slopes.append(m)
		return self

	func zs() -> Array:
		var out := []
		for s in secs:
			out.append(float(s[0]))
		return out

	var _pc := {}

	func params(z: float) -> Array:
		z = clampf(z, z0, z1)
		if _pc.has(z):
			return _pc[z]
		var out := _params(z)
		if _pc.size() < 20000:
			_pc[z] = out
		return out

	func _params(z: float) -> Array:
		var i := 0
		while i < secs.size() - 2 and z > float(secs[i + 1][0]):
			i += 1
		var za: float = secs[i][0]
		var zb: float = secs[i + 1][0]
		var h := zb - za
		var t := (z - za) / h
		var t2 := t * t
		var t3 := t2 * t
		var out := []
		for k in range(1, 6):
			var ya: float = secs[i][k]
			var yb: float = secs[i + 1][k]
			var ma: float = slopes[k - 1][i]
			var mb: float = slopes[k - 1][i + 1]
			out.append((2 * t3 - 3 * t2 + 1) * ya + (t3 - 2 * t2 + t) * h * ma + (-2 * t3 + 3 * t2) * yb + (t3 - t2) * h * mb)
		return out

	func point(z: float, a: float, cut := true) -> Vector3:
		var q := params(z)
		var y0: float = q[0]
		var y1: float = q[1]
		var wb: float = q[2]
		var wt: float = q[3]
		var e := lerpf(2.0, 6.0, 1.0 - clampf(q[4], 0.0, 1.0))
		var ca := cos(a)
		var sa := sin(a)
		var px := signf(ca) * pow(absf(ca), 2.0 / e)
		var py := signf(sa) * pow(absf(sa), 2.0 / e)
		var y: float
		var w: float
		if upper:
			## greenhouse: a in [0, PI] maps belt (py = 0) to roof (py = 1); below 0 a short skirt tucks inward
			if a < 0.0 or a > PI:
				var t := clampf((-a if a < 0.0 else a - PI) / 0.2, 0.0, 1.0)
				return Vector3((1.0 if a < 0.0 else -1.0) * wb * (1.0 - 0.12 * t), y0 - 0.16 * t, z)
			y = y0 + py * (y1 - y0)
			w = lerpf(wb, wt, py)
		else:
			y = (y0 + y1) * 0.5 + py * (y1 - y0) * 0.5
			w = lerpf(wb, wt, (py + 1.0) * 0.5)
		var x := px * w
		for ar in arches:
			var dz: float = z - float(ar[0])
			var r: float = ar[2]
			var ring_d := sqrt(dz * dz + pow(maxf(0.0, y - float(ar[1])), 2.0))
			if flare > 0.0 and absf(px) > 0.5:
				var edge := absf(ring_d - r - 0.07)
				x *= 1.0 + flare * exp(-edge * edge / 0.012) * smoothstep(0.5, 0.95, absf(px))
			if absf(dz) < r:
				var ya: float = float(ar[1]) + sqrt(r * r - dz * dz)
				if hump > 0.0 and py >= -0.2 and absf(px) > 0.55:
					y = maxf(y, lerpf(y, ya + hump, smoothstep(0.55, 0.9, absf(px)) * smoothstep(r, r * 0.3, absf(dz))))
				if cut and py < 0.55 and y < ya:
					y = ya
		return Vector3(x, y, z)

	func normal(z: float, a: float) -> Vector3:
		var p := point(z, a)
		## points pushed onto an arch edge keep the panel's own shading
		var cut := absf(p.y - point(z, a, false).y) < 1e-5
		var dz := point(z + 0.01, a, cut) - point(z - 0.01, a, cut)
		var da := point(z, a + 0.01, cut) - point(z, a - 0.01, cut)
		var n := da.cross(dz)
		if n.length_squared() < 1e-12:
			n = Vector3(signf(p.x), 0.0, 0.0) if absf(p.x) > 0.01 else Vector3.UP
		n = n.normalized()
		var q := params(z)
		var c := Vector3(0, (float(q[0]) + float(q[1])) * 0.5 if not upper else float(q[0]) - 0.3, z)
		if n.dot(p - c) < 0.0:
			n = -n
		return n


static func shape(secs: Array, arches := [], flare := 0.0, hump := 0.0) -> Shape:
	var s := Shape.new()
	s.arches = arches
	s.flare = flare
	s.hump = hump
	return s.setup(secs)


## Greenhouse: sections [z, belt_y, roof_y, half_w_belt, half_w_roof, round]; a in [0, PI] runs belt-right, roof, belt-left.
static func cab(secs: Array) -> Shape:
	var s := Shape.new()
	s.upper = true
	return s.setup(secs)


## Window rectangles on a greenhouse in (z, a) space.
const SIDE_A := Vector2(0.03, 0.62)
const TOP_A := Vector2(0.86, PI - 0.86)


static func win_sides(z0: float, z1: float, top := SIDE_A.y) -> Array:
	return [[z0, z1, SIDE_A.x, top], [z0, z1, PI - top, PI - SIDE_A.x]]


static func win_top(z0: float, z1: float) -> Array:
	return [[z0, z1, TOP_A.x, TOP_A.y]]


## level of detail: 1 = player car, larger = coarser sampling (AI cars)
static var S := 1.0


static func samples(lo: float, hi: float, step: float, cuts := []) -> Array:
	var out := []
	var n := maxi(1, int(ceil((hi - lo) / (step * S))))
	for i in n + 1:
		out.append(lerpf(lo, hi, float(i) / n))
	for c in cuts:
		if c > lo + 1e-4 and c < hi - 1e-4:
			out.append(c)
	out.sort()
	var uniq := []
	for v in out:
		if uniq.is_empty() or absf(v - uniq[-1]) > 1e-4:
			uniq.append(v)
	return uniq


## Surface grid over (z, a) samples; keep(zc, ac, p) decides each cell. off pushes along the normal.
static func surf(sh: Shape, zs: Array, as_: Array, off := 0.0, keep: Callable = Callable(), uvmode := 0) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var nz := zs.size()
	var na := as_.size()
	for i in nz:
		for j in na:
			var z: float = zs[i]
			var a: float = as_[j]
			var nn := sh.normal(z, a)
			v.append(sh.point(z, a) + nn * off)
			n.append(nn)
			uv.append(Vector2(z, a) if uvmode == 0 else Vector2(float(j) / (na - 1), float(i) / (nz - 1)))
	for i in nz - 1:
		for j in na - 1:
			if keep.is_valid():
				var zc: float = (zs[i] + zs[i + 1]) * 0.5
				var ac: float = (as_[j] + as_[j + 1]) * 0.5
				if not keep.call(zc, ac, sh.point(zc, ac)):
					continue
			var a0 := i * na + j
			BH._tri(idx, v, n, a0, a0 + 1, a0 + na)
			BH._tri(idx, v, n, a0 + 1, a0 + na + 1, a0 + na)
	return BH._mesh(v, n, uv, idx)


## End caps closing a full-ring loft.
static func caps(sh: Shape, as_: Array) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	for e: float in [sh.z0, sh.z1]:
		var q := sh.params(e)
		var dirn := Vector3(0, 0, -1) if e == sh.z0 else Vector3(0, 0, 1)
		var c := v.size()
		v.append(Vector3(0, (float(q[0]) + float(q[1])) * 0.5, e))
		n.append(dirn)
		uv.append(Vector2.ZERO)
		var r0 := v.size()
		for a in as_:
			v.append(sh.point(e, a))
			n.append(dirn)
			uv.append(Vector2.ZERO)
		for j in as_.size() - 1:
			BH._tri(idx, v, n, c, r0 + j, r0 + j + 1)
	return BH._mesh(v, n, uv, idx)


## A sticker mapped onto the body surface (conforms to curvature).
## mode 0: right side, 1: left side (both read front to back as seen from that side), 2: top, readable from behind.
static func decal(sh: Shape, rect: Rect2, atlas: Vector2, za: float, zb: float, aa: float, ab: float, mode: int, off := 0.004) -> ArrayMesh:
	var zs := samples(za, zb, 0.04)
	var as_ := samples(aa, ab, 0.04)
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var na := as_.size()
	for i in zs.size():
		for j in na:
			var z: float = zs[i]
			var a: float = as_[j]
			var nn := sh.normal(z, a)
			v.append(sh.point(z, a) + nn * off)
			n.append(nn)
			var fu := (z - za) / (zb - za)
			var fv := (a - aa) / (ab - aa)
			if mode == 0:
				fu = 1.0 - fu
				fv = 1.0 - fv
			elif mode == 2:
				var t := fu
				fu = 1.0 - fv
				fv = t
			uv.append(Vector2((rect.position.x + fu * rect.size.x) / atlas.x, (rect.position.y + fv * rect.size.y) / atlas.y))
	for i in zs.size() - 1:
		for j in na - 1:
			var a0 := i * na + j
			BH._tri(idx, v, n, a0, a0 + 1, a0 + na)
			BH._tri(idx, v, n, a0 + 1, a0 + na + 1, a0 + na)
	return BH._mesh(v, n, uv, idx)


## a value on the ring where the surface reaches height y at z (searching the right side, from the bottom up)
static func a_at_y(sh: Shape, z: float, y: float, right := true) -> float:
	var lo := -PI / 2 + 0.001
	var hi := PI / 2 - 0.001
	for k in 30:
		var m := (lo + hi) * 0.5
		if sh.point(z, m).y < y:
			lo = m
		else:
			hi = m
	var a := (lo + hi) * 0.5
	return a if right else PI - a


static func on(sh: Shape, z: float, a: float, off := 0.0) -> Transform3D:
	## transform at a surface point: +Z out of the surface, +Y roughly up
	var p := sh.point(z, a)
	var nn := sh.normal(z, a)
	var up := Vector3.UP if absf(nn.y) < 0.9 else Vector3.BACK
	var x := up.cross(nn).normalized()
	var y := nn.cross(x)
	return Transform3D(Basis(x, y, nn), p + nn * off)


