# ================================================================== wheels
## Road wheel parts around the Y axis (outer face +Y). design: fivespoke | mesh | dish | turbine | offroad
static func wheel_parts(r: float, w: float, rim_r: float, design: String, rim_col: Color, text := true, knobby := false) -> Array:
	var parts := []
	var half := w * 0.5
	var rubber := BH.TM("road_rubber", "car_road_n", Color(0.07, 0.07, 0.075), 0.88, 0.0, 10.0, true)
	if knobby:
		rubber = BH.TM("rubber", "car_tread_n", Color(0.075, 0.075, 0.08), 0.9, 0.0, 14.0, true)
	var side_m := StandardMaterial3D.new()
	side_m.albedo_texture = BH.T("car_tyre")
	side_m.roughness = 0.88
	var segs := int(64 / S)
	# tread band with shoulders
	parts.append([BH.lathe([Vector2(r - 0.03, -half + 0.005), Vector2(r - 0.008, -half + 0.02), Vector2(r, -half + 0.045), Vector2(r, half - 0.045),
		Vector2(r - 0.008, half - 0.02), Vector2(r - 0.03, half - 0.005)], segs, true), Transform3D(), rubber])
	# grooves (dark rings) on road tyres
	if not knobby:
		for gx: float in [-0.45, -0.15, 0.15, 0.45]:
			parts.append([BH.lathe([Vector2(r + 0.0005, gx * w - 0.006), Vector2(r + 0.0005, gx * w + 0.006)], segs), Transform3D(), BH.V("diel", Color(0.02, 0.02, 0.02), 0.95)])
	# sidewalls
	var mid := (rim_r + r) * 0.5
	for sgn in [-1.0, 1.0]:
		var prof := [Vector2(rim_r, sgn * (half - 0.02)), Vector2(mid - 0.02, sgn * (half + 0.004)), Vector2(mid + 0.03, sgn * (half + 0.006)), Vector2(r - 0.03, sgn * (half - 0.005))]
		if sgn > 0:
			prof.reverse()
		parts.append([BH.lathe(prof, segs, true), Transform3D(), side_m if (sgn > 0 and text) else rubber])
	if knobby and S <= 1.0:
		var knob := BH.slab(Vector3(w * 0.32, 0.026, 0.06), 0.35, 8)
		var n_k := int(TAU * r / 0.1)
		for row: float in [-1.0, 1.0]:
			for k in n_k:
				var aa := TAU * (k + (0.5 if row > 0 else 0.0)) / n_k
				var radial := Vector3(cos(aa), 0, sin(aa))
				parts.append([knob, Transform3D(Basis(Vector3.UP, -aa) * Basis(Vector3.BACK, PI / 2), radial * (r + 0.008) + Vector3(0, row * w * 0.22, 0)), rubber])
	# rim barrel + lip
	var rimm := BH.V("metal", rim_col, 0.22)
	var lipm := BH.V("metal", rim_col.lightened(0.25) if design != "dish" else Color(0.85, 0.86, 0.88), 0.12)
	parts.append([BH.lathe([Vector2(rim_r + 0.008, -half + 0.01), Vector2(rim_r - 0.02, -half + 0.03), Vector2(rim_r - 0.02, half - 0.05), Vector2(rim_r + 0.006, half - 0.01),
		Vector2(rim_r + 0.012, half - 0.004)], int(48 / S)), Transform3D(), rimm])
	parts.append([BH.lathe([Vector2(rim_r - 0.04, half - 0.012), Vector2(rim_r + 0.012, half - 0.012), Vector2(rim_r + 0.014, half + 0.002), Vector2(rim_r - 0.04, half + 0.002)], int(48 / S)), Transform3D(), lipm])
	var face_y := half - 0.03
	var hub_r := rim_r * 0.28
	match design:
		"fivespoke":
			for k in 5:
				var aa := TAU * k / 5.0
				for off: float in [-0.07, 0.07]:
					var sp := BH.slab(Vector3(0.045, 0.035, rim_r - hub_r), 0.5, 10 if S <= 1.0 else 6)
					parts.append([sp, Transform3D(Basis(Vector3.UP, -(aa + off) + PI / 2) * Basis(Vector3.RIGHT, -0.08), Vector3(cos(aa + off), 0, sin(aa + off)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y, 0)), rimm])
		"mesh":
			for k in 10:
				var aa := TAU * k / 10.0
				for tw: float in [-0.35, 0.35]:
					var sp := BH.slab(Vector3(0.016, 0.022, rim_r - hub_r), 0.5, 8 if S <= 1.0 else 5)
					parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2 + tw), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y - 0.01, 0)), rimm])
			for k in (20 if S <= 1.0 else 0):
				var aa := TAU * k / 20.0
				parts.append([Mk.cyl(0.006, 0.006, 0.01, 6), Mk.xf(Vector3(cos(aa) * (rim_r - 0.012), half, sin(aa) * (rim_r - 0.012))), BH.V("metal", Color(0.9, 0.9, 0.92), 0.1)])
		"dish":
			parts.append([BH.lathe([Vector2(hub_r, face_y - 0.07), Vector2(rim_r - 0.035, face_y - 0.07), Vector2(rim_r - 0.035, face_y - 0.055), Vector2(hub_r, face_y - 0.055)], int(40 / S)), Transform3D(), rimm])
			for k in 6:
				var aa := TAU * k / 6.0
				var sp := BH.slab(Vector3(0.05, 0.03, rim_r * 0.6 - hub_r), 0.5, 10 if S <= 1.0 else 6)
				parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r * 0.6 - hub_r) * 0.5) + Vector3(0, face_y - 0.06, 0)), rimm])
		"turbine":
			for k in 14:
				var aa := TAU * k / 14.0
				var sp := BH.slab(Vector3(0.022, 0.03, rim_r - hub_r), 0.4, 8 if S <= 1.0 else 5)
				parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2 + 0.45) * Basis(Vector3.FORWARD, 0.35), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y, 0)), rimm])
		_:
			for k in 6:
				var aa := TAU * k / 6.0
				var sp := BH.slab(Vector3(0.06, 0.035, rim_r - hub_r), 0.45, 10 if S <= 1.0 else 6)
				parts.append([sp, Transform3D(Basis(Vector3.UP, -aa + PI / 2), Vector3(cos(aa), 0, sin(aa)) * (hub_r + (rim_r - hub_r) * 0.5) + Vector3(0, face_y, 0)), rimm])
			for k in (12 if S <= 1.0 else 0):
				var aa := TAU * k / 12.0
				parts.append([Mk.cyl(0.008, 0.008, 0.012, 6), Mk.xf(Vector3(cos(aa) * (rim_r - 0.02), half - 0.004, sin(aa) * (rim_r - 0.02))), BH.V("metal", Color(0.9, 0.9, 0.92), 0.1)])
	# hub, centre cap, nuts
	parts.append([BH.lathe([Vector2(0.0, face_y - 0.02), Vector2(hub_r, face_y - 0.02), Vector2(hub_r, face_y + 0.015), Vector2(hub_r * 0.7, face_y + 0.03), Vector2(0.0, face_y + 0.035)], int(32 / S)), Transform3D(), rimm])
	var cap_col := Color(0.92, 0.92, 0.94) if design != "turbine" else Color(0.9, 0.12, 0.1)
	parts.append([BH.lathe([Vector2(0.0, face_y + 0.03), Vector2(hub_r * 0.55, face_y + 0.03), Vector2(hub_r * 0.45, face_y + 0.045), Vector2(0.0, face_y + 0.05)], int(24 / S)), Transform3D(), BH.V("metal", cap_col, 0.1)])
	if design != "turbine":
		for k in 5:
			var aa := TAU * k / 5.0
			parts.append([Mk.cyl(0.009, 0.011, 0.02, 6), Mk.xf(Vector3(cos(aa) * hub_r * 0.75, face_y + 0.025, sin(aa) * hub_r * 0.75)), BH.V("metal", Color(0.85, 0.86, 0.88), 0.15)])
	# brake disc (spins with the wheel), inboard
	parts.append([BH.lathe([Vector2(rim_r * 0.35, -0.012), Vector2(rim_r * 0.82, -0.012), Vector2(rim_r * 0.82, 0.012), Vector2(rim_r * 0.35, 0.012)], int(40 / S)), Mk.xf(Vector3(0, half - 0.12, 0)), BH.V("metal", Color(0.42, 0.42, 0.44), 0.4)])
	parts.append([Mk.cyl(rim_r * 0.36, rim_r * 0.36, 0.05, 16), Mk.xf(Vector3(0, half - 0.1, 0)), BH.V("metal", Color(0.15, 0.15, 0.16), 0.4)])
