## Headlights moulded into the body surface: glossy black housing patch, two projector lenses, LED strip
## along the lower edge. Right side uses a in [a0, a1]; mirrored to the left.
static func lamp_patch(deco: Array, sh: Shape, z0: float, z1: float, a0: float, a1: float, led, drl, lens_r := 0.045) -> void:
	var housing := BH.V("diel", Color(0.02, 0.02, 0.025), 0.08)
	var chrome := BH.V("metal", Color(0.92, 0.92, 0.94), 0.05)
	for right: bool in [true, false]:
		var aa := a0 if right else PI - a1
		var ab := a1 if right else PI - a0
		deco.append([surf(sh, samples(z0, z1, 0.02), samples(aa, ab, 0.02), 0.004), Transform3D(), housing])
		var ad := [a0, a0 + 0.035] if right else [PI - a0 - 0.035, PI - a0]
		deco.append([surf(sh, samples(z0 + 0.01, z1 - 0.01, 0.02), samples(ad[0], ad[1], 0.012), 0.007), Transform3D(), drl])
		var am := (aa + ab) * 0.5 + (0.01 if right else -0.01)
		for f: float in [0.3, 0.7]:
			var t := on(sh, lerpf(z0, z1, f), am, 0.005)
			deco.append([BH.lathe([Vector2(0.0, -0.01), Vector2(lens_r * 1.25, -0.01), Vector2(lens_r * 1.35, 0.006), Vector2(lens_r * 1.15, 0.006)], 18), t * Transform3D(Basis(Vector3.RIGHT, PI / 2), Vector3.ZERO), chrome])
			deco.append([Mk.sphere(lens_r, lens_r * 1.1, 14, 7), t, led])


