		var a := PI / 2 + k * TAU / 3.0
		p.append([BH.tube([Vector3.ZERO, Vector3(cos(a) * 0.155, 0, sin(a) * 0.155)], 0.014, 8, false), Transform3D(), BH.V("metal", Color(0.3, 0.3, 0.32), 0.3)])
	p.append([BH.lathe([Vector2(0, -0.03), Vector2(0.05, -0.03), Vector2(0.055, 0.0), Vector2(0.035, 0.02), Vector2(0, 0.024)], 20), Transform3D(), BH.V("diel", Color(0.08, 0.08, 0.09), 0.5)])
