class CarRig extends RefCounted:
	var steering: Node3D
	var steer_basis := Basis()
	var head: Node3D
	var arms := []
	var aerial: Node3D
	var t := 0.0
	var sway := Vector2.ZERO
	var sway_v := Vector2.ZERO

	func _place_between(node: Node3D, a: Vector3, b: Vector3) -> void:
		var d := b - a
		var l := d.length()
		if l < 1e-4:
			return
		var y := d / l
		var x := y.cross(Vector3.FORWARD if absf(y.z) < 0.9 else Vector3.RIGHT).normalized()
		var z := x.cross(y)
		node.transform = Transform3D(Basis(x, y * l, z), a)

	func update(car, dt: float) -> void:
		t += dt
		if steering != null:
			var ang: float = -car.steer_s * 2.2 if not car.drifting else clampf(car.slip * 3.0, -2.4, 2.4)
			steering.basis = steer_basis * Basis(Vector3.UP, ang)
			for a in arms:
				_ik(a, a.shoulder, steering.transform * Vector3(a.s * 0.165, 0.0, 0.0))
		if head != null:
			var look: float = -car.steer_s * 0.35
			if car.drifting:
				look = clampf(car.slip * 0.9, -0.6, 0.6)
			head.rotation.y = lerpf(head.rotation.y, look, 1.0 - exp(-6.0 * dt))
			head.rotation.z = lerpf(head.rotation.z, clampf(car.yaw_rate * car.speed * 0.004, -0.15, 0.15), 1.0 - exp(-5.0 * dt))
		if aerial != null:
			var lean := Vector2(clampf(car.yaw_rate * car.speed * 0.006, -0.3, 0.3), clampf(car.long_acc * 0.008 - car.speed * 0.003, -0.35, 0.3))
			sway_v += (lean - sway) * 70.0 * dt
			sway_v *= exp(-3.5 * dt)
			sway += sway_v * dt
			sway = sway.clamp(Vector2(-0.45, -0.45), Vector2(0.45, 0.45))
			aerial.rotation = Vector3(sway.y + sin(t * 3.1) * 0.01, 0, sway.x + sin(t * 2.3) * 0.012)

	func _ik(a: Dictionary, s: Vector3, h: Vector3) -> void:
		var l1 := 0.3
		var l2 := 0.28
		var d := h - s
		var dist := clampf(d.length(), 0.05, l1 + l2 - 0.001)
		var dir := d.normalized()
		var ca := clampf((l1 * l1 + dist * dist - l2 * l2) / (2.0 * l1 * dist), -1.0, 1.0)
		var ang := acos(ca)
		var pole := Vector3(a.s * 0.8, -1.0, 0.25).normalized()
		var bend := (pole - dir * pole.dot(dir)).normalized()
		var elbow := s + dir * cos(ang) * l1 + bend * sin(ang) * l1
		_place_between(a.upper, s, elbow)
		_place_between(a.fore, elbow, h)
		a.hand.position = h


# ================================================================== assembly shared by every car
static func glass_dark() -> StandardMaterial3D:
	var k := "cq_glass_dark"
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_color = Color(0.03, 0.04, 0.055)
	m.metallic = 0.7
	m.roughness = 0.04
	BH._mats[k] = m
	return m


## spec keys: wr, wrf, ww, track, wb, rim_r, design, rim_col, caliper, len, cam_h, knobby
static func assemble(parts: Array, deco: Array, livery: Array, tails: Array, spec: Dictionary, full: bool, exhausts: Array) -> Dictionary:
	var root := Node3D.new()
	var body := Node3D.new()
	body.name = "body"
	root.add_child(body)
	var bm := MeshInstance3D.new()
	bm.mesh = BH.combine(parts)
	body.add_child(bm)
	for set in [deco, livery]:
		if not set.is_empty():
			var dm := MeshInstance3D.new()
			dm.mesh = BH.combine(set)
			dm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
			body.add_child(dm)
	var brake := StandardMaterial3D.new()
	brake.albedo_color = Color(0.6, 0.02, 0.02)
	brake.emission_enabled = true
	brake.emission = Color(1.0, 0.05, 0.03)
	brake.emission_energy_multiplier = 0.9
	if not tails.is_empty():
		var tp := []
		for t in tails:
			tp.append([t[0], t[1], brake])
		var tm := MeshInstance3D.new()
		tm.mesh = BH.combine(tp)
		tm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		body.add_child(tm)
	# wheels
	var wr: float = spec.wr
	var wf: float = spec.get("wrf", wr)
	var ww: float = spec.ww
	var rim_r: float = spec.rim_r
	var knobby: bool = spec.get("knobby", false)
	var rear_mesh := BH.combine(wheel_parts(wr, ww, rim_r, spec.design, spec.rim_col, full, knobby))
	var front_mesh := rear_mesh
	if not is_equal_approx(wf, wr):
		front_mesh = BH.combine(wheel_parts(wf, ww * 0.92, rim_r * wf / wr, spec.design, spec.rim_col, full, knobby))
	var cal_col: Color = spec.get("caliper", Color(0.85, 0.08, 0.05))
	var wheels := []
	for k in 4:
		var front := k < 2
		var side := -1.0 if k % 2 == 0 else 1.0
		var r := wf if front else wr
		var pos := Vector3(side * spec.track * 0.5, r, (-1.0 if front else 1.0) * spec.wb * 0.5)
		var pivot := Node3D.new()
		pivot.name = "w%d" % k
		pivot.position = pos
		var spin := Node3D.new()
		spin.name = "spin"
		pivot.add_child(spin)
		var wmi := MeshInstance3D.new()
		wmi.mesh = front_mesh if front else rear_mesh
		wmi.rotation = Vector3(0, 0 if side > 0 else PI, -PI / 2)
		spin.add_child(wmi)
		var rr := rim_r * (r / wr)
		var wwk := ww * (0.92 if front and not is_equal_approx(wf, wr) else 1.0)
		var cal := MeshInstance3D.new()
		cal.mesh = BH.combine([[BH.slab(Vector3(0.07, 0.06, rr * 0.55), 0.6, 10), Transform3D(Basis(Vector3.RIGHT, 0.45), Vector3(side * (wwk * 0.5 - 0.135), rr * 0.62, rr * 0.3)), BH.V("metal", cal_col, 0.3)]])
		cal.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		pivot.add_child(cal)
		root.add_child(pivot)
		wheels.append({"pivot": pivot, "spin": spin, "pos": pos, "r": r, "front": front})
	# nitro flames at the exhausts
	var flames := []
	var fm := StandardMaterial3D.new()
	fm.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	fm.transparency = BaseMaterial3D.TRANSPARENCY_ALPHA
	fm.blend_mode = BaseMaterial3D.BLEND_MODE_ADD
	fm.albedo_color = Color(0.4, 0.6, 1.0, 0.9)
	fm.cull_mode = BaseMaterial3D.CULL_DISABLED
	var fm2: StandardMaterial3D = fm.duplicate()
	fm2.albedo_color = Color(1.0, 0.55, 0.15, 0.85)
	for ex in exhausts:
		var f := Node3D.new()
		f.name = "f%d" % flames.size()
		f.position = ex
		for layer in [[0.07, 0.6, fm, 0.3], [0.14, 1.1, fm2, 0.55]]:
			var mi := MeshInstance3D.new()
			mi.mesh = Mk.cyl(0.0, layer[0], layer[1], 10)
			mi.material_override = layer[2]
			mi.rotation.x = -PI / 2
			mi.position.z = layer[3]
			mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
			f.add_child(mi)
		f.visible = false
		body.add_child(f)
		flames.append(f)
	return {"root": root, "body": body, "wheels": wheels, "brake": brake, "flames": flames, "rig": CarRig.new(),
		"half_len": spec.len * 0.5, "half_w": spec.track * 0.5 + 0.2, "cam_h": spec.cam_h}


## Lower body + greenhouse with windows. Full detail cuts the floor open under the greenhouse and adds a dark
## interior (tub, headliner) so the seats, dash and driver show through the glass; the AI version has solid tinted glass.
static func shell(parts: Array, deco: Array, lower: Shape, cabin: Shape, P, windows: Array, cab_z: Vector2, hole_w: float, full: bool) -> void:
	var as_full := samples(A_LO, A_HI, 0.07)
	var zs_low := samples(lower.z0, lower.z1, 0.04, lower.zs())
	var keep_low := Callable()
	if full:
		keep_low = func(zc: float, _ac: float, p: Vector3) -> bool:
			return not (zc > cab_z.x and zc < cab_z.y and p.y > float(lower.params(zc)[1]) - 0.05 and absf(p.x) < hole_w)
	parts.append([surf(lower, zs_low, as_full, 0.0, keep_low), Transform3D(), P])
	parts.append([caps(lower, as_full), Transform3D(), P])
	# wheel-well liners so nothing shows through the arches
	var liner := interior_mat()
	for ar in lower.arches:
		var q := lower.params(float(ar[0]))
		var xo: float = maxf(float(q[2]), float(q[3])) * 0.985
		for s: float in [-1.0, 1.0]:
			parts.append([_well(float(ar[0]), float(ar[1]), float(ar[2]) - 0.006, s * 0.42, s * xo), Transform3D(), liner])
	# greenhouse, windows cut exactly on their bounds
	var zc_cuts := cabin.zs()
	var a_cuts := []
	for w in windows:
		zc_cuts.append_array([w[0], w[1]])
		a_cuts.append_array([w[2], w[3]])
	var zs_c := samples(cabin.z0, cabin.z1, 0.04, zc_cuts)
	var as_c := samples(-0.2, PI + 0.2, 0.05, a_cuts + [0.0, PI])
	var in_win := func(zc: float, ac: float) -> bool:
		for w in windows:
			if zc > w[0] and zc < w[1] and ac > w[2] and ac < w[3]:
				return true
		return false
	var keep_cab := func(zc: float, ac: float, _p: Vector3) -> bool:
		return not in_win.call(zc, ac)
	var keep_glass := func(zc: float, ac: float, _p: Vector3) -> bool:
		return in_win.call(zc, ac)
	parts.append([surf(cabin, zs_c, as_c, 0.0, keep_cab), Transform3D(), P])
	parts.append([surf(cabin, zs_c, as_c, 0.0, keep_glass), Transform3D(), glass() if full else glass_dark()])
	# black seals around every window
	var seal := BH.V("diel", Color(0.02, 0.02, 0.025), 0.4)
	for w in windows:
		for edge in [[w[0], w[1], w[2], w[2] + 0.022], [w[0], w[1], w[3] - 0.022, w[3]], [w[0], minf(w[0] + 0.014, w[1]), w[2], w[3]], [maxf(w[1] - 0.014, w[0]), w[1], w[2], w[3]]]:
			deco.append([surf(cabin, samples(edge[0], edge[1], 0.04), samples(edge[2], edge[3], 0.02), 0.003), Transform3D(), seal])
	if full:
		# headliner and pillars from the inside
		parts.append([surf(cabin, zs_c, as_c, -0.012, keep_cab), Transform3D(), liner])
		# tub: floor, side walls, firewall, rear bulkhead
		var y_floor := float(lower.params((cab_z.x + cab_z.y) * 0.5)[0]) + 0.14
		var y_belt := float(lower.params(cab_z.x)[1])
		var y_belt2 := float(lower.params(cab_z.y)[1])
		var len := cab_z.y - cab_z.x
		var zc := (cab_z.x + cab_z.y) * 0.5
		parts.append([BH.slab(Vector3(hole_w * 2.0, 0.03, len), 0.3, 8), Mk.xf(Vector3(0, y_floor, zc)), liner])
		for s: float in [-1.0, 1.0]:
			parts.append([BH.slab(Vector3(0.03, maxf(y_belt, y_belt2) - y_floor, len), 0.3, 8), Mk.xf(Vector3(s * (hole_w + 0.01), (maxf(y_belt, y_belt2) + y_floor) * 0.5, zc)), liner])
		parts.append([BH.slab(Vector3(hole_w * 2.0, y_belt - y_floor + 0.05, 0.03), 0.3, 8), Mk.xf(Vector3(0, (y_belt + y_floor) * 0.5, cab_z.x)), liner])
		parts.append([BH.slab(Vector3(hole_w * 2.0, y_belt2 - y_floor + 0.05, 0.03), 0.3, 8), Mk.xf(Vector3(0, (y_belt2 + y_floor) * 0.5, cab_z.y)), liner])


## Half-cylinder wheel-well roof from x0 to x1 over an arch.
static func _well(zc: float, yc: float, r: float, x0: float, x1: float) -> ArrayMesh:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var idx := PackedInt32Array()
	var segs := 20
	for k in segs + 1:
		var t := PI * k / segs
		var d := Vector3(0, sin(t), -cos(t))
		for x: float in [x0, x1]:
			v.append(Vector3(x, yc, zc) + d * r)
			n.append(-d)
			uv.append(Vector2.ZERO)
	for k in segs:
		var a := k * 2
		BH._tri(idx, v, n, a, a + 1, a + 2)
		BH._tri(idx, v, n, a + 1, a + 3, a + 2)
	# inner wall
	var c := v.size()
	v.append(Vector3(x0, yc, zc))
	n.append(Vector3(signf(x1 - x0), 0, 0))
	uv.append(Vector2.ZERO)
	for k in segs + 1:
		var t := PI * k / segs
		v.append(Vector3(x0, yc + sin(t) * r, zc - cos(t) * r))
		n.append(Vector3(signf(x1 - x0), 0, 0))
		uv.append(Vector2.ZERO)
	for k in segs:
		BH._tri(idx, v, n, c, c + 1 + k, c + 2 + k)
	return BH._mesh(v, n, uv, idx)


static func seams(deco: Array, sh: Shape, zs: Array, a0: float, a1: float) -> void:
	## vertical panel gaps at the given z positions (both sides)
	var m := BH.V("diel", Color(0.03, 0.03, 0.03), 0.6)
	for z in zs:
		for side in [[a0, a1], [PI - a1, PI - a0]]:
			deco.append([surf(sh, samples(z - 0.004, z + 0.004, 0.01), samples(side[0], side[1], 0.04), 0.0015), Transform3D(), m])


static func liv(livery: Array, sh: Shape, rect: Rect2, za: float, zb: float, aa: float, ab: float, both := true) -> void:
	var m := atlas_mat("car_livery")
	livery.append([decal(sh, rect, LIV, za, zb, aa, ab, 0), Transform3D(), m])
	if both:
		livery.append([decal(sh, rect, LIV, za, zb, PI - ab, PI - aa, 1), Transform3D(), m])


static func top_decal(livery: Array, sh: Shape, rect: Rect2, za: float, zb: float, half_a: float) -> void:
	livery.append([decal(sh, rect, LIV, za, zb, PI / 2 - half_a, PI / 2 + half_a, 2), Transform3D(), atlas_mat("car_livery")])


static func plate(livery: Array, at: Vector3) -> void:
	livery.append([BH.slab(Vector3(0.46, 0.12, 0.012), 0.3, 8), Mk.xf(at), BH.V("diel", Color(0.05, 0.05, 0.05), 0.5)])
	var q := QuadMesh.new()
	q.size = Vector2(0.42, 0.098)
	livery.append([q, Mk.xf(at + Vector3(0, 0, 0.008)), _plate_mat()])


static func _plate_mat() -> StandardMaterial3D:
	var k := "cq_plate"
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_texture = BH.T("car_decals")
	m.uv1_scale = Vector3(500.0 / 2048.0, 116.0 / 1024.0, 1)
	m.uv1_offset = Vector3(1542.0 / 2048.0, 518.0 / 1024.0, 0)
	m.roughness = 0.3
	BH._mats[k] = m
	return m


# ================================================================== the cars
static var _cache := {}


## Each car is generated once per detail level; every request after that duplicates the template's nodes
## (meshes are shared) and gives the copy its own paint and brake-light materials.
static func build(id: String, col: Color, full: bool) -> Dictionary:
	var key := id + ("_full" if full else "_ai")
	if not _cache.has(key):
		S = 1.0 if full else 2.0
		var t := _build(id, Color(0.5, 0.5, 0.5), full)
		S = 1.0
		if t.is_empty():
			return t
		_cache[key] = t
	return _clone(_cache[key], col)


static func _clone(t: Dictionary, col: Color) -> Dictionary:
	var root: Node3D = t.root.duplicate()
	var P := BH.paint(col)
	var brake: StandardMaterial3D = t.brake.duplicate()
	_swap(root, t.paint, P, t.brake, brake)
	var body: Node3D = root.get_node("body")
	var wheels := []
	for i in t.wheels.size():
		var w: Dictionary = t.wheels[i]
		var pv: Node3D = root.get_node("w%d" % i)
		wheels.append({"pivot": pv, "spin": pv.get_node("spin"), "pos": w.pos, "r": w.r, "front": w.front})
	var flames := []
	for i in t.flames.size():
		flames.append(body.get_node("f%d" % i))
	var rig := CarRig.new()
	var tr = t.rig
	rig.steering = body.get_node_or_null("steer")
	rig.steer_basis = tr.steer_basis
	rig.head = body.get_node_or_null("head")
	rig.aerial = body.get_node_or_null("aerial")
	for i in tr.arms.size():
		var a: Dictionary = tr.arms[i]
		rig.arms.append({"s": a.s, "shoulder": a.shoulder, "upper": body.get_node("arm%d_u" % i), "fore": body.get_node("arm%d_f" % i), "hand": body.get_node("arm%d_h" % i)})
	return {"root": root, "body": body, "wheels": wheels, "brake": brake, "flames": flames, "rig": rig,
		"half_len": t.half_len, "half_w": t.half_w, "cam_h": t.cam_h}


static func _swap(n: Node, old_p: Material, new_p: Material, old_b: Material, new_b: Material) -> void:
	if n is MeshInstance3D and n.mesh != null:
		for s in n.mesh.get_surface_count():
			var m: Material = n.mesh.surface_get_material(s)
			if m == old_p:
				n.set_surface_override_material(s, new_p)
			elif m == old_b:
				n.set_surface_override_material(s, new_b)
	for c in n.get_children():
		_swap(c, old_p, new_p, old_b, new_b)


static func _build(id: String, col: Color, full: bool) -> Dictionary:
	match id:
		"patrol":
			return _patrol(col, full)
		"drifter":
			return _drifter(col, full)
		"muscle":
			return _muscle(col, full)
		"rally":
			return _rally(col, full)
		"falcon":
			return _falcon(col, full)
	return {}


## Seats, dash with gauges, steering wheel and driver (full detail only).
static func _finish(d: Dictionary, full: bool, hip: Vector3, style: String, suit: Color, accent: Color, hole_w: float, rear_bench := false) -> Dictionary:
	if full:
		var body: Node3D = d.body
		var rig = d.rig
		var sh_y := hip.y + 0.48
		var wpos := Vector3(hip.x, sh_y - 0.13, hip.z + 0.12 - 0.44)
		rig.steering = steering_wheel(body, wpos, 1.15, accent)
		rig.steer_basis = rig.steering.basis
		driver(rig, body, hip, hip.y + 0.64, style, suit)
		var sp := []
		var leather := BH.TM("leather", "car_leather", Color(1, 1, 1), 0.6, 0.0, 4.0)
		seat(sp, hip.x, hip.y - 0.03, hip.z + 0.02, leather)
		seat(sp, -hip.x, hip.y - 0.03, hip.z + 0.02, leather)
		if rear_bench:
			sp.append([BH.slab(Vector3(hole_w * 1.8, 0.14, 0.5), 0.6, 12), Mk.xf(Vector3(0, hip.y - 0.03, hip.z + 0.95)), leather])
			sp.append([BH.slab(Vector3(hole_w * 1.8, 0.55, 0.14), 0.6, 12), Mk.xf(Vector3(0, hip.y + 0.25, hip.z + 1.22), Vector3(-0.15, 0, 0)), leather])
		# dash, gauge pod, centre screen
		var dash := BH.V("diel", Color(0.07, 0.07, 0.075), 0.7)
		sp.append([BH.slab(Vector3(hole_w * 1.9, 0.16, 0.42), 0.7, 14), Mk.xf(Vector3(0, wpos.y + 0.0, wpos.z - 0.3)), dash])
		sp.append([BH.slab(Vector3(0.38, 0.1, 0.14), 0.7, 12), Mk.xf(Vector3(hip.x, wpos.y + 0.1, wpos.z - 0.16)), dash])
		var gq := QuadMesh.new()
		gq.size = Vector2(0.34, 0.085)
		sp.append([gq, Mk.xf(Vector3(hip.x, wpos.y + 0.1, wpos.z - 0.088)), BH.TM("gauges_flat", "car_gauges", Color(1, 1, 1), 0.3, 0.0, 1.0)])
		var sq := QuadMesh.new()
		sq.size = Vector2(0.22, 0.11)
		sp.append([sq, Mk.xf(Vector3(0, wpos.y + 0.03, wpos.z - 0.085), Vector3(-0.25, 0, 0)), _screen_mat()])
		var sm := MeshInstance3D.new()
		sm.mesh = BH.combine(sp)
		sm.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		body.add_child(sm)
	for w in d.wheels:
		for c in w.pivot.get_children():
			if c is GeometryInstance3D:
				c.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	return d


static func _screen_mat() -> StandardMaterial3D:
	var k := "cq_screen"
	if BH._mats.has(k):
		return BH._mats[k]
	var m := StandardMaterial3D.new()
	m.albedo_texture = BH.T("car_screen")
	m.emission_enabled = true
	m.emission_texture = BH.T("car_screen")
	m.emission_energy_multiplier = 0.8
	BH._mats[k] = m
	return m


static func _mirror(parts: Array, at: Vector3, side: float, P) -> void:
	parts.append([BH.tube([at, at + Vector3(side * 0.1, 0.03, 0.03)], 0.015, 8, false), Transform3D(), BH.V("diel", Color(0.05, 0.05, 0.055), 0.5)])
	var c := at + Vector3(side * 0.16, 0.05, 0.03)
	parts.append([BH.slab(Vector3(0.15, 0.1, 0.07), 0.7, 12), Mk.xf(c, Vector3(0, side * 0.25, 0)), P])
	parts.append([BH.slab(Vector3(0.13, 0.08, 0.006), 0.7, 10), Mk.xf(c + Vector3(-side * 0.01, 0, 0.037), Vector3(0, side * 0.25, 0)), BH.V("metal", Color(0.9, 0.9, 0.92), 0.04)])


static func _handle(parts: Array, sh: Shape, z: float, y: float) -> void:
	for right: bool in [true, false]:
		var a := a_at_y(sh, z, y, right)
		parts.append([BH.slab(Vector3(0.13, 0.026, 0.03), 0.8, 10), on(sh, z, a, 0.006), BH.V("metal", Color(0.85, 0.86, 0.88), 0.12)])


static func _tailpipe(parts: Array, pos: Vector3, r: float) -> void:
	parts.append([BH.lathe([Vector2(r * 0.8, 0.0), Vector2(r, 0.0), Vector2(r * 1.04, 0.14), Vector2(r * 0.84, 0.14), Vector2(r * 0.8, 0.02)], 18), Transform3D(Basis(Vector3.RIGHT, PI / 2), pos), BH.V("metal", Color(0.86, 0.87, 0.89), 0.08)])
	parts.append([Mk.cyl(r * 0.8, r * 0.8, 0.01, 14), Mk.xf(pos + Vector3(0, 0, 0.02), Vector3(PI / 2, 0, 0)), BH.V("diel", Color(0.02, 0.02, 0.02), 0.9)])


