		[-1.0, 0.21, 0.79, 0.96, 0.9, 0.38], [-0.5, 0.21, 0.83, 0.96, 0.9, 0.36], [0.6, 0.21, 0.86, 0.97, 0.9, 0.36],
		[1.5, 0.21, 0.9, 0.97, 0.88, 0.38], [2.05, 0.23, 0.92, 0.95, 0.86, 0.4], [2.2, 0.28, 0.9, 0.92, 0.84, 0.42], [2.25, 0.32, 0.87, 0.86, 0.78, 0.45],
	], [[-1.31, 0.36, 0.43], [1.31, 0.36, 0.43]], 0.07)
	var cabin := cab([
		[-0.66, 0.795, 0.8, 0.8, 0.78, 0.4], [-0.12, 0.815, 1.24, 0.8, 0.62, 0.45], [0.75, 0.84, 1.26, 0.81, 0.62, 0.45], [1.62, 0.875, 0.88, 0.83, 0.8, 0.4],
