	var parts := []
	var deco := []
	var livery := []
	var windows := win_top(-0.62, -0.16) + win_sides(-0.08, 0.52) + win_sides(0.6, 1.15, 0.55) + win_top(0.9, 1.55)
	shell(parts, deco, lower, cabin, P, windows, Vector2(-0.5, 1.45), 0.74, full)
	seams(deco, lower, [-0.64, 0.66], -0.85, 0.72)
	_handle(parts, lower, 0.5, 0.76)
	var black := BH.V("diel", Color(0.03, 0.03, 0.035), 0.5)
	# hood vents
	for s: float in [-1.0, 1.0]:
		var c := PI / 2 + s * 0.42
		deco.append([surf(lower, samples(-1.65, -1.25, 0.04), samples(c - 0.07, c + 0.07, 0.035), 0.002), Transform3D(), black])
	# front: grille, bumper intake, splitter, lights
	var z0 := lower.z0
	var grille := QuadMesh.new()
	grille.size = Vector2(0.7, 0.12)
	parts.append([BH.slab(Vector3(0.78, 0.16, 0.03), 0.5, 12), Mk.xf(Vector3(0, 0.36, z0 - 0.01)), black])
	parts.append([grille, Mk.xf(Vector3(0, 0.36, z0 - 0.027), Vector3(0, PI, 0)), grille_mat()])
	parts.append([BH.slab(Vector3(1.8, 0.03, 0.26), 0.4, 12), Mk.xf(Vector3(0, 0.22, z0 + 0.06)), black])
	var led := BH.E("led", Color(1.0, 0.97, 0.88), 3.0)
	var drl := BH.E("drl", Color(0.85, 0.92, 1.0), 2.5)
	for s: float in [-1.0, 1.0]:
		lamp_cluster(deco, Transform3D(Basis(Vector3.UP, PI - s * 0.18), Vector3(s * 0.52, 0.49, z0 - 0.02)), 0.42, 0.13, led, drl)
		parts.append([BH.slab(Vector3(0.2, 0.06, 0.03), 0.5, 8), Mk.xf(Vector3(s * 0.62, 0.32, z0 - 0.01)), black])
		_mirror(parts, Vector3(s * 0.8, 0.9, -0.42), s, P)
		parts.append([BH.slab(Vector3(0.06, 0.07, 1.7), 0.5, 12), Mk.xf(Vector3(s * 0.94, 0.24, 0.0)), black])
		_tailpipe(parts, Vector3(s * 0.5, 0.3, 2.17), 0.05)
	# rear wing on swan-neck stands, diffuser fins
	var wingm := BH.V("diel", Color(0.06, 0.06, 0.065), 0.3)
	parts.append([BH.slab(Vector3(1.8, 0.05, 0.36), 0.6, 14), Mk.xf(Vector3(0, 1.2, 2.02), Vector3(0.12, 0, 0)), wingm])
	for s: float in [-1.0, 1.0]:
		parts.append([BH.slab(Vector3(0.025, 0.17, 0.4), 0.5, 10), Mk.xf(Vector3(s * 0.91, 1.2, 2.02)), wingm])
		parts.append([BH.slab(Vector3(0.05, 0.32, 0.12), 0.5, 10), Mk.xf(Vector3(s * 0.55, 1.04, 2.02), Vector3(0.15, 0, 0)), wingm])
	for k in 5:
		parts.append([BH.slab(Vector3(0.02, 0.12, 0.3), 0.5, 8), Mk.xf(Vector3(-0.4 + k * 0.2, 0.27, 2.1)), black])
