	for s: float in [-1.0, 1.0]:
		tails.append([BH.slab(Vector3(0.36, 0.07, 0.025), 0.7, 12), Mk.xf(Vector3(s * 0.52, 0.76, lower.z1 + 0.008))])
	tails.append([BH.slab(Vector3(0.6, 0.022, 0.02), 0.7, 8), Mk.xf(Vector3(0, 0.78, lower.z1 + 0.006))])
	# livery
	var ab := a_at_y(lower, 0.0, 0.62)
	liv(livery, lower, L_DRIFTKING, -0.62, 0.78, ab - 0.4, ab + 0.1)
	liv(livery, lower, L_21, -1.95, -1.62, ab - 0.18, ab + 0.28)
	plate(livery, Vector3(0, 0.5, 2.27))
	var d := assemble(parts, deco, livery, tails, spec, full, [Vector3(0.5, 0.3, 2.31), Vector3(-0.5, 0.3, 2.31)])
	d["paint"] = P
	return _finish(d, full, Vector3(-0.4, 0.4, 0.42), "blue", Color(0.12, 0.12, 0.14), Color(0.9, 0.1, 0.1), 0.74)


