	tails.append([BH.slab(Vector3(1.6, 0.035, 0.025), 0.6, 10), Mk.xf(Vector3(0, 0.68, lower.z1 + 0.008))])
	# livery: falcon emblem on the nose and doors
	top_decal(livery, lower, L_FALCON, -2.12, -1.8, 0.24)
	var ab := a_at_y(lower, 0.0, 0.48)
	liv(livery, lower, L_FALCON, -0.62, -0.12, ab - 0.2, ab + 0.2)
	var d := assemble(parts, deco, livery, tails, spec, full, [Vector3(-0.05, 0.42, 2.38), Vector3(0.05, 0.42, 2.38)])
	d["paint"] = P
	return _finish(d, full, Vector3(-0.42, 0.28, 0.22), "red", Color(0.08, 0.08, 0.09), Color(1.0, 0.8, 0.15), 0.72)

files.scripts/driver.gd:
extends RefCounted
## Autopilot: follows a path of points (pure pursuit) with corner-speed control. Used by AI racers and the test bot.

var path := PackedVector3Array()
var loop := true
var idx := 0
var lane := 0.0
var drift_style := false
var aggression := 1.0
var nitro_ok := false
var stuck_t := 0.0
var drift_hold := 0.0
var min_speed := 12.0
var la_base := 6.0
var la_k := 0.42
var spacing := 0.0  # > 0: path points are evenly spaced (metres), which makes look-ups O(1)


func set_path(pts: PackedVector3Array, looped: bool) -> void:
	path = pts
	loop = looped
	idx = 0


func nearest(p: Vector3, window := 40) -> int:
	var n := path.size()
	var best := idx
	var bd := 1e18
	for k in range(-10, window):
		var i := idx + k
		if loop:
			i = (i + n) % n
		elif i < 0 or i >= n:
			continue
		var d := Vector2(path[i].x - p.x, path[i].z - p.z).length_squared()
		if d < bd:
			bd = d
			best = i
	return best


func point(i: int) -> Vector3:
	var n := path.size()
	if loop:
		i = ((i % n) + n) % n
	else:
		i = clampi(i, 0, n - 1)
	var p := path[i]
	if lane != 0.0:
		var a := path[((i - 2) % n + n) % n if loop else maxi(i - 2, 0)]
		var b := path[(i + 2) % n if loop else mini(i + 2, n - 1)]
		var d := (b - a)
		d.y = 0
		d = d.normalized()
		p += Vector3(-d.z, 0, d.x) * lane
	return p


func drive(car, dt: float) -> void:
	if path.size() < 2:
		car.set_input(0, 0, 0, false, false)
		return
	idx = nearest(car.pos)
	var f: Vector3 = car.fwd_flat()
	var spd: float = car.speed
	# look ahead along the path
	var la := la_base + spd * la_k
	var target := Vector3.ZERO
	if spacing > 0.0:
		target = point(idx + maxi(1, int(round(la / spacing))))
	else:
		var acc_d := 0.0
		var i := idx
		var prev := Vector3(car.pos.x, 0, car.pos.z)
		target = point(i)
		for k in 60:
			var p := point(i + k)
			acc_d += Vector2(p.x - prev.x, p.z - prev.z).length()
			prev = p
			target = p
			if acc_d >= la:
				break
	var to: Vector3 = target - car.pos
	to.y = 0
	var ang := atan2(f.cross(to).y, f.dot(to))
	var steer := clampf(-ang * 2.4, -1.0, 1.0)
	# corner ahead -> target speed
	var corner := 0.0
	for dist in [12.0, 24.0, 38.0, 55.0]:
		var j := _index_at(dist + spd * 0.4)
		var q: Vector3 = point(j) - car.pos
		q.y = 0
		if q.length() < 1.0:
			continue
		var a2 := absf(atan2(f.cross(q).y, f.dot(q)))
		corner = maxf(corner, a2 * (1.0 if dist < 30.0 else 0.75))
	var vmax: float = float(car.def.vmax) * car.skill
	var vt := lerpf(vmax, min_speed, clampf((corner - 0.12) / 0.8, 0.0, 1.0)) * aggression
	var thr := 1.0
	var brk := 0.0
	if spd > vt + 3.0:
		thr = 0.0
		brk = clampf((spd - vt) / 8.0, 0.0, 1.0)
	elif spd > vt:
		thr = 0.3
	var hb := false
	if drift_style and spd > 15.0 and absf(steer) > 0.55:
		drift_hold = 0.5
	if drift_hold > 0.0:
		drift_hold -= dt
		hb = drift_hold > 0.3
		thr = 1.0
		brk = 0.0
	# reverse out when stuck
	if spd < 1.5 and thr > 0.5:
		stuck_t += dt
	else:
		stuck_t = maxf(0.0, stuck_t - dt)
	if stuck_t > 2.0:
		thr = 0.0
		brk = 1.0
		steer = -steer
		if stuck_t > 3.6:
			stuck_t = 0.0
	var nos: bool = nitro_ok and corner < 0.15 and spd > 15.0 and car.nitro > 0.2
	car.set_input(thr, brk, steer, hb, nos)


func _index_at(dist: float) -> int:
	if spacing > 0.0:
		return idx + int(round(dist / spacing))
	var acc_d := 0.0
	var k := 0
	var prev := point(idx)
	while acc_d < dist and k < 120:
		k += 1
		var p := point(idx + k)
		acc_d += Vector2(p.x - prev.x, p.z - prev.z).length()
		prev = p
	return idx + k


func progress() -> float:
	return float(idx) / maxf(1.0, path.size())


func at_end() -> bool:
	return not loop and idx >= path.size() - 2

