extends Node3D
## Unlimited mode: an endless road that always heads roughly north (+z) through four landscapes
## (Tropical Coast, Pine Mountains, Red Canyon, Autumn Valley), streamed terrain in three detail levels,
## streamed vegetation, road pieces with posts, tyre walls, jump signs and a gate every kilometre.

const Terrain = preload("res://scripts/terrain.gd")
const Veg = preload("res://scripts/veg.gd")
const Flora = preload("res://scripts/flora.gd")
const RoadMesh = preload("res://scripts/roadmesh.gd")
const Props = preload("res://scripts/props.gd")
const Mk = preload("res://scripts/mk.gd")
const BH = preload("res://scripts/buggy_hq.gd")
const PQ = preload("res://scripts/props_hq.gd")

const SURF_TARMAC := 0
const SURF_GRAVEL := 1
const SURF_DIRT := 2
const SURF_SAND := 3
const SURF_GRASS := 4
const SURF_ROCK := 5
const SURF_WATER := 6
const SURF_SNOW := 7

const RSP := 2.0
const START_I := 34
const GATE_EVERY := 500
const PIECE := 100
const VC := 512.0  # vegetation cell size
const BF := 0.0003
const BK := 16.0
const BC := [Vector2(0.3, 0.3), Vector2(-0.3, 0.3), Vector2(0.3, -0.3), Vector2(-0.3, -0.3)]
const BIOME_NAMES := ["TROPICAL COAST", "PINE MOUNTAINS", "RED CANYON", "AUTUMN VALLEY"]
const ROAD_SURF := [0, 0, 2, 1]
const AUTUMN := [Color(1.0, 0.42, 0.08), Color(0.92, 0.2, 0.06), Color(1.0, 0.66, 0.12), Color(0.85, 0.32, 0.1), Color(0.55, 0.62, 0.12), Color(1.0, 0.5, 0.1)]
const SHOULDER := [Color8(160, 130, 94), Color8(140, 132, 120), Color8(186, 112, 72), Color8(150, 122, 88)]

var sea := 0.0
var hw := 5.0
var tex := {}
var gfx := 1

# noise
var nb1: FastNoiseLite
var nb2: FastNoiseLite
var nn: FastNoiseLite
var nt: FastNoiseLite
var f2: FastNoiseLite
var f3: FastNoiseLite
var f4: FastNoiseLite
var t3: FastNoiseLite
var t4: FastNoiseLite
var bo := [0.0, 0.0, 0.0, 0.0]
var start_x := 0.0
var w0 := 0.0
var w1 := 0.0
var w2 := 0.0
var w3 := 0.0

# road
var px := PackedFloat32Array()
var pz := PackedFloat32Array()
var ph := PackedFloat32Array()
var phr := PackedFloat32Array()
var phb := PackedFloat32Array()
var ptx := PackedFloat32Array()
var ptz := PackedFloat32Array()
var pcurv := PackedFloat32Array()
var psf := PackedByteArray()
var psf_raw := PackedByteArray()
var pdist := PackedFloat32Array()
var final := 0
var gx := 0.0
var gz := 0.0
var ghd := 0.0
var gk := 0.0
var g_seg_k := 0.0
var g_seg_left := 300.0
var g_last_jump := 0.0
var rng := RandomNumberGenerator.new()
var jumps := []
var all_jumps := []

# road query results
var q_i := 0.0
var q_d := 0.0
var q_lat := 0.0
var q_h := 0.0
var q_hint := 0

# streaming
var terrain
var veg
var road_mat: ShaderMaterial
var pieces := {}
var vcells := {}
var vjobs := []
var cam := Vector3.ZERO
var last_plan := Vector3(1e9, 0, 1e9)
var props := {}

# colliders
const CCELL := 16.0
var col_grid := {}


func build(textures: Dictionary, quality: int) -> void:
	tex = textures
	gfx = quality
	_noise()
	_pick_start()
	reset_road()
	road_mat = RoadMesh.material(tex, hw)
	terrain = Terrain.new()
	terrain.name = "terrain"
	add_child(terrain)
	terrain.setup(self, [
		{"size": 128.0, "n": 48, "radius": 200.0, "skirt": 2.5, "mask_res": 32},
		{"size": 512.0, "n": 48, "radius": 1150.0, "skirt": 12.0, "drop": 0.8, "mask_res": 16},
		{"size": 2048.0, "n": 48, "radius": 3800.0, "skirt": 40.0, "drop": 3.0},
	], tex, sea)
	for L in terrain.levels:
		L.mat.set_shader_parameter("full_color", 1.0)
	terrain.configure(gfx)
	veg = Veg.new()
	veg.name = "veg"
	add_child(veg)
	veg.setup(tex.leaves, tex.bark)
	veg.cell_size = VC
	veg.add_species("palm", Flora.palm(true), Flora.palm(false), 1.2, true, true)
	veg.add_species("bush", Flora.bush(true), Flora.bush(false), 0.5, false)
	veg.add_species("rock", Flora.rock(true, 1), Flora.rock(false, 1), 0.0, true, false)
	veg.add_species("rock_red", Flora.rock(true, 2, Color(0.72, 0.42, 0.3)), Flora.rock(false, 2, Color(0.72, 0.42, 0.3)), 0.0, true, false)
	veg.add_species("rock_cool", Flora.rock(true, 3, Color(0.6, 0.62, 0.64)), Flora.rock(false, 3, Color(0.6, 0.62, 0.64)), 0.0, true, false)
	veg.add_species("pine", Flora.pine(true), Flora.pine(false), 0.4, true, true)
	veg.add_species("maple", Flora.broadleaf(true, false), Flora.broadleaf(false, false), 0.6, true, true)
	veg.add_species("birch", Flora.broadleaf(true, true), Flora.broadleaf(false, true), 0.7, true, false)
	veg.add_species("cactus", Flora.cactus(true), Flora.cactus(false), 0.0, true)
	veg.add_species("dry", Flora.dry_shrub(true), Flora.dry_shrub(false), 0.4, false)
	veg.add_species("fern", Flora.fern(true), Flora.fern(false), 0.8, false)
	veg.configure(gfx)
	_props_assets()


func _mk_noise(seed: int, octaves: int) -> FastNoiseLite:
	var n := FastNoiseLite.new()
	n.noise_type = FastNoiseLite.TYPE_SIMPLEX
	n.seed = seed
	n.frequency = 1.0
	if octaves > 1:
		n.fractal_type = FastNoiseLite.FRACTAL_FBM
		n.fractal_octaves = octaves
		n.fractal_lacunarity = 2.03
		n.fractal_gain = 0.5
	else:
		n.fractal_type = FastNoiseLite.FRACTAL_NONE
	return n


func _noise() -> void:
	nb1 = _mk_noise(101, 1)
	nb2 = _mk_noise(202, 1)
	nn = _mk_noise(1, 1)
	nt = _mk_noise(303, 1)
	f2 = _mk_noise(1, 2)
	f3 = _mk_noise(1, 3)
	f4 = _mk_noise(1, 4)
	t3 = _mk_noise(303, 3)
	t4 = _mk_noise(303, 4)


# ------------------------------------------------------------------ landscape functions
func biome_w(x: float, z: float) -> void:
	var t := nb1.get_noise_2d(x * BF + bo[0], z * BF + bo[1])
	var m := nb2.get_noise_2d(x * BF + bo[2], z * BF + bo[3])
	w0 = exp(-((t - 0.3) * (t - 0.3) + (m - 0.3) * (m - 0.3)) * BK)
	w1 = exp(-((t + 0.3) * (t + 0.3) + (m - 0.3) * (m - 0.3)) * BK)
	w2 = exp(-((t - 0.3) * (t - 0.3) + (m + 0.3) * (m + 0.3)) * BK)
	w3 = exp(-((t + 0.3) * (t + 0.3) + (m + 0.3) * (m + 0.3)) * BK)
	var s := w0 + w1 + w2 + w3
	w0 /= s
	w1 /= s
	w2 /= s
	w3 /= s


func dominant() -> int:
	var b := 0
	var bw := w0
	if w1 > bw:
		b = 1
		bw = w1
	if w2 > bw:
		b = 2
		bw = w2
	if w3 > bw:
		b = 3
	return b


func h_trop(x: float, z: float) -> float:
	var c := f4.get_noise_2d(x * 0.0011 + 3.1, z * 0.0011 - 7.7)
	var b := 2.0 + 55.0 * c + 7.0 * t3.get_noise_2d(x * 0.0045, z * 0.0045)
	if b < 0.0:
		b *= 1.5
	elif b < 4.0:
		b *= 0.45
	else:
		b = 1.8 + (b - 4.0) * 1.05
	return maxf(b, -22.0)


func h_high(x: float, z: float) -> float:
	var r := 0.0
	var a := 0.5
	var f := 0.0015
	var tot := 0.0
	for i in 4:
		var n := 1.0 - absf(nt.get_noise_2d(x * f + 17.3, z * f - 4.1))
		r += a * n * n
		tot += a
		a *= 0.5
		f *= 2.1
	r /= tot
	return 16.0 + 100.0 * r * r + 9.0 * f3.get_noise_2d(x * 0.006 + 2.0, z * 0.006)


func h_canyon(x: float, z: float) -> float:
	var p := t4.get_noise_2d(x * 0.0013 + 11.0, z * 0.0013 + 5.0)
	var raw := 24.0 + 70.0 * p
	var stp := 12.0
	var s := raw / stp
	var k := floorf(s)
	var ff := smoothstep(0.36, 0.64, s - k)
	var h := (k + ff) * stp + 1.1 * f2.get_noise_2d(x * 0.03, z * 0.03)
	return maxf(h, 3.2 + 1.2 * nn.get_noise_2d(x * 0.01, z * 0.01))


func h_autumn(x: float, z: float) -> float:
	var t := f4.get_noise_2d(x * 0.0016 - 4.0, z * 0.0016 + 9.0)
	var h := 13.0 + 46.0 * t + 5.0 * t3.get_noise_2d(x * 0.007, z * 0.007)
	if h < 1.5:
		h = 1.5 + (h - 1.5) * 1.5
	return maxf(h, -14.0)


## Raw landscape height; call biome_w(x, z) first.
func raw_h(x: float, z: float) -> float:
	var h := 0.0
	var ws := 0.0
	if w0 > 0.004:
		h += w0 * h_trop(x, z)
		ws += w0
	if w1 > 0.004:
		h += w1 * h_high(x, z)
		ws += w1
	if w2 > 0.004:
		h += w2 * h_canyon(x, z)
		ws += w2
	if w3 > 0.004:
		h += w3 * h_autumn(x, z)
		ws += w3
	return h / ws


# ------------------------------------------------------------------ start position (searched once, see tools/infstart.gd)
func _pick_start() -> void:
	bo = [-296.430525183678, -146.828708052635, -200.502875447273, -438.256978802383]
	start_x = 700.0


func search_start() -> void:
	var R := RandomNumberGenerator.new()
	R.seed = 4242
	for tries in 600:
		bo = [R.randf() * 900.0 - 450.0, R.randf() * 900.0 - 450.0, R.randf() * 900.0 - 450.0, R.randf() * 900.0 - 450.0]
		biome_w(0, 0)
		if w0 < 0.93:
			continue
		biome_w(0, 900)
		if w0 < 0.75:
			continue
		for sxi in range(-56, 57):
			var sx := sxi * 25.0
			biome_w(sx, 0)
			if w0 < 0.9:
				continue
			var ok := true
			for zi in range(-3, 14):
				var z := zi * 20.0
				biome_w(sx, z)
				var h := raw_h(sx, z)
				if h < 3.4 or h > 15.0:
					ok = false
					break
			if not ok:
				continue
			var coast := false
			for dx: float in [-260.0, -180.0, 180.0, 260.0]:
				for z: float in [0.0, 100.0, 200.0, 300.0]:
					biome_w(sx + dx, z)
					if raw_h(sx + dx, z) < -1.0:
						coast = true
			if coast:
				start_x = sx
				print("START bo=", bo, " start_x=", sx)
				return


# ------------------------------------------------------------------ road generation
func reset_road() -> void:
	for a in [px, pz, ph, phr, phb, ptx, ptz, pcurv, pdist]:
		a.clear()
	psf.clear()
	psf_raw.clear()
	final = 0
	jumps.clear()
	all_jumps.clear()
	rng.seed = 9090
	gx = start_x
	gz = -START_I * RSP
	ghd = 0.0
	gk = 0.0
	g_seg_k = 0.0
	g_seg_left = 300.0
	g_last_jump = 0.0


func _plan_seg() -> void:
	var cur_h: float = phr[phr.size() - 1] if phr.size() > 0 else 5.0
	var cands := [0.0, 1.0 / 320.0, -1.0 / 320.0, 1.0 / 150.0, -1.0 / 150.0, 1.0 / 85.0, -1.0 / 85.0, 1.0 / 50.0, -1.0 / 50.0]
	var best_k := 0.0
	var best_len := 100.0
	var bc := 1e18
	for kT: float in cands:
		var len := 80.0 + rng.randf() * 160.0 if kT == 0.0 else (30.0 + rng.randf() * 50.0 if absf(kT) > 0.015 else 60.0 + rng.randf() * 110.0)
		var x := gx
		var z := gz
		var hd := ghd
		var k := gk
		var cost := 0.0
		var prev_h := cur_h
		var s := 0.0
		while s < len + 60.0:
			for q in 5:
				k += clampf(kT - k, -0.0012, 0.0012)
				hd = clampf(hd + k * RSP, -1.25, 1.25)
				x += sin(hd) * RSP
				z += cos(hd) * RSP
			biome_w(x, z)
			var h := raw_h(x, z)
			if h < 2.6:
				cost += 60.0 + (2.6 - h) * 8.0
			cost += absf(h - prev_h) * 0.5
			prev_h = h
			s += 10.0
		cost += absf(prev_h - cur_h) * 0.2
		var ah := absf(hd)
		cost += ah * 6.0 + maxf(0.0, ah - 0.85) * 160.0
		cost += (4.0 if kT == 0.0 else 0.0) + (7.0 if absf(kT) > 0.015 else 0.0) + rng.randf() * 16.0
		if cost < bc:
			bc = cost
			best_k = kT
			best_len = len
	g_seg_k = best_k
	g_seg_left = best_len
	var n := px.size()
	if best_k == 0.0 and best_len > 130.0 and n > 200 and n * RSP - g_last_jump > 1100.0 and rng.randf() < 0.5:
		var ci := n + int(round(best_len * 0.5 / RSP))
		var jp := {"i": ci, "h": 1.6 + rng.randf() * 0.9}
		jumps.append(jp)
		all_jumps.append(jp)
		g_last_jump = ci * RSP


func _add_point() -> void:
	if g_seg_left <= 0.0:
		_plan_seg()
	gk += clampf(g_seg_k - gk, -0.0012, 0.0012)
	ghd += gk * RSP
	if ghd > 1.25:
		ghd = 1.25
		if gk > 0.0:
			gk = 0.0
	elif ghd < -1.25:
		ghd = -1.25
		if gk < 0.0:
			gk = 0.0
	if px.size() > 0:
		gx += sin(ghd) * RSP
		gz += cos(ghd) * RSP
	g_seg_left -= RSP
	biome_w(gx, gz)
	var hr := raw_h(gx, gz)
	px.append(gx)
	pz.append(gz)
	ptx.append(sin(ghd))
	ptz.append(cos(ghd))
	phr.append(hr)
	ph.append(maxf(1.4, hr))
	phb.append(0.0)
	pcurv.append(0.0)
	pdist.append((px.size() - 1) * RSP)
	psf.append(ROAD_SURF[dominant()])
	psf_raw.append(ROAD_SURF[dominant()])
	while final < px.size() - 16:
		_finalize(final)
		final += 1
	if jumps.size() > 8:
		jumps = jumps.filter(func(j): return j.i > final - 40)


func _finalize(i: int) -> void:
	var n := px.size()
	var s := 0.0
	var c := 0
	for k in range(maxi(0, i - 15), mini(n - 1, i + 15) + 1):
		s += maxf(phr[k], 1.4)
		c += 1
	var target := maxf(1.4, s / c)
	var G := 0.1 * RSP
	phb[i] = target if i == 0 else clampf(target, phb[i - 1] - G, phb[i - 1] + G)
	var bump := 0.0
	for j in jumps:
		var u := (i - int(j.i)) * RSP
		if u >= -32.0 and u <= 10.0:
			if u <= 0.0:
				var t := (u + 32.0) / 32.0
				bump = maxf(bump, float(j.h) * t * t)
			else:
				var t := u / 10.0
				bump = maxf(bump, float(j.h) * (1.0 - t) * (1.0 - t))
	ph[i] = phb[i] + bump
	var a := maxi(0, i - 5)
	var b := mini(n - 1, i + 5)
	pcurv[i] = atan2(ptx[a] * ptz[b] - ptz[a] * ptx[b], ptx[a] * ptx[b] + ptz[a] * ptz[b]) / (10.0 * RSP)
	# surface: smooth the biome surface over a short window so it does not flicker at borders
	if i >= 8:
		var cnt := [0, 0, 0, 0]
		for k in range(i - 8, mini(n, i + 8)):
			cnt[psf_raw[k]] += 1
		var bs := 0
		for k in 4:
			if cnt[k] > cnt[bs]:
				bs = k
		psf[i] = bs


func ensure_road(target_z: float, max_steps := 4000) -> void:
	var n := 0
	while n < max_steps and (final < 40 or pz[final - 1] < target_z):
		_add_point()
		n += 1


# ------------------------------------------------------------------ road queries
func _index_at_z(z: float) -> int:
	var lo := 0
	var hi := final - 1
	if hi < 1:
		return 0
	if z <= pz[0]:
		return 0
	if z >= pz[hi]:
		return hi
	while hi - lo > 1:
		var mid := (lo + hi) >> 1
		if pz[mid] <= z:
			lo = mid
		else:
			hi = mid
	return lo


## Finds the foot point on the road for (x, z). Results in q_i (fractional index), q_d, q_lat, q_h.
func road_query(x: float, z: float, hint := -1) -> void:
	var i := hint if hint >= 0 and hint < final - 1 and absf(pz[hint] - z) < 12.0 else _index_at_z(z)
	for it in 3:
		var s := (x - px[i]) * ptx[i] + (z - pz[i]) * ptz[i]
		var ni := clampi(i + int(floor(s / RSP)), 0, maxi(final - 2, 0))
		if ni == i:
			break
		i = ni
	i = clampi(i, 0, maxi(final - 2, 0))
	var ex := px[i + 1] - px[i]
	var ez := pz[i + 1] - pz[i]
	var t := clampf(((x - px[i]) * ex + (z - pz[i]) * ez) / (ex * ex + ez * ez), 0.0, 1.0)
	var cx := px[i] + ex * t
	var cz := pz[i] + ez * t
	q_i = i + t
	q_lat = (x - cx) * -ptz[i] + (z - cz) * ptx[i]
	q_d = sqrt((x - cx) * (x - cx) + (z - cz) * (z - cz))
	q_h = lerpf(ph[i], ph[i + 1], t)
	q_hint = i


## Carved height (terrain shaped around the road). Calls biome_w.
func h_carved(x: float, z: float, hint := -1) -> float:
	biome_w(x, z)
	var raw := raw_h(x, z)
	road_query(x, z, hint)
	var ci := hw + 2.5
	var co := hw + 22.0 + absf(raw - q_h) * 0.6
	if q_d >= co:
		return raw
	if q_d < hw + 0.6:
		return q_h - 0.14
	var w := 1.0 - smoothstep(ci, co, q_d)
	return raw + (q_h - 0.12 - raw) * w


# ------------------------------------------------------------------ terrain source
func chunk_wanted(_li: int, _cx: int, cz: int) -> bool:
	return true


class Job:
	var w
	var li := 0
	var x0 := 0.0
	var z0 := 0.0
	var step := 2.0
	var n := 32
	var h := PackedFloat32Array()
	var col := PackedColorArray()
	var mcol := PackedColorArray()
	var uv := PackedVector2Array()
	var uv2 := PackedVector2Array()
	var bw := PackedFloat32Array()
	var rd := PackedFloat32Array()
	var min_h := 1e9
	var row := 0
	var phase := 0

	func run(budget: int) -> bool:
		return w.run_job(self, budget)


func begin_chunk(li: int, x0: float, z0: float, step: float, n: int):
	var j := Job.new()
	j.w = self
	j.li = li
	j.x0 = x0
	j.z0 = z0
	j.step = step
	j.n = n
	var b := n + 3
	var wv := n + 1
	j.h.resize(b * b)
	j.bw.resize(wv * wv * 4)
	j.rd.resize(wv * wv)
	j.col.resize(wv * wv)
	j.mcol.resize(wv * wv)
	j.uv.resize(wv * wv)
	j.uv2.resize(wv * wv)
	return j


func run_job(j, budget: int) -> bool:
	var t0 := Time.get_ticks_usec()
	var n: int = j.n
	var b := n + 3
	var wv := n + 1
	var st: float = j.step
	# make sure the road exists far enough for this chunk (the far ring does not carve the road)
	if j.li < 2 and (final < 2 or pz[final - 1] < j.z0 + n * st + 40.0):
		ensure_road(j.z0 + n * st + 60.0, 400)
	while j.phase == 0:
		var jj: int = j.row
		var z: float = j.z0 + (jj - 1) * st
		var hint := -1
		for ii in b:
			var x: float = j.x0 + (ii - 1) * st
			var h: float
			if j.li == 2:
				biome_w(x, z)
				h = raw_h(x, z)
				q_d = 999.0
			else:
				h = h_carved(x, z, hint)
				hint = q_hint
			j.h[jj * b + ii] = h
			if h < j.min_h:
				j.min_h = h
			if ii >= 1 and ii <= n + 1 and jj >= 1 and jj <= n + 1:
				var k := (jj - 1) * wv + (ii - 1)
				j.bw[k * 4] = w0
				j.bw[k * 4 + 1] = w1
				j.bw[k * 4 + 2] = w2
				j.bw[k * 4 + 3] = w3
				j.rd[k] = q_d
		j.row += 1
		if j.row >= b:
			j.phase = 1
			j.row = 0
		if Time.get_ticks_usec() - t0 > budget:
			return false
	while j.phase == 1:
		var jj: int = j.row
		var z: float = j.z0 + jj * st
		for ii in wv:
			var x: float = j.x0 + ii * st
			var k := jj * wv + ii
			var g := (jj + 1) * b + ii + 1
			var h: float = j.h[g]
			var dx: float = (j.h[g + 1] - j.h[g - 1]) / (2.0 * st)
			var dz: float = (j.h[g + b] - j.h[g - b]) / (2.0 * st)
			var s := sqrt(dx * dx + dz * dz)
			_attr(j, k, x, z, h, s)
		j.row += 1
		if j.row >= wv:
			j.phase = 2
		if Time.get_ticks_usec() - t0 > budget:
			return false
	return true


func _lerp3(a: Vector3, b: Vector3, t: float) -> Vector3:
	return a + (b - a) * t


const GRASS_TINT := [Color(0.07, 0.17, 0.025), Color(0.06, 0.14, 0.03), Color(0.25, 0.2, 0.08), Color(0.17, 0.16, 0.035)]


func _attr(j, k: int, x: float, z: float, h: float, s: float) -> void:
	## Colours are computed on the GPU from the biome weights; here only what the CPU needs (grass).
	var bw0: float = j.bw[k * 4]
	var bw1: float = j.bw[k * 4 + 1]
	var bw2: float = j.bw[k * 4 + 2]
	var bw3: float = j.bw[k * 4 + 3]
	var rd: float = j.rd[k]
	j.mcol[k] = Color(bw0, bw1, bw2, bw3)
	j.uv[k] = Vector2(0.0, minf(rd / 30.0, 1.0))
	if j.li > 0:
		return
	var n2 := nn.get_noise_2d(x * 0.011 + 7.0, z * 0.011 - 3.0)
	var fo := nn.get_noise_2d(x * 0.0055 + 31.0, z * 0.0055 - 17.0)
	var snow := smoothstep(78.0, 90.0, h + n2 * 8.0) * bw1
	var gT := smoothstep(2.4, 3.4, h) * (1.0 - smoothstep(0.42, 0.72, s))
	var gH := (1.0 - smoothstep(0.5, 0.8, s)) * (1.0 - snow) * smoothstep(1.5, 3.0, h) * (0.6 if fo > 0.15 else 1.0)
	var gC := 0.4 * smoothstep(0.15, 0.45, n2) * (1.0 - smoothstep(0.3, 0.5, s))
	var gA := (1.0 - smoothstep(0.45, 0.75, s)) * smoothstep(1.6, 2.6, h) * 0.95
	var grass := bw0 * gT + bw1 * gH + bw2 * gC + bw3 * gA
	grass *= smoothstep(hw + 1.2, hw + 3.8, rd) * (0.55 + 0.45 * clampf(0.5 + n2 * 0.6, 0.0, 1.0))
	var t: Color = GRASS_TINT[0] * bw0 + GRASS_TINT[1] * bw1 + GRASS_TINT[2] * bw2 + GRASS_TINT[3] * bw3
	var dry := smoothstep(0.15, 0.55, n2) * 0.5
	t = t.lerp(Color(0.24, 0.22, 0.07), dry)
	j.col[k] = Color(t.r * 1.6, t.g * 1.6, t.b * 1.6, clampf(grass, 0.0, 1.0))


func _c_trop(h: float, s: float, n1: float, n2: float, n3: float, fo: float) -> Vector3:
	var rip := sin((n1 * 3.0)) * 4.0 if n3 != 0.0 else 0.0
	var c := Vector3(214.0 + n1 * 9.0 + n3 * 6.0 + rip, 196.0 + n1 * 8.0 + n3 * 5.0 + rip, 156.0 + n1 * 8.0 + n3 * 4.0 + rip * 0.8)
	var wet := 1.0 - smoothstep(-0.1, 0.7, h)
	c = _lerp3(c, Vector3(160, 140, 104), wet)
	if h < -0.4:
		c = _lerp3(c, Vector3(205, 192, 152), smoothstep(-0.4, -8.0, h))
	var gt := smoothstep(2.1 + n2 * 0.5, 2.9 + n2 * 0.5, h)
	if gt > 0.0:
		var g := Vector3(74.0 + n1 * 12.0, 112.0 + n1 * 14.0, 42.0 + n1 * 6.0)
		var dry := smoothstep(0.15, 0.55, n2 + n3 * 0.15)
		g = _lerp3(g, Vector3(140, 136, 74), dry * 0.7)
		var f := smoothstep(0.12, 0.35, fo) * 0.3
		g = Vector3(g.x * (1.0 - f), g.y * (1.0 - f * 0.7), g.z * (1.0 - f))
		c = _lerp3(c, g, gt)
	var rk := smoothstep(0.42, 0.78, s + n3 * 0.08)
	if rk > 0.0:
		var v := 108.0 + n1 * 16.0 + n3 * 18.0 + sin(h * 1.9 + n1 * 2.5) * 10.0
		c = _lerp3(c, Vector3(v + 8.0, v, v - 14.0), rk)
	return c


func _c_high(h: float, s: float, n1: float, n2: float, n3: float, fo: float) -> Vector3:
	var c := Vector3(70.0 + n1 * 10.0, 104.0 + n1 * 12.0, 48.0 + n1 * 6.0)
	c = _lerp3(c, Vector3(118, 120, 66), smoothstep(0.2, 0.6, n2) * 0.5)
	c = _lerp3(c, Vector3(36, 58, 30), smoothstep(0.0, 0.3, fo) * 0.8)
	if h < 2.2:
		c = _lerp3(c, Vector3(128, 120, 100), 1.0 - smoothstep(0.4, 2.2, h))
	var rk := smoothstep(0.48, 0.85, s + n3 * 0.08)
	if rk > 0.0:
		var v := 112.0 + n1 * 14.0 + n3 * 16.0 + sin(h * 1.3 + n1 * 2.0) * 8.0
		c = _lerp3(c, Vector3(v, v - 2.0, v - 6.0), rk)
	var sn := smoothstep(78.0, 90.0, h + n2 * 8.0 + n1 * 3.0) * (1.0 - smoothstep(0.75, 1.05, s))
	if sn > 0.0:
		c = _lerp3(c, Vector3(236, 240, 247), sn)
	return c


func _c_canyon(h: float, s: float, n1: float, n2: float, n3: float, _fo: float) -> Vector3:
	var c := Vector3(196.0 + n1 * 10.0 + n3 * 6.0, 114.0 + n1 * 8.0 + n3 * 4.0, 66.0 + n1 * 6.0 + n3 * 3.0)
	c = _lerp3(c, Vector3(170, 140, 84), smoothstep(0.15, 0.5, n2) * 0.45)
	var rk := smoothstep(0.38, 0.7, s + n3 * 0.06)
	if rk > 0.0:
		var band := 0.5 + 0.5 * sin(h * 0.85 + n1 * 1.6)
		var dk := 0.88 + n3 * 0.1
		c = _lerp3(c, Vector3(lerpf(146, 216, band) * dk, lerpf(68, 150, band) * dk, lerpf(40, 100, band) * dk), rk)
	return c


func _c_autumn(h: float, s: float, n1: float, n2: float, n3: float, fo: float) -> Vector3:
	var c := Vector3(118.0 + n1 * 12.0, 122.0 + n1 * 12.0, 54.0 + n1 * 6.0)
	c = _lerp3(c, Vector3(168, 142, 66), smoothstep(0.1, 0.5, n2) * 0.6)
	c = _lerp3(c, Vector3(150, 92, 42), smoothstep(0.0, 0.3, fo) * 0.75)
	if h < 2.0:
		c = _lerp3(c, Vector3(96, 88, 66), 1.0 - smoothstep(0.0, 2.0, h))
	var rk := smoothstep(0.45, 0.8, s + n3 * 0.08)
	if rk > 0.0:
		var v := 116.0 + n1 * 14.0 + n3 * 14.0
		c = _lerp3(c, Vector3(v + 4.0, v - 2.0, v - 10.0), rk)
	return c


func chunk_built(li: int, k: Vector2i, job) -> void:
	if li == 0:
		l0[k] = job


func chunk_freed(li: int, k: Vector2i) -> void:
	if li == 0:
		l0.erase(k)


var l0 := {}


# ------------------------------------------------------------------ physics queries
func _terrain_h(x: float, z: float) -> float:
	var k := Vector2i(int(floor(x / 128.0)), int(floor(z / 128.0)))
	if l0.has(k):
		var j = l0[k]
		var fx: float = (x - j.x0) / j.step
		var fz: float = (z - j.z0) / j.step
		var i := clampi(int(fx), 0, j.n - 1)
		var jj := clampi(int(fz), 0, j.n - 1)
		var a := clampf(fx - i, 0.0, 1.0)
		var b := clampf(fz - jj, 0.0, 1.0)
		var bb: int = j.n + 3
		var g := (jj + 1) * bb + i + 1
		var h: PackedFloat32Array = j.h
		return (h[g] * (1.0 - a) + h[g + 1] * a) * (1.0 - b) + (h[g + bb] * (1.0 - a) + h[g + bb + 1] * a) * b
	return h_carved(x, z)


func height(x: float, z: float) -> float:
	var t := _terrain_h(x, z)
	road_query(x, z, q_hint)
	if q_d < hw + 1.6:
		var rf := clampf(hw + 1.6 - q_d, 0.0, 1.0)
		return lerpf(t, q_h, rf)
	return t


func ground(x: float, z: float, _y := 1e9) -> float:
	return height(x, z)


func normal_at(x: float, z: float, _y := 1e9) -> Vector3:
	var e := 0.8
	var hl := height(x - e, z)
	var hr := height(x + e, z)
	var hd := height(x, z - e)
	var hu := height(x, z + e)
	return Vector3(hl - hr, 2.0 * e, hd - hu).normalized()


func surface_at(x: float, z: float, y: float) -> int:
	road_query(x, z, q_hint)
	if q_d < hw + 0.4:
		return int(psf[clampi(int(q_i), 0, final - 1)])
	if y < sea - 0.2:
		return SURF_WATER
	biome_w(x, z)
	var b := dominant()
	var h := y
	var s := normal_at(x, z).y
	var steep := s < 0.86
	match b:
		0:
			return SURF_SAND if h < 2.35 else (SURF_ROCK if steep else SURF_GRASS)
		1:
			if h + nn.get_noise_2d(x * 0.011 + 7.0, z * 0.011 - 3.0) * 8.0 > 84.0 and s > 0.7:
				return SURF_SNOW
			return SURF_ROCK if steep else SURF_GRASS
		2:
			return SURF_ROCK if s < 0.88 else SURF_SAND
	return SURF_ROCK if steep else SURF_GRASS


func water_depth(x: float, z: float) -> float:
	return sea - _terrain_h(x, z)


func biome_name(x: float, z: float) -> String:
	biome_w(x, z)
	return BIOME_NAMES[dominant()]


func zone_at(x: float, z: float) -> String:
	return biome_name(x, z)


# ------------------------------------------------------------------ road API for the game
func road_count() -> int:
	return final


func road_point(i: float) -> Vector3:
	var fi := clampf(i, 0.0, final - 1.001)
	var i0 := int(fi)
	var t := fi - i0
	return Vector3(lerpf(px[i0], px[i0 + 1], t), lerpf(ph[i0], ph[i0 + 1], t), lerpf(pz[i0], pz[i0 + 1], t))


func road_dir(i: int) -> Vector2:
	i = clampi(i, 0, final - 1)
	return Vector2(ptx[i], ptz[i])


func road_yaw(i: int) -> float:
	var d := road_dir(i)
	return atan2(-d.x, -d.y)


func road_near(x: float, z: float, hint := -1) -> Vector2:
	road_query(x, z, hint)
	return Vector2(int(round(q_i)), q_d)


func road_distance(i: int) -> float:
	return i * RSP


func start_distance() -> float:
	return START_I * RSP


func jump_ahead(i0: int, n: int) -> bool:
	for j in all_jumps:
		var d := int(j.i) - i0
		if d > 5 and d < n:
			return true
	return false


func start_pose() -> Array:
	var i := START_I - 10
	return [road_point(i), road_yaw(i)]


func reset_run() -> void:
	ensure_road(600.0)
	var s := start_pose()
	var p: Vector3 = s[0]
	# build the near rings now; the far ring streams in while driving
	var r1: float = terrain.levels[1].radius
	var r2: float = terrain.levels[2].radius
	terrain.levels[1].radius = 600.0
	terrain.levels[2].radius = 0.0
	terrain.flush(p, 30000)
	terrain.levels[1].radius = r1
	terrain.levels[2].radius = r2
	terrain.last_plan = Vector3(1e9, 0, 1e9)
	update_props(p, true)


# ------------------------------------------------------------------ collisions
func _add_col(x: float, z: float, r: float, top: float, owner: Array) -> void:
	var c0 := int(floor((x - r) / CCELL))
	var c1 := int(floor((x + r) / CCELL))
	var r0 := int(floor((z - r) / CCELL))
	var r1 := int(floor((z + r) / CCELL))
	var e := [x, z, r, top]
	for gz2 in range(r0, r1 + 1):
		for gx2 in range(c0, c1 + 1):
			var key := Vector2i(gx2, gz2)
			if not col_grid.has(key):
				col_grid[key] = []
			col_grid[key].append(e)
			owner.append([key, e])


func _remove_cols(owner: Array) -> void:
	for it in owner:
		var key: Vector2i = it[0]
		if col_grid.has(key):
			col_grid[key].erase(it[1])
			if col_grid[key].is_empty():
				col_grid.erase(key)


func collide(car, p: Vector3, r: float) -> Array:
	var key := Vector2i(int(floor(p.x / CCELL)), int(floor(p.z / CCELL)))
	if not col_grid.has(key):
		return [0.0]
	var hit := 0.0
	for e in col_grid[key]:
		var dx: float = p.x - e[0]
		var dz: float = p.z - e[1]
		var rr: float = r + e[2]
		var d2 := dx * dx + dz * dz
		if d2 >= rr * rr or d2 < 1e-6 or car.pos.y > e[3]:
			continue
		var d := sqrt(d2)
		var nx := dx / d
		var nz := dz / d
		var pen := rr - d
		car.pos.x += nx * pen
		car.pos.z += nz * pen
		var vn: float = car.vel.x * nx + car.vel.z * nz
		if vn < 0.0:
			car.vel.x -= nx * vn * 1.35
			car.vel.z -= nz * vn * 1.35
			car.vel *= 0.82
			hit = maxf(hit, -vn)
	return [hit]


# ------------------------------------------------------------------ vegetation cells
class VegJob:
	var key := Vector2i.ZERO
	var r := RandomNumberGenerator.new()
	var items := {}
	var cols := []
	var placed := PackedVector2Array()
	var t := 0


func _veg_begin(cx: int, cz: int) -> VegJob:
	var vj := VegJob.new()
	vj.key = Vector2i(cx, cz)
	vj.r.seed = hash(Vector2i(cx, cz)) ^ 0x5bd1e995
	for sp in ["palm", "bush", "rock", "rock_red", "rock_cool", "pine", "maple", "birch", "cactus", "dry", "fern"]:
		vj.items[sp] = PackedFloat32Array()
	return vj


func _veg_cell(cx: int, cz: int) -> void:
	var vj := _veg_begin(cx, cz)
	_veg_run(vj, 1 << 30)


## Places up to `budget` microseconds worth of candidates; true when the cell is complete.
func _veg_run(vj: VegJob, budget: int) -> bool:
	var t0 := Time.get_ticks_usec()
	var r := vj.r
	var x0 := vj.key.x * VC
	var z0 := vj.key.y * VC
	var items := vj.items
	var cols := vj.cols
	var placed := vj.placed
	var free_at := func(x: float, z: float, d: float) -> bool:
		for p in placed:
			if (p.x - x) * (p.x - x) + (p.y - z) * (p.y - z) < d * d:
				return false
		return true
	var count := int(210.0 * (VC / 128.0) * (VC / 128.0))
	while vj.t < count:
		vj.t += 1
		if Time.get_ticks_usec() - t0 > budget:
			vj.t -= 1
			return false
		var x := x0 + r.randf() * VC
		var z := z0 + r.randf() * VC
		var h := h_carved(x, z)
		var rd := q_d
		if rd < hw + 4.0:
			continue
		var bw := [w0, w1, w2, w3]
		var h2 := h_carved(x + 1.2, z + 1.2)
		var s := absf(h2 - h) / 1.2 * 1.25
		var rr := r.randf()
		var b := 0
		while b < 3:
			rr -= float(bw[b])
			if rr <= 0.0:
				break
			b += 1
		var fo := nn.get_noise_2d(x * 0.0055 + 31.0, z * 0.0055 - 17.0)
		var u := r.randf()
		var sc := 0.75 + r.randf() * 0.55
		var rot := r.randf() * TAU
		var pos := Vector3(x, h, z)
		if b == 0:
			if h < 0.8:
				if h > -2.0 and u < 0.02:
					var k := 0.5 + r.randf() * 1.2
					Veg.pack(items.rock, pos - Vector3(0, k * 0.15, 0), rot, k, Color(1, 0.98, 0.94), r.randf())
				continue
			var p_palm := 0.0 if s > 0.45 else (0.34 if h < 3.4 else (0.42 if fo > 0.12 else 0.06))
			if u < p_palm and free_at.call(x, z, 4.6):
				Veg.pack(items.palm, pos - Vector3(0, 0.15, 0), rot, sc, Color(1, 1, 1).lerp(Color(1.1, 1.05, 0.8), r.randf()), r.randf(), r.randf_range(-0.05, 0.05))
				placed.append(Vector2(x, z))
				_add_col(x, z, 0.32 * sc + 0.12, h + 9.0, cols)
				continue
			if h > 1.6 and s < 0.5 and u < p_palm + 0.2 and free_at.call(x, z, 2.4):
				Veg.pack(items.bush if r.randf() < 0.7 else items.fern, pos - Vector3(0, 0.1, 0), rot, sc, Color(0.85 + r.randf() * 0.3, 0.9 + r.randf() * 0.2, 0.8 + r.randf() * 0.25), r.randf())
				placed.append(Vector2(x, z))
				continue
			if u > 0.96 or (s > 0.38 and u > 0.6):
				var k := 0.5 + pow(r.randf(), 2.2) * 2.4
				Veg.pack(items.rock, pos - Vector3(0, k * 0.15, 0), rot, k, Color(1, 0.98, 0.94), r.randf())
				if k > 0.75:
					_add_col(x, z, k * 0.85, h + k, cols)
		elif b == 1:
			if h < 1.5:
				continue
			var snowy := h + nn.get_noise_2d(x * 0.011 + 7.0, z * 0.011 - 3.0) * 8.0 > 84.0
			var p_pine := 0.05 if snowy or s > 0.75 else (0.85 if fo > 0.05 else 0.14)
			if u < p_pine and free_at.call(x, z, 3.0):
				var k := sc * (0.9 + r.randf() * 0.5)
				var g := 0.85 + r.randf() * 0.3
				Veg.pack(items.pine, pos - Vector3(0, 0.2, 0), rot, k, Color(g, g * (0.95 + r.randf() * 0.1), g), r.randf())
				placed.append(Vector2(x, z))
				_add_col(x, z, 0.36 * k, h + 12.0, cols)
				continue
			if (s > 0.42 and u > 0.5) or u > 0.97:
				var k := 0.6 + pow(r.randf(), 2.0) * 2.8
				Veg.pack(items.rock_cool, pos - Vector3(0, k * 0.15, 0), rot, k, Color(1, 1, 1), r.randf())
				if k > 0.75:
					_add_col(x, z, k * 0.85, h + k, cols)
				continue
			if u > 0.9 and s < 0.5 and free_at.call(x, z, 2.4):
				Veg.pack(items.fern, pos - Vector3(0, 0.1, 0), rot, sc * 0.8, Color(0.75, 0.85, 0.7), r.randf())
		elif b == 2:
			if s < 0.32 and u < 0.07 and free_at.call(x, z, 4.0):
				var k := 0.8 + r.randf() * 0.6
				Veg.pack(items.cactus, pos - Vector3(0, 0.15, 0), rot, k, Color(1, 1, 1), r.randf())
				placed.append(Vector2(x, z))
				_add_col(x, z, 0.42 * k, h + 5.0, cols)
				continue
			if s < 0.45 and u > 0.07 and u < 0.2 and free_at.call(x, z, 2.2):
				Veg.pack(items.dry, pos - Vector3(0, 0.05, 0), rot, sc * 0.9, Color(0.95, 0.75, 0.5), r.randf())
				placed.append(Vector2(x, z))
				continue
			if u > 0.93 or (s > 0.5 and u > 0.7):
				var k := 1.0 + pow(r.randf(), 1.8) * 3.2
				Veg.pack(items.rock_red, pos - Vector3(0, k * 0.2, 0), rot, k, Color(1, 1, 1), r.randf())
				_add_col(x, z, k * 0.85, h + k, cols)
		else:
			if h < 1.8:
				continue
			var p_tree := 0.02 if s > 0.55 else (0.6 if fo > 0.0 else 0.12)
			if u < p_tree and free_at.call(x, z, 4.2):
				var k := sc * (0.85 + r.randf() * 0.45)
				var pal: Color = AUTUMN[r.randi() % AUTUMN.size()]
				if r.randf() < 0.3:
					Veg.pack(items.birch, pos - Vector3(0, 0.2, 0), rot, k, pal.lerp(Color(1.0, 0.85, 0.2), 0.5), r.randf())
				else:
					Veg.pack(items.maple, pos - Vector3(0, 0.2, 0), rot, k, pal, r.randf())
				placed.append(Vector2(x, z))
				_add_col(x, z, 0.4 * k, h + 9.0, cols)
				continue
			if s < 0.5 and u < p_tree + 0.12 and free_at.call(x, z, 2.4):
				Veg.pack(items.bush, pos - Vector3(0, 0.1, 0), rot, sc, Color(1.1, 0.8, 0.5), r.randf())
				placed.append(Vector2(x, z))
				continue
			if u > 0.96 or (s > 0.45 and u > 0.6):
				var k := 0.6 + pow(r.randf(), 2.0) * 2.2
				Veg.pack(items.rock, pos - Vector3(0, k * 0.15, 0), rot, k, Color(0.95, 0.93, 0.9), r.randf())
				if k > 0.75:
					_add_col(x, z, k * 0.85, h + k, cols)
	veg.add_cell(vj.key, items)
	vcells[vj.key] = cols
	return true


# ------------------------------------------------------------------ road pieces + props
func _props_assets() -> void:
	props.tyre = PQ.tyre_stack()
	var parts := []
