	cp.append([Mk.box(0.1, 2.0, 0.1), Mk.xf(Vector3(0.8, 1.0, 0.05)), BH.V("metal", Color(0.5, 0.52, 0.55), 0.4)])
	cp.append([Mk.box(2.0, 1.0, 0.05), Mk.xf(Vector3(0, 1.7, 0)), BH.V("diel", Color(1.0, 0.75, 0.0), 0.6)])
