	props.chevron = BH.combine(cp)


func _mm(mesh: Mesh, buf: PackedFloat32Array, parent: Node3D, shadow := true, range_end := 600.0) -> void:
	if buf.is_empty():
		return
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_colors = true
	mm.use_custom_data = true
	mm.mesh = mesh
	mm.instance_count = buf.size() / 20
	mm.buffer = buf
	var mi := MultiMeshInstance3D.new()
	mi.multimesh = mm
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if shadow else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	mi.visibility_range_end = range_end
	parent.add_child(mi)


func _build_piece(pi: int) -> void:
	for st in 3:
		_piece_stage(pi, st)


func _piece_stage(pi: int, stage: int) -> void:
	var a := pi * PIECE
	var b := mini(a + PIECE, final - 1)
	if stage == 0:
		var node0 := Node3D.new()
		add_child(node0)
		var mesh := RoadMesh.build(px, pz, ph, ptx, ptz, psf, pdist, a, b, hw, 0)
		var mi := MeshInstance3D.new()
		mi.mesh = mesh
		mi.material_override = road_mat
		mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		mi.visibility_range_end = 1800.0
		node0.add_child(mi)
		pieces[pi] = {"node": node0, "cols": []}
		return
	var node: Node3D = pieces[pi].node
	var cols: Array = pieces[pi].cols
	if stage == 1:
		_piece_roadside(a, b, node, cols)
	else:
		_piece_signs(a, b, node, cols)


func _piece_roadside(a: int, b: int, node: Node3D, cols: Array) -> void:
	# marker posts every 26 m on both sides
	var posts := PackedFloat32Array()
	for i in range(a, b, 13):
		for s: float in [-1.0, 1.0]:
			var off := s * (hw + 1.6)
			var x := px[i] - ptz[i] * off
			var z := pz[i] + ptx[i] * off
			var y := h_carved(x, z, i)
			Veg.pack(posts, Vector3(x, y, z), atan2(-ptx[i], -ptz[i]) + (PI if s > 0 else 0.0), 1.0, Color(1, 1, 1), 0.0)
	_mm(props.post, posts, node, false, 300.0)
	# tyre walls and chevron boards at the sharpest bends
	var tyres := PackedFloat32Array()
	var boards := PackedFloat32Array()
	for i in range(maxi(a, 26), b):
		var c := absf(pcurv[i])
		if c < 0.022:
			continue
		var is_max := true
		for k in range(-25, 26):
			var q := clampi(i + k, 0, final - 1)
			if absf(pcurv[q]) > c:
				is_max = false
				break
		if not is_max:
			continue
		var side := 1.0 if pcurv[i] > 0.0 else -1.0
		for k in range(-3, 4):
			var q := clampi(i + k * 3, 0, final - 1)
			var off := (hw + 2.6) * side
			var x := px[q] - ptz[q] * off
			var z := pz[q] + ptx[q] * off
			var y := h_carved(x, z, q)
			Veg.pack(tyres, Vector3(x, y, z), float(q) * 1.7, 1.0, Color(1, 1, 1), 0.0)
			_add_col(x, z, 0.6, y + 1.3, cols)
		var q2 := clampi(i - 8, 0, final - 1)
		var off2 := (hw + 4.2) * side
		var bx := px[q2] - ptz[q2] * off2
		var bz := pz[q2] + ptx[q2] * off2
		var by := h_carved(bx, bz, q2)
		Veg.pack(boards, Vector3(bx, by, bz), atan2(-ptx[q2], -ptz[q2]) + (PI if side < 0 else 0.0), 1.0, Color(1, 1, 1), 0.0)
	_mm(props.tyre, tyres, node, true, 400.0)
	_mm(props.chevron, boards, node, true, 500.0)


func _piece_signs(a: int, b: int, node: Node3D, cols: Array) -> void:
	# jump signs
	for j in all_jumps:
		var si := int(j.i) - 30
		if si < a or si >= b:
			continue
		for s: float in [-1.0, 1.0]:
			var off := (hw + 2.4) * s
			var x := px[si] - ptz[si] * off
			var z := pz[si] + ptx[si] * off
			var y := h_carved(x, z, si)
			var sp := []
			sp.append([Mk.box(0.12, 2.2, 0.12), Mk.xf(Vector3(0, 1.1, 0)), BH.V("metal", Color(0.6, 0.6, 0.62), 0.5)])
			sp.append([Mk.box(1.3, 1.3, 0.06), Transform3D(Basis(Vector3.BACK, PI / 4), Vector3(0, 2.4, 0)), BH.V("diel", Color(1.0, 0.75, 0.1), 0.6)])
			var n := Props.mesh_node(node, sp, Transform3D(Basis(Vector3.UP, atan2(-ptx[si], -ptz[si]) + PI), Vector3(x, y, z)))
			Props.label(n, "JUMP!", Vector3(0, 2.4, 0.05), 40, Color(0.1, 0.1, 0.1), 0.0, 0)
	# kilometre gates
	for i in range(a, b):
		if i < START_I or (i - START_I) % GATE_EVERY != 0:
			continue
		var k := (i - START_I) / GATE_EVERY
		var g := Node3D.new()
		g.position = Vector3(px[i], ph[i], pz[i])
		g.rotation.y = atan2(-ptx[i], -ptz[i])
		node.add_child(g)
		var span := hw * 2.0 + 2.6
		var gp := []
		for s: float in [-1.0, 1.0]:
			for band in 6:
				gp.append([Mk.cyl(0.36, 0.42, 0.9, 14), Mk.xf(Vector3(s * span * 0.5, 0.45 + band * 0.9, 0)), BH.V("diel", Color(0.25, 0.88, 0.77) if band % 2 == 0 else Color(1, 1, 1), 0.5)])
			_add_col(px[i] - ptz[i] * s * span * 0.5, pz[i] + ptx[i] * s * span * 0.5, 0.5, ph[i] + 6.0, cols)
		gp.append([Mk.box(span + 1.0, 1.4, 0.3), Mk.xf(Vector3(0, 5.6, 0)), BH.V("diel", Color(0.05, 0.23, 0.31), 0.5)])
		for s: float in [-1.0, 1.0]:
			for cy in 3:
				for cxx in 3:
					var c := Color(0.95, 0.95, 0.95) if (cy + cxx) % 2 == 0 else Color(0.08, 0.08, 0.1)
					gp.append([Mk.box(0.4, 0.4, 0.32), Mk.xf(Vector3(s * (span * 0.5 - 0.1 - cxx * 0.4), 5.2 + cy * 0.4, 0)), BH.V("diel", c, 0.5)])
		Props.mesh_node(g, gp, Transform3D())
		var txt := "UNLIMITED  START" if k == 0 else "%d KM" % k
		Props.label(g, txt, Vector3(0, 5.6, -0.17), 96, Color(1, 1, 1), PI)
		Props.label(g, txt, Vector3(0, 5.6, 0.17), 96, Color(1, 1, 1), 0.0)


func update_props(p: Vector3, all_now := false) -> void:
	# road pieces within ~1.6 km ahead and 1 km behind
	ensure_road(p.z + 4200.0, 120 if not all_now else 6000)
	road_query(p.x, p.z, q_hint)
	var ci := int(q_i)
	var want := {}
	var pa := maxi(0, (ci - 500) / PIECE)
	var pb := (ci + 800) / PIECE
	var built := 0
	for pi in range(pa, pb + 1):
		if (pi + 1) * PIECE >= final:
			break
		want[pi] = true
		if not pieces.has(pi) and not ptodo.has(pi):
			if all_now:
				_build_piece(pi)
			else:
				ptodo.append(pi)
				ptodo.append(pi)
				ptodo.append(pi)
	for pi in pieces.keys():
		if not want.has(pi):
			pieces[pi].node.queue_free()
			_remove_cols(pieces[pi].cols)
			pieces.erase(pi)
	# vegetation cells within the far radius
	var r: float = veg.far_r + 64.0
	var c0 := int(floor((p.x - r) / VC))
	var c1 := int(floor((p.x + r) / VC))
	var z0 := int(floor((p.z - r) / VC))
	var z1 := int(floor((p.z + r) / VC))
	var keep := {}
	var todo := []
	for cz in range(z0, z1 + 1):
		for cx in range(c0, c1 + 1):
			var ctr := Vector2((cx + 0.5) * VC, (cz + 0.5) * VC)
			var d := ctr.distance_to(Vector2(p.x, p.z))
			if d > r:
				continue
			var key := Vector2i(cx, cz)
			keep[key] = true
			if not vcells.has(key):
				todo.append([d, key])
	todo.sort_custom(func(x, y): return x[0] < y[0])
	vjobs = todo
	for key in vcells.keys():
		if not keep.has(key):
			var ctr := Vector2((key.x + 0.5) * VC, (key.y + 0.5) * VC)
			if ctr.distance_to(Vector2(p.x, p.z)) > r + 200.0:
				veg.remove_cell(key)
				_remove_cols(vcells[key])
				vcells.erase(key)
	if all_now:
		for t in vjobs:
			_veg_cell(t[1].x, t[1].y)
		vjobs.clear()


var pmax := [0, 0, 0, 0]
var vcur: VegJob = null
var ptodo := []
var pstage := {}


func update(dt: float, cam_pos: Vector3, budget := -1) -> void:
	cam = cam_pos
	var a0 := Time.get_ticks_usec()
	terrain.update(cam, budget)
	var t0 := Time.get_ticks_usec()
	if Vector2(cam.x - last_plan.x, cam.z - last_plan.z).length() > 24.0:
		last_plan = cam
		update_props(cam)
	# one road piece stage per frame
	if not ptodo.is_empty():
		var pi: int = ptodo.pop_front()
		var st: int = pstage.get(pi, 0)
		if st == 0 and pieces.has(pi):
			st = 3
		if st < 3:
			_piece_stage(pi, st)
		pstage[pi] = st + 1
		if st + 1 >= 3:
			pstage.erase(pi)
	var t1 := Time.get_ticks_usec()
	# vegetation cells, nearest first, a slice of work per frame
	while Time.get_ticks_usec() - t1 < 2000:
		if vcur == null:
			if vjobs.is_empty():
				break
			var t = vjobs.pop_front()
			if vcells.has(t[1]):
				continue
			vcur = _veg_begin(t[1].x, t[1].y)
		if _veg_run(vcur, 2000 - (Time.get_ticks_usec() - t1)):
			vcur = null
	var t2 := Time.get_ticks_usec()
	veg.update(cam)
	var t3 := Time.get_ticks_usec()
	pmax[0] = maxi(pmax[0], t0 - a0)
	pmax[1] = maxi(pmax[1], t1 - t0)
	pmax[2] = maxi(pmax[2], t2 - t1)
	pmax[3] = maxi(pmax[3], t3 - t2)
	road_mat.set_shader_parameter("cloud_off", terrain.cloud_off)


func apply_gfx(level: int) -> void:
	gfx = level
	terrain.configure(level)
	veg.configure(level)
	last_plan = Vector3(1e9, 0, 1e9)


func set_weather(wet: float, night: float, rain: float) -> void:
	terrain.set_param("wet", wet)
	terrain.set_water_param("rain", rain)
	terrain.set_water_param("night", night)
	road_mat.set_shader_parameter("wet", wet)
	veg.set_param("wet", wet)
	terrain.grass_mat.set_shader_parameter("wet", wet)

