extends RefCounted
## Vegetation and rock meshes, generated in code. Every species has a detailed near mesh ("hq") and a light far
## mesh ("lo"). Surface 0 is solid (bark, stems, rock: vertex colours in linear space, alpha = roughness),
## surface 1 is leaves (UVs into the leaf atlas, vertex colour tints the grey texture). Forward is -Z, ground y = 0.

const ATLAS_CELLS := 8  # 4 x 2 cells of 256 x 512 in a 1024 x 1024 texture
enum { C_PALM, C_JUNGLE, C_FERN, C_PINE, C_MAPLE, C_ROUND, C_FLOWER, C_GRASS }


class MB:
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var uv := PackedVector2Array()
	var c := PackedColorArray()
	var idx := PackedInt32Array()

	func vert(p: Vector3, nn: Vector3, t: Vector2, col: Color) -> int:
		v.append(p)
		n.append(nn)
		uv.append(t)
		c.append(col)
		return v.size() - 1

	func tri(a: int, b: int, cc: int) -> void:
		idx.append(a)
		idx.append(b)
		idx.append(cc)

	func arrays() -> Array:
		var arr := []
		arr.resize(Mesh.ARRAY_MAX)
		arr[Mesh.ARRAY_VERTEX] = v
		arr[Mesh.ARRAY_NORMAL] = n
		arr[Mesh.ARRAY_TEX_UV] = uv
		arr[Mesh.ARRAY_COLOR] = c
		arr[Mesh.ARRAY_INDEX] = idx
		return arr

	func empty() -> bool:
		return idx.is_empty()


static func lin(col: Color, rough := 0.9) -> Color:
	var l := col.srgb_to_linear()
	return Color(l.r, l.g, l.b, rough)


static func finish(solid: MB, leaves: MB) -> ArrayMesh:
	var m := ArrayMesh.new()
	if solid.empty():
		solid.tri(solid.vert(Vector3.ZERO, Vector3.UP, Vector2.ZERO, Color.BLACK), solid.vert(Vector3.ZERO, Vector3.UP, Vector2.ZERO, Color.BLACK), solid.vert(Vector3.ZERO, Vector3.UP, Vector2.ZERO, Color.BLACK))
	m.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, solid.arrays())
	if not leaves.empty():
		m.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, leaves.arrays())
	return m


static func cell_uv(cell: int, u: float, v: float) -> Vector2:
	return Vector2((cell % 4) * 0.25 + clampf(u, 0.002, 0.998) * 0.25, (cell / 4) * 0.5 + clampf(v, 0.002, 0.998) * 0.5)


## Tube along points with per-point radius and colour; vertex colours darken toward the base (fake AO).
static func tube(mb: MB, pts: Array, radii: Array, segs: int, col: Color, ao_base := 0.75, uv_scale := 1.0) -> void:
	var cnt := pts.size()
	var nrm := Vector3.ZERO
	var base := mb.v.size()
	for i in cnt:
		var p: Vector3 = pts[i]
		var t: Vector3
		if i == 0:
			t = (pts[1] - pts[0]).normalized()
		elif i == cnt - 1:
			t = (pts[i] - pts[i - 1]).normalized()
		else:
			t = (pts[i + 1] - pts[i - 1]).normalized()
		if i == 0:
			nrm = t.cross(Vector3.UP if absf(t.y) < 0.9 else Vector3.RIGHT).normalized()
		else:
			nrm = (nrm - t * nrm.dot(t)).normalized()
		var b := t.cross(nrm)
		var r: float = radii[i]
		var k := lerpf(ao_base, 1.0, clampf(p.y / 2.5, 0.0, 1.0))
		var cc := Color(col.r * k, col.g * k, col.b * k, col.a)
		for s in segs + 1:
			var a := TAU * s / segs
			var d := nrm * cos(a) + b * sin(a)
			mb.vert(p + d * r, d, Vector2(float(s) / segs, p.y * uv_scale), cc)
	var w := segs + 1
	for i in cnt - 1:
		for s in segs:
			var a := base + i * w + s
			mb.tri(a, a + w, a + 1)
			mb.tri(a + 1, a + w, a + w + 1)


## Leaf card strip: starts at `p`, runs along `dir` for `length`, `side` gives width; droop bends it down (quadratic).
static func card(mb: MB, p: Vector3, dir: Vector3, side: Vector3, length: float, width: float, cell: int, col: Color,
		droop := 0.0, segs := 1, twist := 0.0) -> void:
	dir = dir.normalized()
	side = side.normalized()
	var nrm := side.cross(dir).normalized()
	if nrm.y < 0.0:
		nrm = -nrm
	var base := mb.v.size()
	for s in segs + 1:
		var t := float(s) / segs
		var c := p + dir * length * t + Vector3(0, -droop * t * t * length, 0)
		var sd := side.rotated(dir, twist * t) if twist != 0.0 else side
		var nn := (nrm + Vector3(0, 0.6, 0)).normalized()
		var k := lerpf(0.8, 1.05, t)
		var cc := Color(col.r * k, col.g * k, col.b * k, col.a)
		mb.vert(c - sd * width * 0.5, nn, cell_uv(cell, 0.0, 1.0 - t), cc)
		mb.vert(c + sd * width * 0.5, nn, cell_uv(cell, 1.0, 1.0 - t), cc)
	for s in segs:
		var a := base + s * 2
		mb.tri(a, a + 2, a + 1)
		mb.tri(a + 1, a + 2, a + 3)


## Flat card centred at `c`, facing `nrm`, with the cell's vertical axis along `up`.
static func blade(mb: MB, c: Vector3, nrm: Vector3, up: Vector3, w: float, h: float, cell: int, col: Color) -> void:
	var side := up.cross(nrm).normalized()
	var u2 := nrm.cross(side).normalized()
	var nn := (nrm.normalized() * 0.4 + (c - Vector3(0, c.y * 0.5, 0)).normalized() * 0.6).normalized()
	var a := mb.vert(c - side * w * 0.5 - u2 * h * 0.5, nn, cell_uv(cell, 0, 1), col)
	var b := mb.vert(c + side * w * 0.5 - u2 * h * 0.5, nn, cell_uv(cell, 1, 1), col)
	var d := mb.vert(c + side * w * 0.5 + u2 * h * 0.5, nn, cell_uv(cell, 1, 0), col)
	var e := mb.vert(c - side * w * 0.5 + u2 * h * 0.5, nn, cell_uv(cell, 0, 0), col)
	mb.tri(a, b, d)
	mb.tri(a, d, e)


## Noise-displaced blob with per-vertex colour (rocks, cacti tops, canopies).
static func blob(mb: MB, center: Vector3, r: float, segs: int, rings: int, amount: float, seed: int, squash: Vector3, col: Color, flat_bottom := true, strata := false) -> void:
	var nz := FastNoiseLite.new()
	nz.seed = seed
	nz.frequency = 1.1
	nz.fractal_octaves = 3
	var base := mb.v.size()
	var pos := []
	for j in rings + 1:
		var th := PI * j / rings
		for i in segs + 1:
			var ph := TAU * i / segs
			var d := Vector3(sin(th) * cos(ph), cos(th), sin(th) * sin(ph))
			var k := 1.0 + nz.get_noise_3dv(d * 1.3) * amount
			var p := Vector3(d.x * squash.x, d.y * squash.y, d.z * squash.z) * r * k
			if flat_bottom and p.y < -0.2 * r:
				p.y = -0.2 * r + (p.y + 0.2 * r) * 0.15
			pos.append(p)
	# normals from the grid
	var w := segs + 1
	for j in rings + 1:
		for i in segs + 1:
			var p: Vector3 = pos[j * w + i]
			var pu: Vector3 = pos[mini(j + 1, rings) * w + i] - pos[maxi(j - 1, 0) * w + i]
			var pv: Vector3 = pos[j * w + (i + 1) % segs] - pos[j * w + (i - 1 + segs) % segs]
			var nn := pv.cross(pu).normalized()
			if nn.dot(p) < 0.0:
				nn = -nn
			if j == 0:
				nn = Vector3.UP
			elif j == rings:
				nn = Vector3.DOWN
			elif nn.length_squared() < 1e-8:
				nn = p.normalized()
			var cc := col
			if strata:
				var s := 0.5 + 0.5 * sin(p.y * 9.0 + sin(p.x * 2.0 + p.z * 1.7) * 1.4)
				var kk := lerpf(0.82, 1.08, s) * (0.88 + 0.14 * clampf(nn.y, 0.0, 1.0))
				cc = Color(col.r * kk, col.g * kk, col.b * kk, col.a)
			else:
				var kk := 0.8 + 0.25 * clampf(nn.y, -0.3, 1.0)
				cc = Color(col.r * kk, col.g * kk, col.b * kk, col.a)
			mb.vert(center + p, nn, Vector2(float(i) / segs, float(j) / rings), cc)
	for j in rings:
		for i in segs:
			var a := base + j * w + i
			mb.tri(a, a + 1, a + w)
			mb.tri(a + 1, a + w + 1, a + w)


# ================================================================== coconut palm (~9 m, leaning)
static func palm(hq: bool) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 21
	var solid := MB.new()
	var leaves := MB.new()
	var H := 9.0
	var lean := 1.5
	var path := func(t: float) -> Vector3:
		return Vector3(lean * pow(t, 1.7), H * t, 0.0)
	var pts := []
	var rad := []
	var segs := 22 if hq else 6
	for i in segs + 1:
		var t := float(i) / segs
		pts.append(path.call(t) + Vector3(0, -0.4 if i == 0 else 0.0, 0))
		var r := lerpf(0.24, 0.16, t) + 0.12 * pow(1.0 - t, 7.0)
		if hq and i % 2 == 1:
			r *= 1.06
		rad.append(r)
	tube(solid, pts, rad, 9 if hq else 5, lin(Color(0.52, 0.43, 0.33), 0.95), 0.7, 1.4)
	var top: Vector3 = path.call(1.0)
	if hq:
		# leaf bases and coconuts
		blob(solid, top + Vector3(0, -0.1, 0), 0.32, 8, 5, 0.15, 3, Vector3(1, 1.3, 1), lin(Color(0.42, 0.36, 0.22), 0.9), false)
		for k in 7:
			var a := TAU * k / 7.0 + 0.3
			var cp := top + Vector3(cos(a) * 0.28, -0.42 - (k % 2) * 0.12, sin(a) * 0.28)
			var cc := Color(0.35, 0.45, 0.12) if k % 3 != 0 else Color(0.48, 0.34, 0.16)
			blob(solid, cp, 0.15, 7, 4, 0.08, 10 + k, Vector3(1, 1.1, 1), lin(cc, 0.6), false)
	var fronds := 16 if hq else 9
	for f in fronds:
		var a := TAU * f / fronds + rng.randf() * 0.25
		var young := f % 5 == 0
		var elev := (0.75 if young else 0.25) + rng.randf() * 0.3
		var L := 4.2 + rng.randf() * 1.0
		var droop := (0.25 if young else 0.75) + rng.randf() * 0.25
		var hz := Vector3(cos(a), 0, sin(a))
		var dir := (hz * cos(elev) + Vector3(0, sin(elev), 0)).normalized()
		var side := hz.cross(Vector3.UP).normalized()
		var g := Color(0.33, 0.52, 0.16).lerp(Color(0.48, 0.6, 0.2), rng.randf())
		if not young and rng.randf() < 0.12:
			g = Color(0.6, 0.52, 0.28)
		if hq:
			# rachis + two cards in a shallow V so the frond has volume
			var rp := []
			var rr := []
			for s in 6:
				var t := s / 5.0
				rp.append(top + dir * L * t + Vector3(0, -droop * t * t * L, 0))
				rr.append(lerpf(0.05, 0.012, t))
			tube(solid, rp, rr, 4, lin(Color(0.55, 0.55, 0.3), 0.8), 1.0)
			for sg: float in [-1.0, 1.0]:
				var sd := (side * sg + Vector3(0, -0.35, 0)).normalized()
				card(leaves, top + side * sg * 0.02, dir, sd, L, 1.15, C_PALM, lin(g, 0.7), droop, 6)
		else:
			card(leaves, top, dir, side, L, 2.0, C_PALM, lin(g, 0.7), droop, 3)
	return finish(solid, leaves)


# ================================================================== jungle tree (~13 m, buttress roots, cloud canopy)
static func jungle(hq: bool, variant := 0) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 40 + variant
	var solid := MB.new()
	var leaves := MB.new()
	var bark := lin(Color(0.5, 0.45, 0.38), 0.95)
	var H := 8.5 + variant * 1.5
	tube(solid, [Vector3(0, -0.5, 0), Vector3(0.05, 2.0, 0), Vector3(-0.1, 5.0, 0.1), Vector3(0.1, H, 0)], [0.42, 0.33, 0.27, 0.2], 10 if hq else 5, bark, 0.6, 0.6)
	if hq:
		for k in 5:
			var a := TAU * k / 5.0 + rng.randf() * 0.4
			var o := Vector3(cos(a), 0, sin(a))
			tube(solid, [o * 0.15 + Vector3(0, 1.6, 0), o * 0.7 + Vector3(0, 0.4, 0), o * 1.2 + Vector3(0, -0.25, 0)], [0.22, 0.14, 0.06], 5, bark, 0.6)
	var tips := []
	var nb := 6 if hq else 4
	for k in nb:
		var a := TAU * k / nb + rng.randf() * 0.5
		var o := Vector3(cos(a), 0, sin(a))
		var y0 := H * (0.55 + 0.4 * float(k) / nb)
		var start := Vector3(0.05, y0, 0)
		var end := start + o * (2.2 + rng.randf() * 1.6) + Vector3(0, 1.2 + rng.randf() * 1.2, 0)
		if hq:
			tube(solid, [start, start.lerp(end, 0.5) + Vector3(0, 0.3, 0), end], [0.14, 0.09, 0.04], 5, bark, 1.0)
		tips.append(end)
	tips.append(Vector3(0.1, H + 1.0, 0))
	var greens := [Color(0.2, 0.42, 0.12), Color(0.26, 0.5, 0.14), Color(0.17, 0.36, 0.1)]
	for i in tips.size():
		var c: Vector3 = tips[i]
		var cards := 9 if hq else 3
		var rad := 1.9 + rng.randf() * 0.6
		for k in cards:
			var a := rng.randf() * TAU
			var e := rng.randf_range(-0.3, 0.9)
			var off := Vector3(cos(a) * cos(e), sin(e) * 0.6, sin(a) * cos(e)) * rad * (0.4 if hq else 0.2)
			var nrm := (off + Vector3(0, 0.6, 0)).normalized()
			var up := Vector3(cos(a + 1.3), 0.3, sin(a + 1.3)).normalized()
			var sz := rad * (1.25 if hq else 2.0)
			var col: Color = greens[(i + k) % 3]
			var kk := lerpf(0.75, 1.1, clampf(off.y / rad + 0.5, 0.0, 1.0))
			blade(leaves, c + off, nrm, up, sz, sz * 1.6, C_JUNGLE, lin(Color(col.r * kk, col.g * kk, col.b * kk), 0.65))
	return finish(solid, leaves)


# ================================================================== banana plant (~4 m)
static func banana(hq: bool) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 55
	var solid := MB.new()
	var leaves := MB.new()
	tube(solid, [Vector3(0, -0.3, 0), Vector3(0, 1.4, 0), Vector3(0.05, 2.6, 0)], [0.2, 0.16, 0.12], 7 if hq else 4, lin(Color(0.45, 0.5, 0.26), 0.8), 0.7)
	var top := Vector3(0.05, 2.5, 0)
	var nl := 9 if hq else 6
	for k in nl:
		var a := TAU * k / nl + rng.randf() * 0.4
		var hz := Vector3(cos(a), 0, sin(a))
		var elev := 0.9 - rng.randf() * 0.5
		var dir := (hz * cos(elev) + Vector3(0, sin(elev), 0)).normalized()
		var side := hz.cross(Vector3.UP).normalized()
		var L := 2.2 + rng.randf() * 0.6
		var col := lin(Color(0.3, 0.55, 0.15).lerp(Color(0.42, 0.62, 0.2), rng.randf()), 0.55)
		var segs := 6 if hq else 2
		var base := leaves.v.size()
		var droop := 0.45 + rng.randf() * 0.3
		# paddle leaf: widest in the middle, slight V fold along the midrib
		for s in segs + 1:
			var t := float(s) / segs
			var c := top + dir * L * t + Vector3(0, -droop * t * t * L, 0)
			var w := 0.55 * sin(PI * minf(t * 1.05, 1.0)) ** 0.6 + 0.02
			var nn := (side.cross(dir) + Vector3(0, 0.8, 0)).normalized()
			if nn.y < 0:
				nn = -nn
			var fold := Vector3(0, 0.12 * w, 0)
			leaves.vert(c - side * w + fold * -1.0, nn, cell_uv(C_GRASS, 0.3, 1.0 - t), col)
			leaves.vert(c + fold, nn, cell_uv(C_GRASS, 0.5, 1.0 - t), Color(col.r * 1.15, col.g * 1.1, col.b, col.a))
			leaves.vert(c + side * w - fold, nn, cell_uv(C_GRASS, 0.3, 1.0 - t), col)
		for s in segs:
			var a0 := base + s * 3
			for q in 2:
				var p := a0 + q
				leaves.tri(p, p + 3, p + 1)
				leaves.tri(p + 1, p + 3, p + 4)
	return finish(solid, leaves)


# ================================================================== bush (~1.6 m, flowering variant)
static func bush(hq: bool, flowers := false) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 70 + (1 if flowers else 0)
	var solid := MB.new()
	var leaves := MB.new()
	var n := 14 if hq else 5
	for k in n:
		var a := rng.randf() * TAU
		var e := rng.randf_range(0.0, 1.1)
		var c := Vector3(cos(a) * 0.5, 0.65 + sin(e) * 0.45, sin(a) * 0.5)
		var nrm := (c - Vector3(0, 0.3, 0)).normalized()
		var up := Vector3(cos(a + 1.6), 0.4, sin(a + 1.6)).normalized()
		var col := Color(0.22, 0.45, 0.14).lerp(Color(0.3, 0.52, 0.16), rng.randf())
		blade(leaves, c, nrm, up, 1.3 if hq else 1.8, 1.3 if hq else 1.8, C_ROUND if k % 2 == 0 else C_JUNGLE, lin(col, 0.7))
	if flowers:
		for k in (6 if hq else 2):
			var a := rng.randf() * TAU
			var c := Vector3(cos(a) * 0.65, 0.9 + rng.randf() * 0.4, sin(a) * 0.65)
			blade(leaves, c, (c - Vector3(0, 0.5, 0)).normalized(), Vector3.UP, 0.8, 0.8, C_FLOWER, lin(Color(1.0, 0.35, 0.45), 0.6))
	return finish(solid, leaves)


# ================================================================== fern (~1.2 m)
static func fern(hq: bool) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 80
	var solid := MB.new()
	var leaves := MB.new()
	var n := 11 if hq else 5
	for k in n:
		var a := TAU * k / n + rng.randf() * 0.3
		var hz := Vector3(cos(a), 0, sin(a))
		var elev := 0.7 + rng.randf() * 0.35
		var dir := (hz * cos(elev) + Vector3(0, sin(elev), 0)).normalized()
		var col := Color(0.24, 0.5, 0.14).lerp(Color(0.36, 0.58, 0.18), rng.randf())
		card(leaves, Vector3(0, 0.05, 0), dir, hz.cross(Vector3.UP), 1.4 + rng.randf() * 0.4, 0.7, C_FERN, lin(col, 0.7), 0.55, 4 if hq else 2)
	return finish(solid, leaves)


# ================================================================== rock (~1 m radius, scaled per instance)
static func rock(hq: bool, variant := 0, col := Color(0.66, 0.63, 0.58)) -> ArrayMesh:
	var solid := MB.new()
	var leaves := MB.new()
	blob(solid, Vector3(0, -0.05, 0), 1.0, 22 if hq else 8, 11 if hq else 4, 0.45, 40 + variant, Vector3(1.25, 0.72, 1.0), lin(col, 0.9), true, true)
	return finish(solid, leaves)


# ================================================================== pine (~14 m)
static func pine(hq: bool) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 90
	var solid := MB.new()
	var leaves := MB.new()
	var H := 14.0
	tube(solid, [Vector3(0, -0.4, 0), Vector3(0, H * 0.5, 0), Vector3(0, H, 0)], [0.32, 0.2, 0.05], 8 if hq else 4, lin(Color(0.4, 0.3, 0.22), 0.95), 0.7)
	# dark inner cones give the crown volume so it never looks see-through
	var tiers := 4 if hq else 3
	for t in tiers:
		var y0 := lerpf(2.4, H * 0.62, float(t) / tiers)
		var R := lerpf(2.9, 1.0, float(t) / tiers)
		var h := (H - y0) * 0.62
		var segs := 10 if hq else 6
		var base := solid.v.size()
		var col := lin(Color(0.1, 0.2, 0.1).lerp(Color(0.14, 0.26, 0.13), float(t) / tiers), 0.9)
		for k in segs + 1:
			var a := TAU * k / segs
			var d := Vector3(cos(a), 0, sin(a))
			var nrm := (d + Vector3(0, R / h, 0)).normalized()
			solid.vert(Vector3(0, y0, 0) + d * R, nrm, Vector2(float(k) / segs, 0), Color(col.r * 0.8, col.g * 0.8, col.b * 0.8, col.a))
			solid.vert(Vector3(0, y0 + h, 0), nrm, Vector2(float(k) / segs, 1), col)
		for k in segs:
			var i0 := base + k * 2
			solid.tri(i0, i0 + 1, i0 + 2)
			solid.tri(i0 + 2, i0 + 1, i0 + 3)
	var layers := 10 if hq else 5
	for l in layers:
		var t := float(l) / (layers - 1)
		var y := lerpf(2.4, H - 0.5, t)
		var R := lerpf(3.6, 0.8, t)
		var nb := (9 if hq else 5) if t < 0.8 else 5
		for k in nb:
			var a := TAU * k / nb + l * 0.7 + rng.randf() * 0.3
			var hz := Vector3(cos(a), 0, sin(a))
			var dir := (hz + Vector3(0, -0.12, 0)).normalized()
			var col := Color(0.13, 0.27, 0.12).lerp(Color(0.2, 0.34, 0.15), rng.randf()) * lerpf(0.75, 1.1, t)
			card(leaves, Vector3(0, y, 0), dir, hz.cross(Vector3.UP).rotated(dir, 0.4), R, R * 0.95, C_PINE, lin(col, 0.8), 0.2, 2 if hq else 1)
			if hq:
				card(leaves, Vector3(0, y + 0.15, 0), dir, Vector3.UP.rotated(dir, 0.3), R * 0.9, R * 0.6, C_PINE, lin(col * 0.9, 0.8), 0.15, 1)
	return finish(solid, leaves)


# ================================================================== broadleaf (maple / birch), leaves tinted per instance
static func broadleaf(hq: bool, birch := false) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 100 + (1 if birch else 0)
	var solid := MB.new()
	var leaves := MB.new()
	var bark := lin(Color(0.86, 0.84, 0.8) if birch else Color(0.38, 0.3, 0.24), 0.9)
	var H := 9.0 if birch else 7.5
	tube(solid, [Vector3(0, -0.4, 0), Vector3(0.05, H * 0.45, 0), Vector3(-0.05, H, 0)], [0.24 if birch else 0.34, 0.17, 0.06], 8 if hq else 4, bark, 0.8)
	var tips := []
	var nb := 7 if hq else 4
	for k in nb:
		var a := TAU * k / nb + rng.randf() * 0.5
		var o := Vector3(cos(a), 0, sin(a))
		var y0 := H * (0.4 + 0.45 * float(k) / nb)
		var end := Vector3(0, y0, 0) + o * (1.6 + rng.randf()) + Vector3(0, 1.4 + rng.randf(), 0)
		if hq:
			tube(solid, [Vector3(0, y0, 0), end], [0.1, 0.03], 5, bark, 1.0)
		tips.append(end)
	tips.append(Vector3(0, H + 0.6, 0))
	var cell := C_ROUND if birch else C_MAPLE
	for i in tips.size():
		var c: Vector3 = tips[i]
		var cards := 8 if hq else 3
		var rad := 1.7 + rng.randf() * 0.5
		for k in cards:
			var a := rng.randf() * TAU
			var e := rng.randf_range(-0.4, 0.9)
			var off := Vector3(cos(a) * cos(e), sin(e) * 0.7, sin(a) * cos(e)) * rad * (0.45 if hq else 0.2)
			var nrm := (off + Vector3(0, 0.5, 0)).normalized()
			var up := Vector3(cos(a + 1.3), 0.4, sin(a + 1.3)).normalized()
			var sz := rad * (1.2 if hq else 1.9)
			var kk := lerpf(0.7, 1.1, clampf(off.y / rad + 0.5, 0.0, 1.0))
			blade(leaves, c + off, nrm, up, sz, sz * 1.8, cell, lin(Color(kk, kk, kk), 0.7))
	return finish(solid, leaves)


# ================================================================== saguaro cactus (~5 m)
static func cactus(hq: bool) -> ArrayMesh:
	var solid := MB.new()
	var leaves := MB.new()
	var col := lin(Color(0.25, 0.45, 0.2), 0.7)
	var seg := 12 if hq else 5
	var ribbed := func(pts: Array, r: float) -> void:
		var radii := []
		for p in pts:
			radii.append(r)
		var base := solid.v.size()
		tube(solid, pts, radii, seg, col, 0.85)
		if hq:
			# ribs: push every other ring vertex out a little
			for i in range(base, solid.v.size()):
				var k := (i - base) % (seg + 1)
				if k % 2 == 0:
					solid.v[i] += solid.n[i] * r * 0.09
				else:
					var cc := solid.c[i]
					solid.c[i] = Color(cc.r * 0.8, cc.g * 0.8, cc.b * 0.8, cc.a)
	ribbed.call([Vector3(0, -0.3, 0), Vector3(0, 2.5, 0), Vector3(0, 4.6, 0), Vector3(0, 4.95, 0)], 0.38)
	blob(solid, Vector3(0, 4.95, 0), 0.37, seg, 4, 0.02, 5, Vector3(1, 0.7, 1), col, false)
	for arm in [[1.0, 1.7, 1.5], [-1.0, 2.4, 1.1]]:
		var sd: float = arm[0]
		var y0: float = arm[1]
		var up: float = arm[2]
		ribbed.call([Vector3(sd * 0.2, y0, 0), Vector3(sd * 0.75, y0 + 0.05, 0), Vector3(sd * 0.95, y0 + 0.35, 0), Vector3(sd * 0.98, y0 + up, 0)], 0.24)
		blob(solid, Vector3(sd * 0.98, y0 + up, 0), 0.235, seg, 3, 0.02, 6, Vector3(1, 0.7, 1), col, false)
	return finish(solid, leaves)


# ================================================================== dry shrub / tumbleweed for the canyon
static func dry_shrub(hq: bool) -> ArrayMesh:
	var rng := RandomNumberGenerator.new()
	rng.seed = 120
	var solid := MB.new()
	var leaves := MB.new()
	var n := 10 if hq else 4
	for k in n:
		var a := rng.randf() * TAU
		var c := Vector3(cos(a) * 0.4, 0.45 + rng.randf() * 0.3, sin(a) * 0.4)
		blade(leaves, c, (c - Vector3(0, 0.2, 0)).normalized(), Vector3(cos(a + 1.6), 0.4, sin(a + 1.6)).normalized(), 1.1, 1.0, C_ROUND, lin(Color(0.55, 0.5, 0.3), 0.9))
	return finish(solid, leaves)


# ================================================================== grass clump card bundle (used far from the road in the endless world)
static func tall_grass(hq: bool) -> ArrayMesh:
	var solid := MB.new()
	var leaves := MB.new()
	for k in (3 if hq else 2):
		var a := PI * k / 3.0
		var nrm := Vector3(cos(a), 0, sin(a))
		blade(leaves, Vector3(0, 0.45, 0), nrm, Vector3.UP, 1.2, 0.95, C_GRASS, lin(Color(0.5, 0.6, 0.3), 0.8))
	return finish(solid, leaves)

