	{"id": "patrol", "name": "JUNGLE PATROL", "need": 4, "accel": 12.5, "vmax": 46.0, "grip": 8.2, "dgrip": 1.45, "steer": 2.15, "dsteer": 2.5,
		"loose": 1.16, "engine": 0.78, "mass": 1.4, "color": 1, "desc": "Big and tough. Nothing stops it off-road."},
	{"id": "muscle", "name": "MUSCLE THUNDER", "need": 6, "accel": 15.0, "vmax": 54.0, "grip": 6.8, "dgrip": 1.25, "steer": 2.2, "dsteer": 2.8,
		"loose": 0.92, "engine": 0.66, "mass": 1.25, "color": 3, "desc": "Huge V8 power on the coast road."},
	{"id": "falcon", "name": "GOLDEN FALCON", "need": 9, "accel": 17.0, "vmax": 60.0, "grip": 8.8, "dgrip": 1.35, "steer": 2.6, "dsteer": 3.0,
		"loose": 1.0, "engine": 1.55, "mass": 1.1, "color": 5, "desc": "The fastest car on the island. Pure gold!"},
