extends Control
## In-game HUD: speedometer + gear, nitro, lap/time/position, splits, pace notes, minimap, popups and banners.

var game
var map_pts := PackedVector2Array()
var map_scale := 1.0
var map_center := Vector2.ZERO


func _ready() -> void:
	set_anchors_preset(Control.PRESET_FULL_RECT)
	mouse_filter = Control.MOUSE_FILTER_IGNORE


func _process(_d: float) -> void:
	visible = game != null and game.driving()
	if visible:
		queue_redraw()


func _pill(p: Vector2, w: float, h: float, a := 0.62) -> void:
	var sb := G.box(Color(0.02, 0.1, 0.16, a), 18, 0)
	draw_style_box(sb, Rect2(p, Vector2(w, h)))


func _draw() -> void:
	var vs := get_viewport_rect().size
	var W := vs.x
	var H := vs.y
	var c = game.player
	var t := Time.get_ticks_msec() / 1000.0
	var y := 18.0
	# ---------- mode info (top left)
	match game.mode:
		"race":
			_pill(Vector2(18, y), 270, 124)
			G.draw_text_l(self, Vector2(34, y + 22), "ISLAND RACE", 22, Color(1.0, 0.6, 0.5), G.font_title, 6)
			var pos_s: String = ["1st", "2nd", "3rd", "4th", "5th", "6th"][clampi(game.race_pos - 1, 0, 5)]
			G.draw_text_l(self, Vector2(34, y + 62), pos_s, 46, Color.WHITE, G.font_digits, 8)
			G.draw_text_l(self, Vector2(140, y + 66), "/ %d" % (game.ais.size() + 1), 26, G.CREAM, G.font_digits, 6)
			G.draw_text_l(self, Vector2(34, y + 102), "LAP %d/%d   %s" % [clampi(game.lap + 1, 1, game.laps), game.laps, G.fmt_time(game.t_run)], 22, G.CREAM, G.font_bold, 6)
		"tt":
			_pill(Vector2(18, y), 300, 124)
			G.draw_text_l(self, Vector2(34, y + 22), "TIME TRIAL  LAP %d/%d" % [clampi(game.lap + 1, 1, game.laps), game.laps], 22, Color(0.6, 0.9, 1.0), G.font_title, 6)
			G.draw_text_l(self, Vector2(34, y + 62), G.fmt_time(game.lap_t), 42, Color.WHITE, G.font_digits, 8)
			var best: float = float(G.data.best_lap)
			G.draw_text_l(self, Vector2(34, y + 102), "BEST " + (G.fmt_time(best) if best > 0.0 else "--:--.--"), 22, G.GOLD, G.font_bold, 6)
		"explore":
			_pill(Vector2(18, y), 250, 100)
			G.draw_text_l(self, Vector2(34, y + 22), "EXPLORE", 22, G.GOLD, G.font_title, 6)
			G.draw_star(self, Vector2(52, y + 62), 18, true, 3.0)
			G.draw_text_l(self, Vector2(80, y + 62), "%d / 20" % game.found.size(), 36, Color.WHITE, G.font_digits, 8)
			G.draw_text_l(self, Vector2(180, y + 86), G.fmt_time(game.t_run), 16, G.CREAM, G.font_bold, 5)
			var tgt: Vector3 = game.nearest_star()
			if tgt != Vector3.INF:
				_arrow_to(tgt, Vector2(W * 0.5, 120), G.GOLD)
		"inf":
			var ta: bool = game.inf_mode == "ta"
			_pill(Vector2(18, y), 280, 130 if ta else 112)
			G.draw_text_l(self, Vector2(34, y + 22), "TIME ATTACK" if ta else "UNLIMITED", 22, Color(0.6, 1.0, 0.6) if not ta else Color(0.8, 0.65, 1.0), G.font_title, 6)
			if ta:
				var low: bool = game.t_left < 10.0
				var tc := Color(1.0, 0.35, 0.3) if low and int(t * 4.0) % 2 == 0 else Color.WHITE
				G.draw_text_l(self, Vector2(34, y + 62), "%.1f" % maxf(game.t_left, 0.0), 44, tc, G.font_digits, 8)
				G.draw_text_l(self, Vector2(160, y + 66), "sec", 20, G.CREAM, G.font_bold, 5)
				G.draw_text_l(self, Vector2(34, y + 104), "%.2f km   next +%d s" % [game.inf_dist / 1000.0, int(maxf(22.0, 35.0 - (game.inf_gates + 1)))], 20, G.CREAM, G.font_bold, 5)
			else:
				G.draw_text_l(self, Vector2(34, y + 62), "%.2f km" % (game.inf_dist / 1000.0), 40, Color.WHITE, G.font_digits, 8)
				G.draw_text_l(self, Vector2(34, y + 96), game.biome, 18, Color(0.85, 1.0, 0.8), G.font_bold, 5)
	# ---------- split time
	if game.split_show > 0.0 and game.mode in ["race", "tt"]:
		var k := clampf(game.split_show * 2.0, 0.0, 1.0)
		var d: float = game.split_diff
		var txt := "SPLIT  %s" % G.fmt_time(game.split_last)
		if absf(d) > 0.001:
			txt += "   %s%.2f" % ["+" if d > 0.0 else "-", absf(d)]
		var col := Color(0.4, 1.0, 0.5, k) if d <= 0.0 else Color(1.0, 0.45, 0.4, k)
		G.draw_text_c(self, Vector2(W * 0.5, 190), txt, 34, col, G.font_digits, 8, Color(0.02, 0.06, 0.1, k))
	# ---------- pace note
	if game.state == "run" and game.mode != "explore":
		_pace_note(Vector2(W * 0.5, 64))
	if game.wrong_t > 1.0:
		G.draw_text_c(self, Vector2(W * 0.5, H * 0.3), "WRONG WAY!", 64, Color(1.0, 0.3, 0.3), G.font_title, 12)
	# ---------- popups
	var py := H * 0.36
	for i in range(game.popups.size() - 1, -1, -1):
		var p: Dictionary = game.popups[i]
		var a := clampf(p.t / 0.4, 0.0, 1.0)
		var rise: float = (2.0 - p.t) * 18.0
		var col: Color = p.col
		col.a = a
		G.draw_text_c(self, Vector2(W * 0.5, py - rise), p.txt, p.size, col, G.font_title, 10, Color(0.02, 0.06, 0.1, a))
		py -= p.size + 14
	# ---------- banner
	if game.banner_t > 0.0 and game.banner != "":
		var k := clampf(game.banner_t * 3.0, 0.0, 1.0)
		var sz := int(110 + (1.0 - k) * 30)
		var bc: Color = game.banner_col
		bc.a = k
		G.draw_text_c(self, Vector2(W * 0.5, H * 0.46), game.banner, sz, bc, G.font_title, 16, Color(0.02, 0.06, 0.1, k))
	# ---------- zone name
	if game.zone_t > 0.0 and game.mode in ["explore", "race", "tt"]:
		var k := clampf(minf(game.zone_t, 2.6 - game.zone_t) * 3.0, 0.0, 1.0)
		G.draw_text_c(self, Vector2(W * 0.5, H - 205), game.zone, 30, Color(1, 0.97, 0.9, k), G.font_title, 8, Color(0.02, 0.06, 0.1, k))
	# ---------- speedometer (bottom centre)
	var sc := Vector2(W * 0.5, H - 72)
	var kmh := int(c.speed * 3.6)
	draw_circle(sc, 80, Color(0.02, 0.08, 0.13, 0.72))
	draw_arc(sc, 67, PI * 0.8, PI * 2.2, 40, Color(1, 1, 1, 0.16), 10, true)
	var frac := clampf(kmh / 220.0, 0.0, 1.0)
	var arc_col := Color(0.2, 0.85, 0.95).lerp(Color(1.0, 0.35, 0.25), frac)
	if c.nitro_on:
		arc_col = Color(0.5, 0.75, 1.0)
	if frac > 0.005:
		draw_arc(sc, 67, PI * 0.8, PI * 0.8 + PI * 1.4 * frac, 40, arc_col, 10, true)
	# rpm ticks
	var rpm: float = c.rpm
	draw_arc(sc, 52, PI * 0.8, PI * 0.8 + PI * 1.4 * rpm, 30, Color(1, 1, 1, 0.5) if rpm < 0.85 else Color(1.0, 0.4, 0.3, 0.9), 4, true)
	G.draw_text_c(self, sc + Vector2(0, -8), str(kmh), 44, Color.WHITE, G.font_digits, 6)
	G.draw_text_c(self, sc + Vector2(0, 26), "km/h", 17, G.CREAM, G.font_bold, 4)
	G.draw_text_c(self, sc + Vector2(0, 50), "R" if c.vf < -0.5 else str(c.gear), 20, G.GOLD, G.font_digits, 4)
	var nb := Rect2(sc.x - 90, H - 18 - 4, 180, 12)
	draw_rect(nb.grow(3), Color(0.02, 0.08, 0.13, 0.8))
	var ncol := Color(0.35, 0.7, 1.0) if c.nitro < 0.999 else Color(0.45, 0.85, 1.0).lerp(Color.WHITE, 0.5 + 0.5 * sin(t * 8.0))
	draw_rect(Rect2(nb.position, Vector2(nb.size.x * c.nitro, nb.size.y)), ncol)
	G.draw_text_r(self, Vector2(nb.position.x - 8, nb.position.y + 5), "NITRO", 14, Color(0.7, 0.9, 1.0), G.font_title, 4)
	# ---------- minimap (top right)
	_minimap(Vector2(W - 104, 112), 88.0)
	if not G.is_touch and game.t_run < 12.0 and game.state == "run":
		G.draw_text_c(self, Vector2(W * 0.5, H - 172), "ARROWS drive   SPACE drift   SHIFT nitro   C camera   R reset   L lights", 18, Color(1, 1, 1, 0.85), G.font_bold, 6)


func _pace_note(at: Vector2) -> void:
	var w = game.world
	var c = game.player
	var i0: int = game.p_idx
	var spd: float = maxf(c.speed, 12.0)
	# look 30..110 m ahead for the sharpest bend or a jump
	var best := 0.0
	var best_k := 0
	var d0: Vector2 = w.road_dir(i0 + 10)
	for k in range(15, 60, 3):
		var a: Vector2 = w.road_dir(i0 + k)
		var b: Vector2 = w.road_dir(i0 + k + 12)
		var turn := a.angle_to(b)
		if absf(turn) > absf(best):
			best = turn
			best_k = k
	var jump := false
	if w.has_method("jump_ahead"):
		jump = w.jump_ahead(i0, 70)
	if absf(best) < 0.32 and not jump:
		return
	var sev := absf(best)
	var txt := ""
	var col := Color(1, 1, 1)
	if jump and absf(best) < 0.5:
		txt = "JUMP!"
		col = G.GOLD
	else:
		var left := best < 0.0
		if sev > 1.0:
			txt = "HAIRPIN"
			col = Color(1.0, 0.35, 0.3)
		elif sev > 0.62:
			txt = "SHARP"
			col = Color(1.0, 0.65, 0.3)
		else:
			txt = "EASY"
			col = Color(0.6, 1.0, 0.6)
		txt += " LEFT" if left else " RIGHT"
		# arrow icon
		var ax := at + Vector2(0, 40)
		var dirx := -1.0 if left else 1.0
		var curve := PackedVector2Array()
		for s in 9:
			var u := s / 8.0
			curve.append(ax + Vector2(dirx * 30.0 * pow(u, 1.6) * (0.6 + sev * 0.4), 20.0 - 44.0 * u))
		draw_polyline(curve, Color(0.02, 0.06, 0.1, 0.8), 14.0, true)
		draw_polyline(curve, col, 8.0, true)
		var tip: Vector2 = curve[8]
		var dv: Vector2 = (curve[8] - curve[7]).normalized()
		var nv := Vector2(-dv.y, dv.x)
		draw_colored_polygon(PackedVector2Array([tip + dv * 14, tip + nv * 11, tip - nv * 11]), col)
	G.draw_text_c(self, at, txt, 30, col, G.font_title, 8)


func _arrow_to(target: Vector3, at: Vector2, col: Color) -> void:
	var c = game.player
	var to: Vector3 = target - c.pos
	var ang := atan2(to.x, to.z) - atan2(c.fwd_flat().x, c.fwd_flat().z)
	var dist := Vector2(to.x, to.z).length()
	var d := Vector2(sin(ang), -cos(ang))
	var nrm := Vector2(-d.y, d.x)
	var pts := PackedVector2Array([at + d * 30, at - d * 18 + nrm * 20, at - d * 8, at - d * 18 - nrm * 20])
	draw_colored_polygon(pts, col)
	var loop := pts.duplicate()
	loop.append(pts[0])
	draw_polyline(loop, Color(0.02, 0.06, 0.1), 3.0, true)
	G.draw_text_c(self, at + Vector2(0, 46), "%d m" % int(dist), 20, Color.WHITE, G.font_digits, 5)


func _build_island_map(w) -> void:
	map_pts = PackedVector2Array()
	var mn := Vector2(1e9, 1e9)
	var mx := Vector2(-1e9, -1e9)
	for i in range(0, w.RN, 6):
		var p := Vector2(w.rx[i], w.rz[i])
		map_pts.append(p)
		mn = mn.min(p)
		mx = mx.max(p)
	map_center = (mn + mx) * 0.5
	map_scale = 1.0 / maxf(mx.x - mn.x, mx.y - mn.y)


func _minimap(center: Vector2, r: float) -> void:
	draw_circle(center, r + 6, Color(0.02, 0.08, 0.13, 0.7))
	var w = game.world
	var c = game.player
	if game.mode == "inf":
		# local map, heading up
		var fw: Vector3 = c.fwd_flat()
		var ang := atan2(fw.x, -fw.z)
		var pts := PackedVector2Array()
		var sc := r / 260.0
		for k in range(-80, 200, 3):
			var p: Vector3 = w.road_point(game.p_idx + k)
			var rel := Vector2(p.x - c.pos.x, p.z - c.pos.z).rotated(-ang) * sc
			if rel.length() < r:
				pts.append(center + rel)
		if pts.size() > 1:
			draw_polyline(pts, Color(0.02, 0.06, 0.1), 9.0, true)
			draw_polyline(pts, Color(0.95, 0.92, 0.85), 5.0, true)
		_dot(center, Color(1.0, 0.4, 0.3), 7.0)
		return
	if map_pts.is_empty():
		_build_island_map(w)
	var k := r * 1.75 * map_scale
	var pts2 := PackedVector2Array()
	for p in map_pts:
		pts2.append(center + (p - map_center) * k)
	pts2.append(pts2[0])
	draw_polyline(pts2, Color(0.02, 0.06, 0.1), 8.0, true)
	draw_polyline(pts2, Color(0.95, 0.92, 0.85), 4.0, true)
	var sl := center + (Vector2(w.rx[0], w.rz[0]) - map_center) * k
	draw_rect(Rect2(sl - Vector2(5, 5), Vector2(10, 10)), Color(1, 1, 1))
	if game.mode == "explore":
		for i in w.stars_nodes.size():
			if not game.found.has(i):
				var sp: Vector3 = w.stars_nodes[i].position
				var q := center + (Vector2(sp.x, sp.z) - map_center) * k
				draw_colored_polygon(G.star_pts(q, 6.0), G.GOLD)
	for a in game.ais:
		_dot(center + (Vector2(a.car.pos.x, a.car.pos.z) - map_center) * k, a.car.paint, 5.0)
	_dot(center + (Vector2(c.pos.x, c.pos.z) - map_center) * k, Color(1.0, 0.35, 0.3), 7.0)


func _dot(p: Vector2, col: Color, r: float) -> void:
	draw_circle(p, r + 2.0, Color(0.02, 0.06, 0.1))
	draw_circle(p, r, col)

