	hts = FileAccess.get_file_as_bytes("res://world/heights.bin.gz").decompress(N * N * 4, FileAccess.COMPRESSION_GZIP).to_float32_array()
	msk = FileAccess.get_file_as_bytes("res://world/mask.bin.gz").decompress(N * N * 4, FileAccess.COMPRESSION_GZIP)
	rdg = FileAccess.get_file_as_bytes("res://world/roadg.bin.gz").decompress(N * N, FileAccess.COMPRESSION_GZIP)
	var road: Array = lay.road
	RN = road.size()
	for arr in [rx, rz, rh, rtx, rtz, rdist]:
		arr.resize(RN)
	rsf.resize(RN)
	for i in RN:
		var p: Array = road[i]
		rx[i] = p[0]
		rz[i] = p[1]
		rh[i] = p[2]
		rsf[i] = int(p[3])
	var acc := 0.0
	for i in RN:
		var a := (i - 1 + RN) % RN
		var b := (i + 1) % RN
		var d := Vector2(rx[b] - rx[a], rz[b] - rz[a]).normalized()
		rtx[i] = d.x
		rtz[i] = d.y
		rdist[i] = acc
		acc += Vector2(rx[b] - rx[i], rz[b] - rz[i]).length() if b != 0 else Vector2(rx[0] - rx[i], rz[0] - rz[i]).length()
		var key := Vector2i(int(floor(rx[i] / RCELL)), int(floor(rz[i] / RCELL)))
		if not road_hash.has(key):
			road_hash[key] = PackedInt32Array()
		road_hash[key].append(i)
	road_len = acc


func build(textures: Dictionary, quality: int) -> void:
	tex = textures
	gfx = quality
	load_data()
	terrain = Terrain.new()
	terrain.name = "terrain"
	add_child(terrain)
	var dom := Rect2(O, O, -2.0 * O, -2.0 * O)
	terrain.setup(self, [
		{"size": 128.0, "n": 64, "radius": 200.0, "skirt": 2.5, "bounds": dom, "mask_res": 32},
		{"size": 512.0, "n": 64, "radius": 4000.0, "skirt": 14.0, "drop": 0.7, "permanent": true, "bounds": dom},
	], tex, sea)
	terrain.configure(gfx)
	veg = Veg.new()
	veg.name = "veg"
	add_child(veg)
	veg.setup(tex.leaves, tex.bark)
	veg.cell_size = 2048.0
	_species()
	veg.configure(gfx)
	_ocean()
	_road()
	_trees()
	_props()


func _species() -> void:
	veg.add_species("palm", Flora.palm(true), Flora.palm(false), 1.2, true, true)
	veg.add_species("jungle", Flora.jungle(true, 0), Flora.jungle(false, 0), 0.6, true, true)
	veg.add_species("jungle2", Flora.jungle(true, 2), Flora.jungle(false, 2), 0.5, true, true)
	veg.add_species("banana", Flora.banana(true), Flora.banana(false), 1.0, true)
	veg.add_species("bush", Flora.bush(true), Flora.bush(false), 0.5, false)
	veg.add_species("flower", Flora.bush(true, true), Flora.bush(false, true), 0.5, false)
	veg.add_species("rock", Flora.rock(true, 0), Flora.rock(false, 0), 0.0, true, false)
	veg.add_species("fern", Flora.fern(true), Flora.fern(false), 0.8, false)


# ------------------------------------------------------------------ terrain source
func chunk_wanted(_li: int, _cx: int, _cz: int) -> bool:
	return true


class Job:
	var w
	var li := 0
	var x0 := 0.0
	var z0 := 0.0
	var step := 2.0
	var n := 32
	var h := PackedFloat32Array()
	var col := PackedColorArray()
	var uv := PackedVector2Array()
	var uv2 := PackedVector2Array()
	var min_h := 1e9

	func run(_budget: int) -> bool:
		w.fill_job(self)
		return true


func begin_chunk(li: int, x0: float, z0: float, step: float, n: int):
	var j := Job.new()
	j.w = self
	j.li = li
	j.x0 = x0
	j.z0 = z0
	j.step = step
	j.n = n
	return j


func fill_job(j) -> void:
	var n: int = j.n
	var b := n + 3
	var w := n + 1
	var stride := int(round(j.step / S))
	var gi0 := int(round((j.x0 - O) / S))
	var gj0 := int(round((j.z0 - O) / S))
	var h := PackedFloat32Array()
	h.resize(b * b)
	var mn := 1e9
	for jj in b:
		var gj := clampi(gj0 + (jj - 1) * stride, 0, N - 1) * N
		for ii in b:
			var gi := clampi(gi0 + (ii - 1) * stride, 0, N - 1)
			var v := hts[gj + gi]
			h[jj * b + ii] = v
			if v < mn:
				mn = v
	var col := PackedColorArray()
	var uv := PackedVector2Array()
	var uv2 := PackedVector2Array()
	col.resize(w * w)
	uv.resize(w * w)
	uv2.resize(w * w)
	var k := 0
	for jj in w:
		var gj := clampi(gj0 + jj * stride, 0, N - 1) * N
		for ii in w:
			var gi := clampi(gi0 + ii * stride, 0, N - 1)
			var m := (gj + gi) * 4
			var sand := msk[m] / 255.0
			var rock := msk[m + 1] / 255.0
			var dirt := msk[m + 2] / 255.0
			var grass := msk[m + 3] / 255.0
			var hh := hts[gj + gi]
			var c := base_col.lerp(dry_col, clampf((hh - 25.0) / 90.0, 0.0, 0.6))
			col[k] = Color(c.r, c.g, c.b, grass)
			uv[k] = Vector2(rock, sand)
			uv2[k] = Vector2(0.0, dirt)
			k += 1
	j.h = h
	j.col = col
	j.uv = uv
	j.uv2 = uv2
	j.min_h = mn


# ------------------------------------------------------------------ physics queries
func height(x: float, z: float) -> float:
	var fx := (x - O) / S
	var fz := (z - O) / S
	if fx < 0.0 or fz < 0.0 or fx >= N - 1.001 or fz >= N - 1.001:
		return -30.0
	var i := int(fx)
	var j := int(fz)
	var a := fx - i
	var b := fz - j
	var k := j * N + i
	var h := (hts[k] * (1.0 - a) + hts[k + 1] * a) * (1.0 - b) + (hts[k + N] * (1.0 - a) + hts[k + N + 1] * a) * b
	var r0 := 1.0 if rdg[k] > 0 else 0.0
	var r1 := 1.0 if rdg[k + 1] > 0 else 0.0
	var r2 := 1.0 if rdg[k + N] > 0 else 0.0
	var r3 := 1.0 if rdg[k + N + 1] > 0 else 0.0
	var rf := (r0 * (1.0 - a) + r1 * a) * (1.0 - b) + (r2 * (1.0 - a) + r3 * a) * b
	return h + 0.14 * rf


func ground(x: float, z: float, _y := 1e9) -> float:
	return height(x, z)


func normal_at(x: float, z: float, _y := 1e9) -> Vector3:
	var e := 0.8
	var hl := height(x - e, z)
	var hr := height(x + e, z)
	var hd := height(x, z - e)
	var hu := height(x, z + e)
	return Vector3(hl - hr, 2.0 * e, hd - hu).normalized()


func surface_at(x: float, z: float, y: float) -> int:
	var i := clampi(int(round((x - O) / S)), 0, N - 1)
	var j := clampi(int(round((z - O) / S)), 0, N - 1)
	var k := j * N + i
	var r := rdg[k]
	if r > 0:
		return [SURF_TARMAC, SURF_GRAVEL, SURF_DIRT, SURF_SAND][r - 1] if r <= 4 else SURF_TARMAC
	if y < sea - 0.2:
		return SURF_WATER
	if msk[k * 4] > 128:
		return SURF_SAND
	if msk[k * 4 + 1] > 150:
		return SURF_ROCK
	return SURF_GRASS


func water_depth(x: float, z: float) -> float:
	return sea - height(x, z)


func zone_at(x: float, z: float) -> String:
	var lh: Array = lay.lighthouse
	if Vector2(x - lh[0], z - lh[1]).length() < 140.0:
		return "LIGHTHOUSE CAPE"
	var v: Array = lay.volcano
	var dv := Vector2(x - v[0], z - v[1]).length()
	if dv < 230.0:
		return "VOLCANO"
	var r := Vector2(x, z).length()
	if z > 380.0 and absf(x) < 260.0:
		return "CORAL VILLAGE"
	if x > 380.0 and z > 260.0:
		return "TURTLE BAY"
	if z < -300.0:
		return "NORTH RIDGE"
	if x < -300.0:
		return "WEST BEACH"
	if r > 560.0:
		return "COAST ROAD"
	return "JUNGLE"


# ------------------------------------------------------------------ road queries
func road_count() -> int:
	return RN


func road_point(i: float) -> Vector3:
	var i0 := int(floor(i))
	var t := i - i0
	i0 = ((i0 % RN) + RN) % RN
	var i1 := (i0 + 1) % RN
	return Vector3(lerpf(rx[i0], rx[i1], t), lerpf(rh[i0], rh[i1], t), lerpf(rz[i0], rz[i1], t))


func road_dir(i: int) -> Vector2:
	i = ((i % RN) + RN) % RN
	return Vector2(rtx[i], rtz[i])


func jump_ahead(i0: int, n: int) -> bool:
	for j in lay.jumps:
		var d := (int(j.i) - i0 + RN) % RN
		if d > 5 and d < n:
			return true
	return false


func road_yaw(i: int) -> float:
	var d := road_dir(i)
	return atan2(-d.x, -d.y)


## Nearest road sample to (x, z): Vector2(index, distance). hint >= 0 searches around the hint first.
func road_near(x: float, z: float, hint := -1) -> Vector2:
	var best := -1
	var bd := 1e18
	if hint >= 0:
		for k in range(-30, 45):
			var i := (hint + k + RN) % RN
			var dx := rx[i] - x
			var dz := rz[i] - z
			var d := dx * dx + dz * dz
			if d < bd:
				bd = d
				best = i
		if bd < 900.0:
			return Vector2(best, sqrt(bd))
	var cx := int(floor(x / RCELL))
	var cz := int(floor(z / RCELL))
	for ring in 6:
		for gz in range(cz - ring, cz + ring + 1):
			for gx in range(cx - ring, cx + ring + 1):
				if maxi(absi(gx - cx), absi(gz - cz)) != ring:
					continue
				var key := Vector2i(gx, gz)
				if not road_hash.has(key):
					continue
				for i in road_hash[key]:
					var dx := rx[i] - x
					var dz := rz[i] - z
					var d := dx * dx + dz * dz
					if d < bd:
						bd = d
						best = i
		if best >= 0 and sqrt(bd) < ring * RCELL:
			break
	if best < 0:
		# far from everything: brute force
		for i in range(0, RN, 4):
			var dx := rx[i] - x
			var dz := rz[i] - z
			var d := dx * dx + dz * dz
			if d < bd:
				bd = d
				best = i
	return Vector2(best, sqrt(bd))


# ------------------------------------------------------------------ collisions
func add_circle(x: float, z: float, r: float, top: float) -> void:
	var id := col_x.size()
	col_x.append(x)
	col_z.append(z)
	col_r.append(r)
	col_top.append(top)
	var c0 := int(floor((x - r) / CCELL))
	var c1 := int(floor((x + r) / CCELL))
	var r0 := int(floor((z - r) / CCELL))
	var r1 := int(floor((z + r) / CCELL))
	for gz in range(r0, r1 + 1):
		for gx in range(c0, c1 + 1):
			var key := Vector2i(gx, gz)
			if not col_grid.has(key):
				col_grid[key] = PackedInt32Array()
			col_grid[key].append(id)


## Pushes the car out of static circles. Returns [impact speed].
func collide(car, p: Vector3, r: float) -> Array:
	var key := Vector2i(int(floor(p.x / CCELL)), int(floor(p.z / CCELL)))
	if not col_grid.has(key):
		return [0.0]
	var hit := 0.0
	for id in col_grid[key]:
		var dx := p.x - col_x[id]
		var dz := p.z - col_z[id]
		var rr := r + col_r[id]
		var d2 := dx * dx + dz * dz
		if d2 >= rr * rr or d2 < 1e-6 or car.pos.y > col_top[id]:
			continue
		var d := sqrt(d2)
		var nx := dx / d
		var nz := dz / d
		var pen := rr - d
		car.pos.x += nx * pen
		car.pos.z += nz * pen
		var vn: float = car.vel.x * nx + car.vel.z * nz
		if vn < 0.0:
			car.vel.x -= nx * vn * 1.35
			car.vel.z -= nz * vn * 1.35
			car.vel *= 0.82
			hit = maxf(hit, -vn)
	return [hit]


# ------------------------------------------------------------------ ocean around the island
func _ocean() -> void:
	ocean_mat = terrain.levels[1].wmat.duplicate()
	ocean_mat.set_shader_parameter("hole_win", Vector4(0, 0, 1, 0))
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var inner := -O
	var radii := [inner, inner + 200.0, 2400.0, 4000.0, 9000.0, 20000.0]
	var na := 64
	# square inner edge morphing to circles outside
	for ri in radii.size():
		for ai in na:
			var a := TAU * ai / na
			var dir := Vector2(cos(a), sin(a))
			var sq := dir / maxf(absf(dir.x), absf(dir.y))
			var r: float = radii[ri]
			var p: Vector2 = (sq * inner).lerp(dir * r, 0.0 if ri == 0 else 1.0)
			if ri == 1:
				p = sq * r
			st.set_uv(Vector2(30.0, 0.0))
			st.set_normal(Vector3.UP)
			st.add_vertex(Vector3(p.x, sea, p.y))
	for ri in radii.size() - 1:
		for ai in na:
			var a := ri * na + ai
			var b := ri * na + (ai + 1) % na
			var c := (ri + 1) * na + ai
			var d := (ri + 1) * na + (ai + 1) % na
			st.add_index(a)
			st.add_index(c)
			st.add_index(b)
			st.add_index(b)
			st.add_index(c)
			st.add_index(d)
	ocean = MeshInstance3D.new()
	ocean.mesh = st.commit()
	ocean.material_override = ocean_mat
	ocean.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(ocean)
	# far islands on the horizon
	var far := Props.far_islands()
	add_child(far)


# ------------------------------------------------------------------ road
func _road() -> void:
	road_mat = RoadMesh.material(tex, hw)
	var sec := 60
	var i := 0
	while i < RN:
		var i1 := mini(i + sec, RN)
		var m := RoadMesh.build(rx, rz, rh, rtx, rtz, rsf, rdist, i, i1, hw, RN)
		var mi := MeshInstance3D.new()
		mi.mesh = m
		mi.material_override = road_mat
		mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		mi.visibility_range_end = 1500.0
		add_child(mi)
		i = i1


# ------------------------------------------------------------------ vegetation
func _trees() -> void:
	var names := ["palm", "jungle", "banana", "bush", "rock", "fern"]
	var cells := {}
	var rng := RandomNumberGenerator.new()
	rng.seed = 5
	for t in lay.trees:
		var x: float = t[0]
		var z: float = t[1]
		var kind := int(t[2])
		var s: float = t[3]
		var rot: float = t[4]
		var sp: String = names[kind]
		if sp == "jungle" and rng.randf() < 0.4:
			sp = "jungle2"
		if sp == "bush" and rng.randf() < 0.3:
			sp = "flower"
		var key := Vector2i(0, 0)  # one far cell per species for the whole island: few draw calls
		if not cells.has(key):
			cells[key] = {}
		if not cells[key].has(sp):
			cells[key][sp] = PackedFloat32Array()
		var y := height(x, z)
		var tint := Color(1, 1, 1)
		match sp:
			"palm":
				tint = Color(1, 1, 1).lerp(Color(1.1, 1.05, 0.8), rng.randf())
				add_circle(x, z, 0.35 * s, y + 9.0 * s)
			"jungle", "jungle2":
				tint = Color(1, 1, 1).lerp(Color(0.85, 1.05, 0.8), rng.randf())
				add_circle(x, z, 0.5 * s, y + 10.0 * s)
			"rock":
				var g := rng.randf_range(0.85, 1.1)
				tint = Color(g, g * 0.98, g * 0.95)
				y -= 0.25 * s
				add_circle(x, z, 1.05 * s, y + 0.9 * s)
			"banana":
				tint = Color(1, 1, 1).lerp(Color(1.1, 1.1, 0.85), rng.randf())
			_:
				tint = Color(1, 1, 1).lerp(Color(0.85, 1.0, 0.75), rng.randf())
		var buf: PackedFloat32Array = cells[key][sp]
		Veg.pack(buf, Vector3(x, y - 0.05, z), rot, s, tint, rng.randf(), rng.randf_range(-0.05, 0.05) if sp != "rock" else 0.0)
		cells[key][sp] = buf
	for key in cells:
		veg.add_cell(key, cells[key])


# ------------------------------------------------------------------ props
func _props() -> void:
	Props.build_island(self)


func set_stars_visible(found: Array, on: bool) -> void:
	for i in stars_nodes.size():
		stars_nodes[i].visible = on and not found.has(i)


func update(dt: float, cam: Vector3, budget := -1) -> void:
	terrain.update(cam, budget)
	veg.update(cam)
	ocean.position = Vector3(0, 0, 0)
	for st in stars_nodes:
		if st.visible:
			st.rotation.y += dt * 1.8
	if lighthouse_beam != null and lighthouse_beam.visible:
		lighthouse_beam.rotation.y += dt * 0.9
	Props.update_smoke(self, dt)


func apply_gfx(level: int) -> void:
	gfx = level
	terrain.configure(level)
	veg.configure(level)


func set_weather(wet: float, night: float, rain: float) -> void:
	terrain.set_param("wet", wet)
	terrain.set_water_param("rain", rain)
	terrain.set_water_param("night", night)
	ocean_mat.set_shader_parameter("rain", rain)
	ocean_mat.set_shader_parameter("night", night)
	road_mat.set_shader_parameter("wet", wet)
	veg.set_param("wet", wet)
	terrain.grass_mat.set_shader_parameter("wet", wet)
	if lighthouse_beam != null:
		lighthouse_beam.visible = night > 0.5
	for l in lamp_lights:
		l.visible = night > 0.5


func set_cloud(off: Vector2, amount: float) -> void:
	terrain.set_param("cloud_shadow", amount)
	road_mat.set_shader_parameter("cloud_off", terrain.cloud_off)
	road_mat.set_shader_parameter("cloud_shadow", amount)

