		var t6 := Time.get_ticks_usec()
		print("biome_w %.2f us, +raw_h %.2f us, road_query %.2f us, h_carved %.2f us, L0 job %.1f ms" % [(t1 - ts) / float(N), (t2 - t1) / float(N), (t3 - t2) / float(N), (t4 - t3) / float(N), (t6 - t5) / 1000.0])
		get_tree().quit()
		return
	if "--biomes" in args:
