		print("psf hist ", hist, " ROAD_SURF ", E.ROAD_SURF)
		var line := ""
		for km in 60:
			var i: int = mini(E.final - 1, E.START_I + km * 500)
			E.biome_w(E.px[i], E.pz[i])
			line += "%d:%s(%.0fm,s%d) " % [km, ["T", "P", "C", "A"][E.dominant()], E.ph[i], E.psf[i]]
		print(line)
		get_tree().quit()
		return
	if "--infstart" in args:
