	await get_tree().process_frame
	var t0 := Time.get_ticks_msec()
	for n in ["noise", "ground_n", "rock_n", "rock_a", "sand_n", "gravel_n", "asphalt", "water_n", "clouds", "leaves", "bark", "bark_n", "puff", "spark"]:
		textures[n] = G.tex(n)
