	hud_layer.add_child(hud)
	touch = Touch.new()
	touch.game = game
	touch.main = self
	hud_layer.add_child(touch)
	print("island built in %d ms" % (Time.get_ticks_msec() - t0))
	apply_settings()
	# prebuild the terrain around the menu spot so the first frame looks right
	var s: Array = island.lay.show
	island.terrain.flush(Vector3(s[0], 0, s[1]), 8000)
	print("ready in %d ms (%d chunks)" % [Time.get_ticks_msec() - t0, island.terrain.built_count])
	for a in args:
		if a.begins_with("--shot="):
			shot_path = a.substr(7)
		if a.begins_with("--frames="):
			shot_frames = int(a.substr(9))
	if "--selftest" in args:
		var st = load("res://scripts/selftest.gd").new()
		st.main = self
		add_child(st)
		return
	var start := ""
	if OS.has_feature("web"):
		var h = JavaScriptBridge.eval("location.hash", true)
		if h is String and h.length() > 1:
			start = h.substr(1)
	for a in args:
		if a.begins_with("--start="):
			start = a.substr(8)
	var opts := start.split(",")
	start = opts[0]
	for o in opts.slice(1):
		match o:
			"fast":
				G.data.gfx = 0
			"high":
				G.data.gfx = 1
			"max":
				G.data.gfx = 2
			"golden":
				G.data.tod = 1
			"night":
				G.data.tod = 2
			"rain":
				G.data.weather = 1
			"noon":
				G.data.tod = 0
	if opts.size() > 1:
		apply_settings()
	if start == "explore" or start == "free":
		go_mode("explore")
	elif start == "race" or start == "tt":
		go_mode(start)
	elif start == "inf" or start == "inf-ta":
		go_mode("inf_ta" if start == "inf-ta" else "inf_free")
	elif start.begins_with("inf-at-"):
		## debug: jump to kilometre N of the endless road
		await go_mode("inf_free")
		var E = game.endless
		var km := float(start.substr(7))
		var i: int = E.START_I + int(km * 500.0)
		E.ensure_road(E.pz[mini(E.final - 1, i)] + 5000.0, 1000000)
		E.ensure_road(km * 1000.0 + 5000.0, 1000000)
		game.player.place(E.road_point(i), E.road_yaw(i))
		game.p_idx = i
		E.terrain.flush(game.player.pos, 60000)
		E.update_props(game.player.pos, true)
		game.cam_snap = true
	elif start == "garage":
		go_garage()
	elif start.begins_with("show"):
		## close-up: #show-<angle deg>-<height>-<radius>[-<steer>[-<car id>]]
		var bits := start.split("-")
		go_garage()
		ui.hide_all()
		game.mode = "showcase"
		if bits.size() >= 4:
			game.showcase = Vector3(deg_to_rad(float(bits[1])), float(bits[2]), float(bits[3]))
		if bits.size() >= 6:
			game.player.set_car(bits[5], G.paint_of(bits[5]))
		if bits.size() >= 5:
			game.player.steer_s = float(bits[4].replace("n", "-"))
		game.player.update_visual(0.0)
	elif start.begins_with("look"):
		## free camera: #look-<x>-<z>-<height>-<target x>-<target z>-<target height>, "n" for minus
		var v := []
		for b in start.split("-").slice(1):
			v.append(float(b.replace("n", "-")))
		go_title()
		ui.hide_all()
		game.mode = "look"
		game.look_from = Vector3(v[0], island.height(v[0], v[1]) + v[2], v[1])
		game.look_at = Vector3(v[3], island.height(v[3], v[4]) + v[5], v[4])
		island.terrain.flush(game.look_from, 8000)
