			for far in 2:
				var p := base + Vector3(-12.0 + i * 4.0, 0, -10.0 - far * 160.0)
				p.y = island.height(p.x, p.z)
				Veg.pack(buf, p, 0.3, 1.0 if far == 0 else 6.0, Color(1, 1, 1), 0.5)
			items[sp] = buf
			i += 1
		island.veg.add_cell("test", items)
		game.mode = "look"
		game.look_from = base + Vector3(0, island.height(base.x, base.z) + 3.0, 6.0)
		game.look_at = base + Vector3(0, island.height(base.x, base.z) + 2.0, -10.0)
		if start == "vegtest-far":
			game.look_at = base + Vector3(0, island.height(base.x, base.z) + 10.0, -170.0)
	elif start == "ui-results":
