			var yaw: float = game.player.yaw
			var bs := Basis(Vector3.UP, yaw)
			game.mode = "look"
			ui.hide_all()
			game.look_from = pp + bs * Vector3(v[0], v[1], v[2])
			game.look_at = pp + bs * Vector3(v[3], v[4], v[5])


func _process(dt: float) -> void:
	if shot_path != "":
		shot_wait += 1
		if shot_wait == maxi(shot_frames, 3):
			var img := get_viewport().get_texture().get_image()
			img.save_png(shot_path)
			var cats := {}
			var frustum := cam.get_frustum()
			for n in get_tree().root.find_children("*", "GeometryInstance3D", true, false):
				if not n.is_visible_in_tree():
					continue
				var aabb: AABB = n.get_aabb()
				aabb = n.global_transform * aabb
				var inside := true
				for pl in frustum:
					var c := aabb.get_center()
					var e := aabb.size * 0.5
					var r := absf(pl.normal.x) * e.x + absf(pl.normal.y) * e.y + absf(pl.normal.z) * e.z
					if pl.distance_to(c) > r:
						inside = false
						break
				if not inside:
					continue
				var key: String = n.get_parent().name if n.get_parent() != null else "?"
				if n.get_parent() is Node3D and n.get_parent().get_parent() != null and String(n.get_parent().name).begins_with("@"):
					key = String(n.get_parent().get_parent().name)
				key += ":" + n.get_class()
				var surf := 1
				if n is MeshInstance3D and n.mesh != null:
					surf = n.mesh.get_surface_count()
				elif n is MultiMeshInstance3D and n.multimesh != null and n.multimesh.mesh != null:
					surf = n.multimesh.mesh.get_surface_count()
				cats[key] = cats.get(key, 0) + surf
			var keys := cats.keys()
			keys.sort_custom(func(a, b): return cats[a] > cats[b])
			for k in keys.slice(0, 14):
				print("   ", k, " ", cats[k])
			print("SHOT ", shot_path, " draws=", Performance.get_monitor(Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME),
				" objects=", Performance.get_monitor(Performance.RENDER_TOTAL_OBJECTS_IN_FRAME),
				" prims=", Performance.get_monitor(Performance.RENDER_TOTAL_PRIMITIVES_IN_FRAME),
				" nodes=", Performance.get_monitor(Performance.OBJECT_NODE_COUNT))
			get_tree().quit()
	_auto_quality(dt)


func apply_settings() -> void:
	var gfx := int(G.data.gfx)
	sky.configure(gfx)
	sky.set_time(int(G.data.tod), int(G.data.weather) == 1)
	island.apply_gfx(gfx)
	island.set_weather(sky.wet, sky.night, sky.wet)
	if game != null and game.endless != null:
		game.endless.apply_gfx(gfx)
		game.endless.set_weather(sky.wet, sky.night, sky.wet)
	fx.light = Color(1, 1, 1) if sky.night < 0.5 else Color(0.35, 0.4, 0.5)
	var vp := get_viewport()
	vp.msaa_3d = [Viewport.MSAA_DISABLED, Viewport.MSAA_2X, Viewport.MSAA_4X][gfx]
	res_scale = [0.8, 1.0, 1.0][gfx]
	vp.scaling_3d_scale = res_scale
	if game != null and game.player != null and game.player.car_id != "":
		var want_hq := gfx > 0
		if want_hq != game.player.model.has("rig"):
			game.refresh_player_car()
			for a in game.ais:
				a.car.set_car(a.car.car_id, a.car.paint)
		game.player.set_lights(sky.tod == 2)
		game.player.wet = sky.wet


func _auto_quality(dt: float) -> void:
	## lower the 3D resolution (then the graphics level) if the game runs slowly
	if game == null or game.headless or game.paused or not game.driving():
		return
	var fps := Engine.get_frames_per_second()
	if fps < 40.0:
		fps_low_t += dt
		fps_high_t = 0.0
	elif fps > 57.0:
		fps_high_t += dt
		fps_low_t = 0.0
	else:
		fps_low_t = 0.0
		fps_high_t = 0.0
	var gfx := int(G.data.gfx)
	var floor_s := 0.6 if gfx > 0 else 0.5
	if fps_low_t > 2.5:
		fps_low_t = 0.0
		if res_scale > floor_s + 0.01:
			res_scale = maxf(floor_s, res_scale - 0.1)
			get_viewport().scaling_3d_scale = res_scale
		elif gfx > 0:
			G.data.gfx = gfx - 1
			G.save_game()
			apply_settings()
			res_scale = 0.8
			get_viewport().scaling_3d_scale = res_scale
			if not auto_note:
				auto_note = true
				game.add_popup("Graphics set to %s for smooth driving" % G.GFX_NAMES[gfx - 1], Color(0.8, 0.9, 1.0), 26)
	elif fps_high_t > 6.0:
		fps_high_t = 0.0
		var top := 1.0 if gfx > 0 else 0.8
		if res_scale < top - 0.01:
			res_scale = minf(top, res_scale + 0.1)
			get_viewport().scaling_3d_scale = res_scale


func go_title() -> void:
	game.paused = false
	pause_audio(false)
	game.refresh_player_car()
	game.enter_title()
	ui.show_title()


func go_garage() -> void:
	game.refresh_player_car()
	game.enter_garage()
	ui.show_garage()


func go_mode(m: String) -> void:
	game.paused = false
	pause_audio(false)
	game.refresh_player_car()
	ui.hide_all()
	match m:
		"race", "tt", "explore":
			if m == "race" and not game.headless:
				ui.show_loading("Getting the rally cars ready...")
				await get_tree().process_frame
				await get_tree().process_frame
			game.start_island(m)
			if not game.headless:
				island.terrain.flush(game.player.pos, 3000)
			ui.hide_all()
		"inf_free":
			ui.show_loading("Building an endless road...")
			await get_tree().process_frame
			await get_tree().process_frame
			game.start_inf("free")
			ui.hide_all()
		"inf_ta":
			ui.show_loading("Building an endless road...")
			await get_tree().process_frame
			await get_tree().process_frame
			game.start_inf("ta")
			ui.hide_all()


func preview_car(id: String) -> void:
	game.player.set_car(id, G.paint_of(id))
	game.player.set_lights(sky.tod == 2)
	game.player.update_visual(0.0)


func on_done(res: Dictionary) -> void:
	await get_tree().create_timer(2.2).timeout
	if game.state == "done":
		ui.show_results(res)


func toggle_pause() -> void:
	if not game.driving():
		return
	game.paused = not game.paused
	pause_audio(game.paused)
	if game.paused:
		Engine.time_scale = 1.0
		ui.show_pause()
	else:
		ui.hide_all()


func pause_audio(on: bool) -> void:
	for c in [game.player] + game.ais.map(func(a): return a.car):
		for p in [c.eng, c.skid_p, c.sand_p, c.wind_p, c.nos_p]:
			if p != null:
				p.stream_paused = on


func _notification(what: int) -> void:
	if what == NOTIFICATION_APPLICATION_FOCUS_OUT or what == NOTIFICATION_WM_WINDOW_FOCUS_OUT:
		if game != null and game.driving() and not game.paused and not game.headless and game.state != "done":
			toggle_pause()
		if G != null and G.data.size() > 0:
			G.save_game()

