# ================================================================== Bedouin tent (bait al-sha'ar)
static func tent(size: float) -> ArrayMesh:
	var L := 9.0 * size
	var W := 5.5 * size
	var H := 2.6 * size
	var parts := []
	var cloth_dark := Color(0.13, 0.1, 0.085)
	var cloth_light := Color(0.24, 0.19, 0.15)
	# roof: woven strips along the length, sagging between the poles
	var roof_y := func(x: float, z: float) -> float:
		var u := absf(z) / (W * 0.5)
		var ridge := H - 0.85 * size * pow(u, 1.3)
		if z > 0.0:
			ridge = H - 0.55 * size * pow(u, 1.2)
		var bay := fposmod(x / (L * 0.25) + 0.5, 1.0)
		return ridge - 0.22 * size * sin(PI * bay) * (0.4 + 0.6 * u)
	var nx := 36
	var nz := 14
	var v := PackedVector3Array()
	var n := PackedVector3Array()
	var cols := PackedColorArray()
	var idx := PackedInt32Array()
	for i in nx + 1:
		for j in nz + 1:
			var x := lerpf(-L * 0.5, L * 0.5, float(i) / nx)
			var z := lerpf(-W * 0.5, W * 0.5, float(j) / nz)
			v.append(Vector3(x, roof_y.call(x, z), z))
			var stripe := int(floor(z / (W / 7.0) + 10.0)) % 2 == 0
			cols.append(lin(cloth_dark if stripe else cloth_light))
	for i in nx + 1:
		for j in nz + 1:
			var x := lerpf(-L * 0.5, L * 0.5, float(i) / nx)
			var z := lerpf(-W * 0.5, W * 0.5, float(j) / nz)
			var dx := Vector3(0.1, roof_y.call(x + 0.05, z) - roof_y.call(x - 0.05, z), 0)
			var dz := Vector3(0, roof_y.call(x, z + 0.05) - roof_y.call(x, z - 0.05), 0.1)
			n.append(dz.cross(dx).normalized())
	for i in nx:
		for j in nz:
			var a := i * (nz + 1) + j
			BH._tri(idx, v, n, a, a + 1, a + nz + 1)
			BH._tri(idx, v, n, a + 1, a + nz + 2, a + nz + 1)
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = v
	arr[Mesh.ARRAY_NORMAL] = n
	arr[Mesh.ARRAY_COLOR] = cols
	arr[Mesh.ARRAY_INDEX] = idx
	var roof := ArrayMesh.new()
	roof.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	# walls: back and sides hang from the roof edge; a sadu band runs across the back
	var wall_h := H - 0.85 * size
	var wall := BH.V("diel", cloth_dark, 0.95)
	parts.append([BH.slab(Vector3(L, wall_h, 0.05), 0.2, 8), Mk.xf(Vector3(0, wall_h * 0.5, -W * 0.5 + 0.03)), wall])
	for s: float in [-1.0, 1.0]:
		parts.append([BH.slab(Vector3(0.05, wall_h, W * 0.98), 0.2, 8), Mk.xf(Vector3(s * (L * 0.5 - 0.03), wall_h * 0.5, 0)), wall])
	var red := BH.V("diel", Color(0.72, 0.1, 0.09), 0.9)
	var cream := BH.V("diel", Color(0.95, 0.9, 0.8), 0.9)
	var black := BH.V("diel", Color(0.08, 0.07, 0.06), 0.9)
	var band_y := wall_h * 0.55
	parts.append([BH.slab(Vector3(L - 0.1, 0.5 * size, 0.03), 0.2, 8), Mk.xf(Vector3(0, band_y, -W * 0.5 + 0.07)), red])
	for k in int(L / (0.42 * size)):
		var x := -L * 0.5 + 0.3 + k * 0.42 * size
