		parts.append([Mk.cyl(0.02, 0.03, 0.3, 6), Mk.xf(peg + Vector3(0, 0.1, 0)), pole])
	for s: float in [-1.0, 1.0]:
		var c := Vector3(s * L * 0.5, roof_y.call(s * L * 0.5, -W * 0.5), -W * 0.5)
		parts.append([tube_r([c, c + Vector3(s * 2.0, -c.y, -1.2) * size], [0.012, 0.012], 4, false), Transform3D(), BH.V("diel", Color(0.75, 0.66, 0.5), 0.9)])
	# rugs, cushions, low table, coffee pot and cups
	parts.append([BH.slab(Vector3(L * 0.75, 0.04, W * 0.62), 0.2, 8), Mk.xf(Vector3(0, 0.02, -0.1)), BH.V("diel", Color(0.6, 0.12, 0.12), 0.95)])
	parts.append([BH.slab(Vector3(L * 0.7, 0.05, W * 0.55), 0.2, 8), Mk.xf(Vector3(0, 0.03, -0.1)), BH.V("diel", Color(0.15, 0.2, 0.45), 0.95)])
	parts.append([BH.slab(Vector3(L * 0.6, 0.06, W * 0.42), 0.2, 8), Mk.xf(Vector3(0, 0.04, -0.1)), BH.V("diel", Color(0.7, 0.15, 0.12), 0.95)])
	var cush := [Color(0.75, 0.12, 0.1), Color(0.1, 0.4, 0.22), Color(0.85, 0.6, 0.15)]
	for k in 7:
		var x := -L * 0.33 + k * L * 0.11
		parts.append([BH.slab(Vector3(L * 0.1, 0.2, 0.55) * Vector3(1, size, size), 0.8, 10), Mk.xf(Vector3(x, 0.14, -W * 0.5 + 0.45)), BH.V("diel", cush[k % 3], 0.9)])
		parts.append([BH.slab(Vector3(L * 0.1, 0.5, 0.18) * Vector3(1, size, size), 0.8, 10), Mk.xf(Vector3(x, 0.35, -W * 0.5 + 0.18), Vector3(-0.15, 0, 0)), BH.V("diel", cush[(k + 1) % 3], 0.9)])
	parts.append([BH.slab(Vector3(1.0, 0.06, 0.6), 0.4, 10), Mk.xf(Vector3(0.6, 0.3, 0.2)), BH.V("diel", Color(0.5, 0.33, 0.18), 0.6)])
