	parts.append([tube_r([Vector3(0.08, 0.1, 0), Vector3(0.15, 0.2, 0), Vector3(0.2, 0.3, 0), Vector3(0.24, 0.31, 0)], [0.02, 0.016, 0.012, 0.01], 6), dallah, brass])
	parts.append([tube_r([Vector3(-0.05, 0.25, 0), Vector3(-0.16, 0.2, 0), Vector3(-0.12, 0.08, 0)], [0.008, 0.008, 0.008], 5), dallah, brass])
	for k in 4:
		parts.append([BH.lathe([Vector2(0.0, 0.0), Vector2(0.022, 0.0), Vector2(0.03, 0.045), Vector2(0.026, 0.045), Vector2(0.0, 0.006)], 10), Mk.xf(Vector3(0.75 + (k % 2) * 0.1, 0.33, 0.1 + (k / 2) * 0.12)), BH.V("diel", Color(0.95, 0.95, 0.92), 0.2)])
