## Road surface meshes from road samples, and the road shader (tarmac with lines, gravel, dirt, sand; rain puddles).

const ROAD_SHADER := """
shader_type spatial;
render_mode cull_back;
uniform sampler2D asphalt : filter_linear_mipmap, repeat_enable;
uniform sampler2D noise_t : filter_linear_mipmap, repeat_enable;
uniform sampler2D gravel_n : hint_normal, filter_linear_mipmap, repeat_enable;
uniform sampler2D ground_n : hint_normal, filter_linear_mipmap, repeat_enable;
uniform sampler2D water_n : hint_normal, filter_linear_mipmap, repeat_enable;
uniform float hw = 5.0;
uniform float wet = 0.0;
uniform vec3 tint = vec3(1.0);
uniform vec3 shoulder_col : source_color = vec3(0.5, 0.4, 0.28);
uniform vec2 cloud_off = vec2(0.0);
uniform float cloud_shadow = 0.35;
varying vec3 wpos;
varying vec2 sv;
void vertex() {
	wpos = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	sv = UV2;
}
void fragment() {
	float lat = (UV.x - 0.5) * 2.0 * hw;
	float al = UV.y;
	float alat = abs(lat);
	float s = sv.x;
	float w_t = 1.0 - smoothstep(0.25, 0.75, s);
	float w_g = smoothstep(0.25, 0.75, s) * (1.0 - smoothstep(1.25, 1.75, s));
	float w_d = smoothstep(1.25, 1.75, s) * (1.0 - smoothstep(2.25, 2.75, s));
	float w_s = smoothstep(2.25, 2.75, s);
	vec2 uv = vec2(lat, al);
	vec4 a = texture(asphalt, uv * 0.25);
	vec4 a2 = texture(asphalt, uv * 0.031);
	vec4 n1 = texture(noise_t, uv * 0.11);
	vec4 n2 = texture(noise_t, vec2(lat * 0.05, al * 0.006));
	// wheel tracks (two per lane)
	float tr = 0.0;
	for (int k = 0; k < 4; k++) {
		float c = (float(k) - 1.5) * hw * 0.48;
		tr += exp(-pow((lat - c) / 0.55, 2.0));
	}
	// tarmac
	vec3 tar = vec3(0.105, 0.105, 0.11) * (0.75 + 0.5 * a.r) * (0.9 + 0.2 * a2.a);
	tar = mix(tar, vec3(0.06), a.b * 0.7);
	tar = mix(tar, tar * 0.55, a.g * 0.8);
	tar *= 1.0 - tr * 0.18;
	float edge = smoothstep(0.09, 0.0, abs(alat - (hw - 0.4)));
	float dash = step(fract(al / 12.0), 0.5) * smoothstep(0.12, 0.05, alat);
	vec3 paint = vec3(0.92, 0.92, 0.88) * (0.8 + 0.2 * n1.r);
	float worn = smoothstep(0.35, 0.65, n2.g);
	tar = mix(tar, paint, clamp((edge + dash) * (1.0 - worn * 0.5), 0.0, 1.0));
	// gravel
	vec3 grv = vec3(0.56, 0.5, 0.42) * (0.72 + 0.45 * n1.r);
	grv *= 1.0 - tr * 0.22;
	grv = mix(grv, grv * vec3(1.08, 1.0, 0.9), n2.b);
	// dirt
	vec3 drt = vec3(0.46, 0.33, 0.21) * (0.78 + 0.4 * n1.r);
	drt *= 1.0 - tr * 0.28;
	// sand
	vec3 snd = vec3(0.86, 0.78, 0.6) * (0.85 + 0.25 * n1.g);
	snd *= 1.0 - tr * 0.2;
	vec3 c = tar * w_t + grv * w_g + drt * w_d + snd * w_s;
	// shoulders: soft verge colour
	float sh = smoothstep(hw - 0.05, hw + 0.4, alat);
	vec3 verge = shoulder_col * (0.75 + 0.45 * n1.r);
	c = mix(c, verge, sh * (0.7 + 0.3 * w_t));
	// rain: darker + puddles in the tracks / dips
	float pud = smoothstep(0.58, 0.72, n2.r + tr * 0.12) * wet * (1.0 - w_t * 0.6) * (1.0 - sh);
	float wetk = wet * (0.85 + 0.15 * n1.g);
	c *= 1.0 - wetk * 0.38;
	c = mix(c, c * 0.45 + vec3(0.02, 0.025, 0.03), pud);
	float cs = texture(noise_t, wpos.xz * 0.0011 + cloud_off).g;
	c *= 1.0 - cloud_shadow * smoothstep(0.52, 0.7, cs);
	ALBEDO = c * tint;
	float rough = mix(0.86, 0.93, 1.0 - w_t) - (edge + dash) * 0.15 * w_t;
	ROUGHNESS = mix(rough, 0.28, wetk * 0.8 * w_t + wetk * 0.3);
	ROUGHNESS = mix(ROUGHNESS, 0.04, pud);
	SPECULAR = 0.4 + wetk * 0.3;
	vec3 nm = mix(texture(ground_n, uv * 0.35).xyz, texture(gravel_n, uv * 0.3).xyz, w_g + w_d * 0.6);
	vec3 rip = texture(water_n, wpos.xz * 0.6 + vec2(TIME * 0.31, TIME * 0.17)).xyz;
	nm = mix(nm, rip, pud * 0.6);
	NORMAL_MAP = mix(vec3(0.5, 0.5, 1.0), nm, 0.35 + 0.65 * (1.0 - w_t) + pud * 0.3);
}
"""


static func material(tex: Dictionary, hw: float) -> ShaderMaterial:
	var sh := Shader.new()
	sh.code = ROAD_SHADER
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("asphalt", tex.asphalt)
	m.set_shader_parameter("noise_t", tex.noise)
	m.set_shader_parameter("gravel_n", tex.gravel_n)
	m.set_shader_parameter("ground_n", tex.ground_n)
	m.set_shader_parameter("water_n", tex.water_n)
	m.set_shader_parameter("hw", hw)
	return m


## Builds the road between samples i0..i1 (inclusive). px/pz/ph: centre line, tx/tz: unit tangent,
## sf: surface per sample (0 tarmac, 1 gravel, 2 dirt, 3 sand), dist: distance along the road per sample.
static func build(px: PackedFloat32Array, pz: PackedFloat32Array, ph: PackedFloat32Array, tx: PackedFloat32Array, tz: PackedFloat32Array,
		sf: PackedByteArray, dist: PackedFloat32Array, i0: int, i1: int, hw: float, loop_n := 0) -> ArrayMesh:
	var offs := [-hw - 2.4, -hw - 0.9, -hw, -hw * 0.5, 0.0, hw * 0.5, hw, hw + 0.9, hw + 2.4]
	var dys := [-0.45, -0.06, 0.0, 0.025, 0.04, 0.025, 0.0, -0.06, -0.45]
	var cols := offs.size()
	var verts := PackedVector3Array()
	var norms := PackedVector3Array()
	var uvs := PackedVector2Array()
	var uv2s := PackedVector2Array()
	var idx := PackedInt32Array()
	var rows := 0
	for ii in range(i0, i1 + 1):
		var i := ii % loop_n if loop_n > 0 else ii
		var rx := -tz[i]
		var rz := tx[i]
		# smooth the surface code over neighbours for soft transitions
		var s := float(sf[i])
		for c in cols:
			var o: float = offs[c]
			verts.append(Vector3(px[i] + rx * o, ph[i] + dys[c], pz[i] + rz * o))
			norms.append(Vector3.UP)
			uvs.append(Vector2(o / (2.0 * hw) + 0.5, dist[i]))
			uv2s.append(Vector2(s, 0.0))
		rows += 1
	for r in rows - 1:
		for c in cols - 1:
			var a := r * cols + c
			idx.append_array([a, a + cols, a + 1, a + 1, a + cols, a + cols + 1])
	# soften surface changes: average the surface code over +-6 rows
	var sm := PackedFloat32Array()
	sm.resize(rows)
	for r in rows:
		var acc := 0.0
		var cnt := 0
		for k in range(-6, 7):
			var rr := clampi(r + k, 0, rows - 1)
			acc += uv2s[rr * cols].x
			cnt += 1
		sm[r] = acc / cnt
	for r in rows:
		for c in cols:
			uv2s[r * cols + c] = Vector2(sm[r], 0.0)
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = verts
	arr[Mesh.ARRAY_NORMAL] = norms
	arr[Mesh.ARRAY_TEX_UV] = uvs
	arr[Mesh.ARRAY_TEX_UV2] = uv2s
	arr[Mesh.ARRAY_INDEX] = idx
	var tmp := ArrayMesh.new()
	tmp.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	var st := SurfaceTool.new()
	st.create_from(tmp, 0)
	st.generate_normals()
	st.generate_tangents()
	return st.commit()

files.scripts/sky.gd:
extends Node3D
## Sky, sun/moon, fog, tone mapping, time of day (midday, golden hour, night), rain with lightning.

const SKY_SHADER := """
shader_type sky;
uniform vec3 sun_dir = vec3(0.3, 0.8, 0.5);
uniform vec3 sun_col : source_color = vec3(1.0, 0.95, 0.85);
uniform vec3 zenith : source_color = vec3(0.18, 0.42, 0.85);
uniform vec3 horizon : source_color = vec3(0.72, 0.85, 0.95);
uniform vec3 ground_col : source_color = vec3(0.3, 0.38, 0.45);
uniform vec3 cloud_lit : source_color = vec3(1.0, 1.0, 1.0);
uniform vec3 cloud_shade : source_color = vec3(0.62, 0.68, 0.76);
uniform float cloud_cover = 0.45;
uniform float night = 0.0;
uniform float flash = 0.0;
uniform float sun_disk = 1.0;
uniform float energy = 1.0;
uniform vec3 moon_dir = vec3(-0.3, 0.6, -0.6);
uniform vec2 cloud_off = vec2(0.0);
uniform sampler2D clouds : filter_linear_mipmap, repeat_enable;

float hash13(vec3 p) {
	p = fract(p * 0.1031);
	p += dot(p, p.zyx + 31.32);
	return fract((p.x + p.y) * p.z);
}

void sky() {
	vec3 d = normalize(EYEDIR);
	float y = d.y;
	float hy = clamp(y, 0.0, 1.0);
	float t = pow(1.0 - hy, 5.0);
	vec3 col = mix(zenith, horizon, t);
	col = mix(col, ground_col, smoothstep(0.0, -0.25, y));
	float sd = max(dot(d, normalize(sun_dir)), 0.0);
	col += sun_col * (pow(sd, 6.0) * 0.22 + pow(sd, 48.0) * 0.45) * (1.0 - night * 0.85);
	float disk = smoothstep(0.99955, 0.99975, sd) * sun_disk;
	col += sun_col * disk * 16.0 * (1.0 - night);
	// moon
	float md = max(dot(d, normalize(moon_dir)), 0.0);
	col += vec3(0.9, 0.93, 1.0) * smoothstep(0.99935, 0.9996, md) * 3.0 * night;
	col += vec3(0.2, 0.25, 0.4) * pow(md, 30.0) * 0.4 * night;
	// stars
	if (night > 0.01 && y > 0.0) {
		vec3 p = d * 240.0;
		vec3 c = floor(p);
		float h = hash13(c);
		float star = step(0.9965, h) * smoothstep(0.42, 0.1, length(fract(p) - 0.5));
		float tw = 0.65 + 0.35 * sin(TIME * 3.0 + h * 80.0);
		col += vec3(0.9, 0.95, 1.0) * star * tw * night * smoothstep(0.0, 0.2, y) * 2.5 * (1.0 - cloud_cover);
	}
	// clouds on a dome
	if (y > 0.0) {
		vec2 uv = d.xz / (y + 0.12) * 0.22 + cloud_off;
		float a = texture(clouds, uv).r;
		float b = texture(clouds, uv * 2.9 + 0.3).g;
		float w = texture(clouds, uv * 0.7 - 0.2).b;
		float dens = a * 0.7 + b * 0.3 + w * 0.12;
		float cov = clamp(cloud_cover, 0.0, 1.0);
		float c = smoothstep(1.0 - cov - 0.08, 1.0 - cov + 0.3, dens);
		c *= smoothstep(0.0, 0.14, y);
		float lit = clamp(0.55 + (b - 0.5) * 0.8 + pow(sd, 4.0) * 0.6, 0.0, 1.3);
		vec3 cc = mix(cloud_shade, cloud_lit, lit);
		cc += sun_col * pow(sd, 10.0) * 0.6 * (1.0 - c) * (1.0 - night);
		col = mix(col, cc, c * 0.95);
	}
	col += vec3(0.8, 0.85, 1.0) * flash * 1.6;
	COLOR = col * energy;
}
"""

const RAIN_SHADER := """
shader_type spatial;
render_mode unshaded, blend_add, cull_disabled, depth_draw_never, shadows_disabled, skip_vertex_transform;
uniform vec3 cam_pos = vec3(0.0);
uniform vec3 drift = vec3(0.0);
uniform float amount = 1.0;
uniform float bright = 1.0;
varying float a;
void vertex() {
	vec3 o = VERTEX;
	vec3 fall = vec3(0.0, -15.0, 0.0) - drift;
	vec3 p = o + fall * TIME * (0.85 + UV2.x * 0.3);
	p = mod(p - cam_pos + 20.0, 40.0) - 20.0 + cam_pos;
	vec3 ax = normalize(fall) * (0.55 + 0.35 * UV2.x);
	vec3 vd = normalize(p - CAMERA_POSITION_WORLD);
	vec3 sd = normalize(cross(ax, vd)) * 0.012 * (1.0 + length(p - CAMERA_POSITION_WORLD) * 0.06);
	vec3 wp = p + sd * (UV.x - 0.5) * 2.0 + ax * UV.y;
	VERTEX = (VIEW_MATRIX * vec4(wp, 1.0)).xyz;
	float dist = length(p - CAMERA_POSITION_WORLD);
	a = step(UV2.y, amount) * smoothstep(0.6, 2.5, dist) * (1.0 - smoothstep(14.0, 20.0, dist)) * (UV.y > 0.5 ? 0.0 : 1.0);
}
void fragment() {
	ALBEDO = vec3(0.6, 0.66, 0.75) * bright;
	ALPHA = a * 0.35;
}
"""

var env: Environment
var wenv: WorldEnvironment
var sky_mat: ShaderMaterial
var sun: DirectionalLight3D
var rain_mi: MeshInstance3D
var rain_mat: ShaderMaterial
var tod := 0
var raining := false
var night := 0.0
var wet := 0.0
var flash := 0.0
var flash_t := 0.0
var next_bolt := 8.0
var thunder_t := -1.0
var cloud_off := Vector2.ZERO
var base_sun_energy := 1.3
var cloud_amount := 0.45
var gfx := 1
var shadow_far := 110.0


func setup(clouds: Texture2D) -> void:
	wenv = WorldEnvironment.new()
	env = Environment.new()
	env.background_mode = Environment.BG_SKY
	var sky := Sky.new()
	sky_mat = ShaderMaterial.new()
	var sh := Shader.new()
	sh.code = SKY_SHADER
	sky_mat.shader = sh
	sky_mat.set_shader_parameter("clouds", clouds)
	sky.sky_material = sky_mat
	sky.radiance_size = Sky.RADIANCE_SIZE_64
	env.sky = sky
	env.ambient_light_source = Environment.AMBIENT_SOURCE_SKY
	env.reflected_light_source = Environment.REFLECTION_SOURCE_SKY
	env.tonemap_mode = Environment.TONE_MAPPER_ACES
	env.tonemap_exposure = 1.0
	env.tonemap_white = 6.0
	env.fog_enabled = true
	env.fog_mode = Environment.FOG_MODE_EXPONENTIAL
	env.fog_sky_affect = 0.0
	env.glow_enabled = true
	env.glow_intensity = 0.4
	env.glow_bloom = 0.03
	env.glow_hdr_threshold = 1.2
	env.glow_blend_mode = Environment.GLOW_BLEND_MODE_SOFTLIGHT
	env.adjustment_enabled = true
	env.adjustment_saturation = 1.12
	env.adjustment_contrast = 1.06
	wenv.environment = env
	add_child(wenv)
	sun = DirectionalLight3D.new()
	sun.shadow_enabled = true
	sun.directional_shadow_mode = DirectionalLight3D.SHADOW_PARALLEL_2_SPLITS
	sun.directional_shadow_max_distance = shadow_far
	sun.shadow_blur = 1.2
	sun.shadow_bias = 0.04
	sun.shadow_normal_bias = 1.2
	sun.directional_shadow_blend_splits = true
	add_child(sun)
	_rain()


func _rain() -> void:
	var n := 5000
	var verts := PackedVector3Array()
	var uvs := PackedVector2Array()
	var uv2s := PackedVector2Array()
	var idx := PackedInt32Array()
	var rng := RandomNumberGenerator.new()
	rng.seed = 4
	for i in n:
		var o := Vector3(rng.randf() * 40.0, rng.randf() * 40.0, rng.randf() * 40.0)
		var r := Vector2(rng.randf(), rng.randf())
		var b := i * 4
		for c in [Vector2(0, 0), Vector2(1, 0), Vector2(1, 1), Vector2(0, 1)]:
			verts.append(o)
			uvs.append(c)
			uv2s.append(r)
		idx.append_array([b, b + 1, b + 2, b, b + 2, b + 3])
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = verts
	arr[Mesh.ARRAY_TEX_UV] = uvs
	arr[Mesh.ARRAY_TEX_UV2] = uv2s
	arr[Mesh.ARRAY_INDEX] = idx
	var m := ArrayMesh.new()
	m.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	m.custom_aabb = AABB(Vector3(-1e5, -1e4, -1e5), Vector3(2e5, 2e4, 2e5))
	rain_mat = ShaderMaterial.new()
	var sh := Shader.new()
	sh.code = RAIN_SHADER
	rain_mat.shader = sh
	rain_mi = MeshInstance3D.new()
	rain_mi.mesh = m
	rain_mi.material_override = rain_mat
	rain_mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	rain_mi.visible = false
	add_child(rain_mi)


func configure(level: int) -> void:
	gfx = level
	sun.shadow_enabled = level > 0
	RenderingServer.directional_shadow_atlas_set_size(4096 if level >= 2 else 2048, true)
	if level >= 2:
		sun.directional_shadow_mode = DirectionalLight3D.SHADOW_PARALLEL_4_SPLITS
		shadow_far = 200.0
		sun.shadow_blur = 1.0
	else:
		sun.directional_shadow_mode = DirectionalLight3D.SHADOW_PARALLEL_2_SPLITS
		shadow_far = 110.0
		sun.shadow_blur = 1.3
	sun.directional_shadow_max_distance = shadow_far
	env.glow_enabled = level > 0
	rain_mat.set_shader_parameter("amount", [0.45, 0.75, 1.0][level])


## Short shadow range for close-ups in menus.
func set_close(close: bool) -> void:
	if close:
		sun.directional_shadow_mode = DirectionalLight3D.SHADOW_ORTHOGONAL
		sun.directional_shadow_max_distance = 24.0
		sun.shadow_normal_bias = 2.0
	else:
		configure(gfx)
		sun.shadow_normal_bias = 1.2


func set_time(t: int, rain: bool) -> void:
	tod = t
	raining = rain
	var el := 0.0
	var az := 0.0
	match t:
		0:
			el = 58.0
			az = 215.0
		1:
			el = 9.0
			az = 255.0
		2:
			el = 38.0
			az = 140.0
	var d := Vector3(sin(deg_to_rad(az)) * cos(deg_to_rad(el)), sin(deg_to_rad(el)), cos(deg_to_rad(az)) * cos(deg_to_rad(el)))
	sun.transform = Transform3D(Basis.looking_at(-d, Vector3.UP), Vector3.ZERO)
	night = 1.0 if t == 2 else 0.0
	var p := {}
	match t:
		0:
			p = {"sun": Color(1.0, 0.95, 0.86), "e": 1.45, "z": Color(0.16, 0.4, 0.86), "h": Color(0.7, 0.84, 0.96), "g": Color(0.36, 0.48, 0.56),
				"fog": Color(0.7, 0.8, 0.9), "fd": 0.00055, "amb": 1.0, "exp": 1.0, "cl": Color(1, 1, 1), "cs": Color(0.66, 0.72, 0.8), "cov": 0.42}
		1:
			p = {"sun": Color(1.0, 0.62, 0.34), "e": 1.7, "z": Color(0.22, 0.32, 0.62), "h": Color(1.0, 0.66, 0.42), "g": Color(0.45, 0.35, 0.32),
				"fog": Color(0.92, 0.66, 0.48), "fd": 0.0007, "amb": 0.8, "exp": 1.05, "cl": Color(1.0, 0.78, 0.6), "cs": Color(0.55, 0.42, 0.48), "cov": 0.5}
		2:
			p = {"sun": Color(0.6, 0.7, 1.0), "e": 0.55, "z": Color(0.012, 0.022, 0.06), "h": Color(0.07, 0.1, 0.18), "g": Color(0.03, 0.04, 0.07),
				"fog": Color(0.05, 0.075, 0.13), "fd": 0.001, "amb": 0.9, "exp": 1.3, "cl": Color(0.2, 0.22, 0.3), "cs": Color(0.06, 0.07, 0.1), "cov": 0.35}
	var sun_c: Color = p.sun
	var e: float = p.e
	var z: Color = p.z
	var h: Color = p.h
	var fog: Color = p.fog
	var fd: float = p.fd
	var cov: float = p.cov
	var cl: Color = p.cl
	var cs: Color = p.cs
	if rain:
		var grey := Color(0.44, 0.48, 0.53) if t != 2 else Color(0.03, 0.04, 0.06)
		z = z.lerp(grey * 0.8, 0.85)
		h = h.lerp(grey, 0.8)
		fog = fog.lerp(grey, 0.8)
		fd = fd * 3.2
		e *= 0.32
		cov = 0.92
		cl = cl.lerp(grey * 1.25, 0.7)
		cs = cs.lerp(grey * 0.7, 0.8)
	base_sun_energy = e
	cloud_amount = cov
	sun.light_color = sun_c
	sun.light_energy = e
	sky_mat.set_shader_parameter("sun_dir", d)
	sky_mat.set_shader_parameter("sun_col", sun_c)
	sky_mat.set_shader_parameter("zenith", z)
	sky_mat.set_shader_parameter("horizon", h)
	sky_mat.set_shader_parameter("ground_col", p.g)
	sky_mat.set_shader_parameter("cloud_lit", cl)
	sky_mat.set_shader_parameter("cloud_shade", cs)
	sky_mat.set_shader_parameter("cloud_cover", cov)
	sky_mat.set_shader_parameter("night", night)
	sky_mat.set_shader_parameter("sun_disk", 0.0 if rain or t == 2 else 1.0)
	sky_mat.set_shader_parameter("moon_dir", d)
	env.fog_light_color = fog
	env.fog_density = fd
	env.fog_sun_scatter = 0.0 if rain else (0.35 if t == 1 else 0.12)
	env.ambient_light_energy = p.amb * (0.85 if rain else 1.0)
	env.ambient_light_sky_contribution = 1.0
	env.tonemap_exposure = p.exp
	env.glow_intensity = 0.7 if t == 2 else 0.4
	env.adjustment_saturation = 0.95 if rain else (1.15 if t != 2 else 1.0)
	wet = 1.0 if rain else 0.0
	rain_mi.visible = rain
	rain_mat.set_shader_parameter("bright", 0.35 if t == 2 else 1.0)
	next_bolt = randf_range(6.0, 12.0)


func update(dt: float, cam: Vector3, car_vel: Vector3) -> void:
	cloud_off += Vector2(0.0022, 0.0011) * dt
	sky_mat.set_shader_parameter("cloud_off", cloud_off)
	if rain_mi.visible:
		rain_mat.set_shader_parameter("cam_pos", cam)
		rain_mat.set_shader_parameter("drift", Vector3(car_vel.x, 0, car_vel.z) * 0.6)
		next_bolt -= dt
		if next_bolt <= 0.0:
			next_bolt = randf_range(9.0, 22.0)
			flash_t = 0.45
			thunder_t = randf_range(0.8, 2.5)
		if flash_t > 0.0:
			flash_t -= dt
			flash = 1.0 if (flash_t > 0.33 or (flash_t > 0.12 and flash_t < 0.22)) else 0.0
		else:
			flash = 0.0
		if thunder_t > 0.0:
			thunder_t -= dt
			if thunder_t <= 0.0:
				G.play("thunder", randf_range(0.85, 1.1), -2.0)
	else:
		flash = 0.0
	sky_mat.set_shader_parameter("flash", flash)
	sun.light_energy = base_sun_energy + flash * 2.5

files.scripts/terrain.gd:
extends Node3D
## Terrain streamer: square chunks in up to three LOD rings around the camera. A data source fills each
## chunk's height grid and material attributes; this builds the meshes (with skirts), the per-chunk water
## surface and the near grass. Coarser rings cut holes (shader discard via a small mask texture) where a
## finer ring is ready, and dip slightly near the boundary so cracks stay hidden under the finer ring's skirts.

const TERRAIN_SHADER := """
shader_type spatial;
render_mode cull_back;
uniform sampler2D noise_t : filter_linear_mipmap, repeat_enable;
uniform sampler2D ground_n : hint_normal, filter_linear_mipmap, repeat_enable;
uniform sampler2D rock_n : hint_normal, filter_linear_mipmap, repeat_enable;
uniform sampler2D rock_a : filter_linear_mipmap, repeat_enable;
uniform sampler2D sand_n : hint_normal, filter_linear_mipmap, repeat_enable;
uniform sampler2D hole_mask : filter_nearest;
uniform vec4 hole_win = vec4(0.0, 0.0, 64.0, 0.0);
uniform vec3 cam_pos = vec3(0.0);
uniform float drop = 0.0;
uniform float drop_r0 = 200.0;
uniform float drop_r1 = 320.0;
uniform vec3 sand_col : source_color = vec3(0.86, 0.78, 0.6);
uniform vec3 wet_sand : source_color = vec3(0.55, 0.47, 0.34);
uniform vec3 rock_col : source_color = vec3(0.43, 0.39, 0.35);
uniform vec3 dirt_col : source_color = vec3(0.5, 0.38, 0.26);
uniform vec3 snow_col : source_color = vec3(0.92, 0.95, 1.0);
uniform float sea = 0.0;
uniform float wet = 0.0;
uniform float time_s = 0.0;
uniform vec2 cloud_off = vec2(0.0);
uniform float cloud_shadow = 0.35;
uniform float full_color = 0.0;
varying vec3 wpos;
varying vec4 vcol;
varying vec2 m1;
varying vec2 m2;
varying float ny;
uniform float hw = 5.0;

vec3 c_trop(float h, float s, float n1, float n2, float n3, float fo) {
	vec3 c = vec3(214.0 + n1 * 9.0 + n3 * 6.0, 196.0 + n1 * 8.0 + n3 * 5.0, 156.0 + n1 * 8.0 + n3 * 4.0);
	c = mix(c, vec3(160.0, 140.0, 104.0), 1.0 - smoothstep(-0.1, 0.7, h));
	c = mix(c, vec3(205.0, 192.0, 152.0), 1.0 - smoothstep(-8.0, -0.4, h));
	float gt = smoothstep(2.1 + n2 * 0.5, 2.9 + n2 * 0.5, h);
	vec3 g = vec3(74.0 + n1 * 12.0, 112.0 + n1 * 14.0, 42.0 + n1 * 6.0);
	g = mix(g, vec3(140.0, 136.0, 74.0), smoothstep(0.15, 0.55, n2 + n3 * 0.15) * 0.7);
	float f = smoothstep(0.12, 0.35, fo) * 0.3;
	g *= vec3(1.0 - f, 1.0 - f * 0.7, 1.0 - f);
	c = mix(c, g, gt);
	float rk = smoothstep(0.42, 0.78, s + n3 * 0.08);
	float v = 108.0 + n1 * 16.0 + n3 * 18.0 + sin(h * 1.9 + n1 * 2.5) * 10.0;
	return mix(c, vec3(v + 8.0, v, v - 14.0), rk);
}
vec3 c_high(float h, float s, float n1, float n2, float n3, float fo) {
	vec3 c = vec3(70.0 + n1 * 10.0, 104.0 + n1 * 12.0, 48.0 + n1 * 6.0);
	c = mix(c, vec3(118.0, 120.0, 66.0), smoothstep(0.2, 0.6, n2) * 0.5);
	c = mix(c, vec3(36.0, 58.0, 30.0), smoothstep(0.0, 0.3, fo) * 0.8);
	c = mix(c, vec3(128.0, 120.0, 100.0), 1.0 - smoothstep(0.4, 2.2, h));
	float rk = smoothstep(0.48, 0.85, s + n3 * 0.08);
	float v = 112.0 + n1 * 14.0 + n3 * 16.0 + sin(h * 1.3 + n1 * 2.0) * 8.0;
	c = mix(c, vec3(v, v - 2.0, v - 6.0), rk);
	float sn = smoothstep(78.0, 90.0, h + n2 * 8.0 + n1 * 3.0) * (1.0 - smoothstep(0.75, 1.05, s));
	return mix(c, vec3(236.0, 240.0, 247.0), sn);
}
vec3 c_canyon(float h, float s, float n1, float n2, float n3) {
	vec3 c = vec3(196.0 + n1 * 10.0 + n3 * 6.0, 114.0 + n1 * 8.0 + n3 * 4.0, 66.0 + n1 * 6.0 + n3 * 3.0);
	c = mix(c, vec3(170.0, 140.0, 84.0), smoothstep(0.15, 0.5, n2) * 0.45);
	float rk = smoothstep(0.38, 0.7, s + n3 * 0.06);
	float band = 0.5 + 0.5 * sin(h * 0.85 + n1 * 1.6);
	float dk = 0.88 + n3 * 0.1;
	return mix(c, vec3(mix(146.0, 216.0, band), mix(68.0, 150.0, band), mix(40.0, 100.0, band)) * dk, rk);
}
vec3 c_autumn(float h, float s, float n1, float n2, float n3, float fo) {
	vec3 c = vec3(118.0 + n1 * 12.0, 122.0 + n1 * 12.0, 54.0 + n1 * 6.0);
	c = mix(c, vec3(168.0, 142.0, 66.0), smoothstep(0.1, 0.5, n2) * 0.6);
	c = mix(c, vec3(150.0, 92.0, 42.0), smoothstep(0.0, 0.3, fo) * 0.75);
	c = mix(c, vec3(96.0, 88.0, 66.0), 1.0 - smoothstep(0.0, 2.0, h));
	float rk = smoothstep(0.45, 0.8, s + n3 * 0.08);
	float v = 116.0 + n1 * 14.0 + n3 * 14.0;
	return mix(c, vec3(v + 4.0, v - 2.0, v - 10.0), rk);
}

void vertex() {
	vec3 p = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	float d = length(p.xz - cam_pos.xz);
	VERTEX.y -= drop * (1.0 - smoothstep(drop_r0, drop_r1, d));
	wpos = p;
	vcol = COLOR;
	m1 = UV;
	m2 = UV2;
	ny = NORMAL.y;
}
void fragment() {
	if (hole_win.w > 0.5) {
		vec2 mc = (wpos.xz - hole_win.xy) / hole_win.z;
		ivec2 ic = ivec2(floor(mc));
		if (ic.x >= 0 && ic.y >= 0 && ic.x < int(hole_win.w) && ic.y < int(hole_win.w)) {
			if (texelFetch(hole_mask, ic, 0).r > 0.5) discard;
		}
	}
	vec2 uv = wpos.xz;
	vec4 n1 = texture(noise_t, uv * 0.13);
	vec4 n2 = texture(noise_t, uv * 0.017);
	vec4 n3 = texture(noise_t, uv * 0.0023);
	vec3 bio = vec3(0.0);
	float b_rock = 0.0;
	float b_snow = 0.0;
	float b_sand = 0.0;
	if (full_color > 0.5) {
		// endless world: landscape colour from the four biome weights (vertex colour), height, slope, road distance
		float h = wpos.y;
		float s = sqrt(max(1.0 / max(ny * ny, 0.01) - 1.0, 0.0));
		float rd = m1.y * 30.0;
		float bn1 = (texture(noise_t, uv * 0.011).r - 0.5) * 2.0;
		float bn2 = (texture(noise_t, uv * 0.0016).g - 0.5) * 1.6;
		float bn3 = (texture(noise_t, uv * 0.06).r - 0.5) * 2.0;
		float bfo = (texture(noise_t, uv * 0.0009).b - 0.5) * 1.4;
		vec4 w = vcol / max(vcol.r + vcol.g + vcol.b + vcol.a, 0.001);
		vec3 c255 = vec3(0.0);
		vec3 sh255 = vec3(0.0);
		if (w.r > 0.004) { c255 += c_trop(h, s, bn1, bn2, bn3, bfo) * w.r; sh255 += vec3(160.0, 130.0, 94.0) * w.r; }
		if (w.g > 0.004) { c255 += c_high(h, s, bn1, bn2, bn3, bfo) * w.g; sh255 += vec3(140.0, 132.0, 120.0) * w.g; }
		if (w.b > 0.004) { c255 += c_canyon(h, s, bn1, bn2, bn3) * w.b; sh255 += vec3(186.0, 112.0, 72.0) * w.b; }
		if (w.a > 0.004) { c255 += c_autumn(h, s, bn1, bn2, bn3, bfo) * w.a; sh255 += vec3(150.0, 122.0, 88.0) * w.a; }
		float shk = 1.0 - smoothstep(hw + 0.3, hw + 3.2 + bn3 * 0.6, rd);
		c255 = mix(c255, sh255 + vec3(bn3 * 10.0, bn3 * 8.0, bn3 * 6.0), shk);
		bio = pow(clamp(c255 / 255.0, 0.0, 1.0), vec3(2.2));
		b_rock = clamp(smoothstep(0.42, 0.78, s) * (w.r + w.a) + smoothstep(0.48, 0.85, s) * w.g + smoothstep(0.38, 0.7, s) * w.b, 0.0, 1.0);
		b_snow = w.g * smoothstep(78.0, 90.0, h + bn2 * 8.0 + bn1 * 3.0) * (1.0 - smoothstep(0.75, 1.05, s));
		b_sand = w.r * (1.0 - smoothstep(2.1, 2.9, h)) + w.b * 0.6;
	}
	// grass / soil base from the vertex colour with large and small scale variation
	vec3 base = vcol.rgb * (0.78 + 0.32 * n2.g) * (0.86 + 0.24 * n1.r);
	base = mix(base, base * vec3(1.12, 1.05, 0.7), smoothstep(0.55, 0.85, n3.b) * 0.6);
	float rock_in = full_color > 0.5 ? b_rock : m1.x;
	float rock = clamp(rock_in + (n2.b - 0.5) * 0.5 * rock_in, 0.0, 1.0);
	rock = smoothstep(0.3, 0.7, rock);
	float sand = clamp((full_color > 0.5 ? b_sand : m1.y) + (n1.g - 0.5) * 0.3, 0.0, 1.0);
	float snow = full_color > 0.5 ? smoothstep(0.3, 0.6, b_snow) : smoothstep(0.35, 0.65, m2.x + (n2.r - 0.5) * 0.4);
	float dirt = full_color > 0.5 ? 0.0 : clamp(m2.y, 0.0, 1.0);
	// triplanar-ish rock: blend xz and the dominant side projection
	float steep = 1.0 - ny;
	vec2 ruv = mix(uv, vec2(uv.x + uv.y, wpos.y * 1.6), smoothstep(0.25, 0.6, steep)) * 0.09;
	vec3 rcol = rock_col * (0.55 + 0.75 * texture(rock_a, ruv).r) * (0.85 + 0.3 * n2.r);
	vec3 scol = mix(sand_col * (0.9 + 0.18 * n1.r), wet_sand, 1.0 - smoothstep(sea + 0.1, sea + 0.9, wpos.y));
	vec3 dcol = dirt_col * (0.75 + 0.4 * n1.r);
	vec3 c = base;
	if (full_color > 0.5) {
		// endless world: the vertex colour already holds the blended landscape colour
		c = bio * mix((0.8 + 0.4 * n1.r) * (0.86 + 0.28 * n2.g), 0.95 + 0.08 * n1.r, snow);
		c *= mix(1.0, 0.55 + 0.75 * texture(rock_a, ruv).r, rock * (1.0 - snow));
	} else {
		c = mix(c, dcol, dirt);
		c = mix(c, scol, sand);
		c = mix(c, rcol, rock);
		c = mix(c, snow_col * (0.92 + 0.08 * n1.r), snow);
	}
	// underwater darkening
	float under = 1.0 - smoothstep(sea - 0.6, sea + 0.15, wpos.y);
	c = mix(c, c * vec3(0.55, 0.75, 0.8), under);
	// rain: darker, shinier
	float wetk = wet * (1.0 - snow) * (0.75 + 0.25 * n1.g);
	c *= 1.0 - wetk * 0.35;
	// moving cloud shadows
	float cs = texture(noise_t, uv * 0.0011 + cloud_off).g;
	c *= 1.0 - cloud_shadow * smoothstep(0.52, 0.7, cs);
	ALBEDO = c;
	ROUGHNESS = mix(mix(0.93, 0.6, wetk), 0.35, wetk * dirt) - snow * 0.25;
	SPECULAR = 0.35 + wetk * 0.3;
	vec3 gn = texture(ground_n, uv * 0.21).xyz;
	vec3 rn = texture(rock_n, ruv * 1.3).xyz;
	vec3 sn = texture(sand_n, uv * 0.15).xyz;
	vec3 nm = mix(gn, sn, sand);
	nm = mix(nm, rn, rock);
	nm = mix(nm, vec3(0.5, 0.5, 1.0), snow * 0.7);
	NORMAL_MAP = nm;
	NORMAL_MAP_DEPTH = 1.0 + rock * 0.6;
}
"""

const WATER_SHADER := """
shader_type spatial;
render_mode cull_back, specular_schlick_ggx;
uniform sampler2D water_n : hint_normal, filter_linear_mipmap, repeat_enable;
uniform sampler2D noise_t : filter_linear_mipmap, repeat_enable;
uniform sampler2D hole_mask : filter_nearest;
uniform vec4 hole_win = vec4(0.0, 0.0, 64.0, 0.0);
uniform vec3 cam_pos = vec3(0.0);
uniform vec3 deep_col : source_color = vec3(0.02, 0.16, 0.3);
uniform vec3 mid_col : source_color = vec3(0.03, 0.42, 0.55);
uniform vec3 shallow_col : source_color = vec3(0.12, 0.62, 0.62);
uniform vec3 sand_col : source_color = vec3(0.72, 0.68, 0.5);
uniform float wave_amp = 1.0;
uniform float rain = 0.0;
uniform float night = 0.0;
uniform float wave_fade = 260.0;
varying vec3 wpos;
varying float depth;
vec3 gerst(vec2 p, vec2 dir, float k, float a, float sp, inout vec3 tb) {
	float ph = k * dot(dir, p) - sp * TIME;
	tb += vec3(-dir.x * k * a * cos(ph), 0.0, -dir.y * k * a * cos(ph));
	return vec3(0.0, a * sin(ph), 0.0);
}
void vertex() {
	vec3 p = (MODEL_MATRIX * vec4(VERTEX, 1.0)).xyz;
	depth = UV.x;
	float d = length(p.xz - cam_pos.xz);
	float amp = wave_amp * smoothstep(0.0, 3.0, depth) * (1.0 - smoothstep(wave_fade * 0.6, wave_fade, d));
	vec3 tb = vec3(0.0);
	vec3 off = gerst(p.xz, normalize(vec2(0.8, 0.6)), 0.21, 0.22 * amp, 1.1, tb)
		+ gerst(p.xz, normalize(vec2(-0.4, 0.9)), 0.37, 0.12 * amp, 1.6, tb)
		+ gerst(p.xz, normalize(vec2(0.95, -0.3)), 0.61, 0.06 * amp, 2.2, tb)
		+ gerst(p.xz, normalize(vec2(-0.7, -0.7)), 0.09, 0.30 * amp, 0.7, tb);
	VERTEX.y += off.y;
	NORMAL = normalize(vec3(tb.x, 1.0, tb.z));
	TANGENT = normalize(vec3(1.0, -tb.x, 0.0));
	BINORMAL = normalize(cross(NORMAL, TANGENT));
	wpos = p + off;
}
void fragment() {
	if (hole_win.w > 0.5) {
		vec2 mc = (wpos.xz - hole_win.xy) / hole_win.z;
		ivec2 ic = ivec2(floor(mc));
		if (ic.x >= 0 && ic.y >= 0 && ic.x < int(hole_win.w) && ic.y < int(hole_win.w)) {
			if (texelFetch(hole_mask, ic, 0).r > 0.5) discard;
		}
	}
	vec2 uv = wpos.xz;
	vec2 na = texture(water_n, uv * 0.031 + vec2(TIME * 0.011, TIME * 0.007)).xy * 2.0 - 1.0;
	vec2 nb = texture(water_n, uv * 0.057 - vec2(TIME * 0.009, -TIME * 0.013)).xy * 2.0 - 1.0;
	vec2 nc = texture(water_n, uv * 0.17 + vec2(-TIME * 0.03, TIME * 0.021)).xy * 2.0 - 1.0;
	float dist = length(wpos - cam_pos);
	vec2 dn = (na + nb * 0.8 + nc * (0.5 + rain)) * mix(0.55, 0.18, smoothstep(30.0, 500.0, dist));
	NORMAL_MAP = normalize(vec3(dn, 1.0)) * 0.5 + 0.5;
	NORMAL_MAP_DEPTH = 1.0;
	float dpt = max(depth, 0.0);
	vec3 c = mix(sand_col * 0.7, shallow_col, smoothstep(0.0, 0.6, dpt));
	c = mix(c, mid_col, smoothstep(1.2, 6.0, dpt));
	c = mix(c, deep_col, smoothstep(7.0, 24.0, dpt));
	// sunlit caustic shimmer in the shallows
	float ca = texture(noise_t, uv * 0.35 + vec2(TIME * 0.05, 0.0)).a + texture(noise_t, uv * 0.29 - vec2(0.0, TIME * 0.04)).a;
	c += vec3(0.06, 0.08, 0.06) * smoothstep(1.1, 1.6, ca) * (1.0 - smoothstep(0.3, 3.0, dpt)) * (1.0 - night);
	// foam: a thin line at the water's edge plus bands rolling in
	float n = texture(noise_t, uv * 0.11 + vec2(TIME * 0.02)).g;
	float band = smoothstep(0.75, 0.95, sin(dpt * 9.0 - TIME * 1.4 + n * 4.0) * 0.5 + 0.5) * (1.0 - smoothstep(0.1, 0.7, dpt));
	float edge = 1.0 - smoothstep(0.02, 0.22, dpt);
	float foam = clamp((edge + band * 0.7) * smoothstep(0.25, 0.55, n + 0.25) * smoothstep(-0.05, 0.06, dpt), 0.0, 1.0);
	c = mix(c, vec3(0.85, 0.9, 0.92), foam * 0.8);
	ALBEDO = c * (1.0 - night * 0.5);
	ROUGHNESS = mix(0.05 + rain * 0.12, 0.6, foam);
	SPECULAR = 0.32;
	METALLIC = 0.0;
}
"""

const GRASS_SHADER := """
shader_type spatial;
render_mode cull_disabled, specular_disabled;
uniform vec3 cam_pos = vec3(0.0);
uniform float fade_r = 70.0;
uniform float wind = 1.0;
uniform float wet = 0.0;
varying vec3 tint;
void vertex() {
	vec3 ip = (MODEL_MATRIX * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
	float d = length(ip.xz - cam_pos.xz);
	float s = 1.0 - smoothstep(fade_r * 0.72, fade_r, d);
	float h = VERTEX.y;
	VERTEX *= s;
	float ph = ip.x * 0.11 + ip.z * 0.09;
	VERTEX.x += sin(TIME * 1.7 + ph) * 0.12 * h * h * wind;
	VERTEX.z += cos(TIME * 1.3 + ph * 1.3) * 0.09 * h * h * wind;
	tint = COLOR.rgb * mix(0.55, 1.12, clamp(h * 1.6, 0.0, 1.0));
	NORMAL = normalize(vec3(NORMAL.x * 0.25, 1.0, NORMAL.z * 0.25));
}
void fragment() {
	ALBEDO = tint * (1.0 - wet * 0.25);
	ROUGHNESS = 0.8 - wet * 0.3;
	BACKLIGHT = vec3(0.25, 0.3, 0.1);
}
"""

class Level:
	var size := 64.0
	var n := 32
	var step := 2.0
	var radius := 200.0
	var skirt := 2.0
	var drop := 0.0
	var chunks := {}
	var mat: ShaderMaterial
	var wmat: ShaderMaterial
	var mask_img: Image
	var mask_tex: ImageTexture
	var mask_res := 64
	var mask_org := Vector2i(1 << 30, 0)
	var permanent := false
	var bounds := Rect2()


var source
var levels: Array = []
var queue: Array = []
var jobs: Array = []
var cam := Vector3.ZERO
var last_plan := Vector3(1e9, 0, 1e9)
var tex := {}
var grass_mat: ShaderMaterial
var grass_mesh: ArrayMesh
var grass_count := 0
var grass_r := 70.0
var budget_us := 3000
var sea := 0.0
var idx_cache := {}
var built_count := 0
var stat_us := 0
var water_on := true
var shadows := true
var cloud_off := Vector2.ZERO


func setup(src, cfg: Array, textures: Dictionary, sea_level := 0.0) -> void:
	source = src
	tex = textures
	sea = sea_level
	for c in cfg:
		var L := Level.new()
		L.size = c.size
		L.n = c.n
		L.step = c.size / c.n
		L.radius = c.radius
		L.skirt = c.skirt
		L.drop = c.get("drop", 0.0)
		L.permanent = c.get("permanent", false)
		L.bounds = c.get("bounds", Rect2())
		L.mask_res = c.get("mask_res", 64)
		L.mat = _terrain_mat()
		L.wmat = _water_mat()
		levels.append(L)
	# coarser levels cut holes where the next finer level is ready
	for li in range(1, levels.size()):
		var fine: Level = levels[li - 1]
		fine.mask_img = Image.create(fine.mask_res, fine.mask_res, false, Image.FORMAT_R8)
		fine.mask_tex = ImageTexture.create_from_image(fine.mask_img)
		var L: Level = levels[li]
		for m in [L.mat, L.wmat]:
			m.set_shader_parameter("hole_mask", fine.mask_tex)
		L.mat.set_shader_parameter("drop", L.drop)
		L.mat.set_shader_parameter("drop_r0", fine.radius - fine.size * 0.5)
		L.mat.set_shader_parameter("drop_r1", fine.radius + fine.size * 1.5)
	grass_mat = ShaderMaterial.new()
	var gs := Shader.new()
	gs.code = GRASS_SHADER
	grass_mat.shader = gs
	grass_mesh = _grass_tuft()


func _terrain_mat() -> ShaderMaterial:
	var sh: Shader = tex.get("_tsh")
	if sh == null:
		sh = Shader.new()
		sh.code = TERRAIN_SHADER
		tex["_tsh"] = sh
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("noise_t", tex.noise)
	m.set_shader_parameter("ground_n", tex.ground_n)
	m.set_shader_parameter("rock_n", tex.rock_n)
	m.set_shader_parameter("rock_a", tex.rock_a)
	m.set_shader_parameter("sand_n", tex.sand_n)
	m.set_shader_parameter("sea", sea)
	return m


func _water_mat() -> ShaderMaterial:
	var sh: Shader = tex.get("_wsh")
	if sh == null:
		sh = Shader.new()
		sh.code = WATER_SHADER
		tex["_wsh"] = sh
	var m := ShaderMaterial.new()
	m.shader = sh
	m.set_shader_parameter("water_n", tex.water_n)
	m.set_shader_parameter("noise_t", tex.noise)
	return m


func set_param(name: String, v) -> void:
	for L: Level in levels:
		L.mat.set_shader_parameter(name, v)


func set_water_param(name: String, v) -> void:
	for L: Level in levels:
		L.wmat.set_shader_parameter(name, v)


func configure(gfx: int) -> void:
	## gfx: 0 FAST, 1 HIGH, 2 MAX
	grass_count = [0, 6000, 13000][gfx]
	grass_r = [0.0, 62.0, 96.0][gfx]
	grass_mat.set_shader_parameter("fade_r", grass_r)
	shadows = gfx > 0
	if levels.size() > 0:
		var L0: Level = levels[0]
		L0.radius = [150.0, 200.0, 250.0][gfx]
		if levels.size() > 1:
			var L1: Level = levels[1]
			L1.mat.set_shader_parameter("drop_r0", L0.radius - L0.size * 0.5)
			L1.mat.set_shader_parameter("drop_r1", L0.radius + L0.size * 1.5)
	for L: Level in levels:
		for k in L.chunks:
			var c: Dictionary = L.chunks[k]
			if c.has("mi"):
				c.mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if shadows and L == levels[0] else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
			if c.has("grass"):
				c.grass.queue_free()
				c.erase("grass")
	# regrow grass on ready near chunks
	if grass_count > 0 and levels.size() > 0:
		for k in levels[0].chunks:
			var c: Dictionary = levels[0].chunks[k]
			if c.get("ready", false) and c.has("job"):
				_make_grass(levels[0], k, c, c.job)
	last_plan = Vector3(1e9, 0, 1e9)


func clear() -> void:
	for L: Level in levels:
		for k in L.chunks.keys():
			_free_chunk(L, k)
		L.chunks.clear()
		if L.mask_img != null:
			L.mask_img.fill(Color(0, 0, 0))
			L.mask_tex.update(L.mask_img)
	queue.clear()
	jobs.clear()
	post.clear()
	last_plan = Vector3(1e9, 0, 1e9)


# ------------------------------------------------------------------ streaming
func update(cam_pos: Vector3, budget := -1) -> void:
	cam = cam_pos
	cloud_off += Vector2(0.0011, 0.0006) * get_process_delta_time()
	for L: Level in levels:
		L.mat.set_shader_parameter("cam_pos", cam)
		L.wmat.set_shader_parameter("cam_pos", cam)
		L.mat.set_shader_parameter("cloud_off", cloud_off)
	grass_mat.set_shader_parameter("cam_pos", cam)
	if Vector2(cam.x - last_plan.x, cam.z - last_plan.z).length() > 12.0:
		last_plan = cam
		var a := Time.get_ticks_usec()
		_plan()
		smax[4] = maxi(smax[4], Time.get_ticks_usec() - a)
	_work(budget if budget >= 0 else budget_us)


func busy() -> bool:
	return not queue.is_empty() or not jobs.is_empty() or not post.is_empty()


func pending() -> int:
	return queue.size() + jobs.size() + post.size()


func _plan() -> void:
	var want := []
	for li in levels.size():
		var L: Level = levels[li]
		var keep := {}
		var r := L.radius
		var c0 := int(floor((cam.x - r) / L.size))
		var c1 := int(floor((cam.x + r) / L.size))
		var r0 := int(floor((cam.z - r) / L.size))
		var r1 := int(floor((cam.z + r) / L.size))
		for cz in range(r0, r1 + 1):
			for cx in range(c0, c1 + 1):
				var ctr := Vector2((cx + 0.5) * L.size, (cz + 0.5) * L.size)
				# distance from the camera to the chunk's square
				var dx := maxf(absf(cam.x - ctr.x) - L.size * 0.5, 0.0)
				var dz := maxf(absf(cam.z - ctr.y) - L.size * 0.5, 0.0)
				var d := sqrt(dx * dx + dz * dz)
				if d > r:
					continue
				if L.bounds.size.x > 0.0 and not L.bounds.intersects(Rect2(cx * L.size, cz * L.size, L.size, L.size)):
					continue
				if not source.chunk_wanted(li, cx, cz):
					continue
				var k := Vector2i(cx, cz)
				keep[k] = true
				if not L.chunks.has(k):
					L.chunks[k] = {"ready": false}
					want.append([d + li * 40.0, li, k])
		# drop chunks that are far outside the ring
		if not L.permanent:
			for k in L.chunks.keys():
				if keep.has(k):
					continue
				var ctr2 := Vector2((k.x + 0.5) * L.size, (k.y + 0.5) * L.size)
				if ctr2.distance_to(Vector2(cam.x, cam.z)) > r + L.size * 1.5:
					_free_chunk(L, k)
					L.chunks.erase(k)
		_recenter_mask(li)
	want.sort_custom(func(a, b): return a[0] < b[0])
	for w in want:
		queue.append(w)
	# re-sort the whole queue by current distance
	var cp := Vector2(cam.x, cam.z)
	queue = queue.filter(func(q): return levels[q[1]].chunks.has(q[2]) and not levels[q[1]].chunks[q[2]].ready)
	for q in queue:
		var L: Level = levels[q[1]]
		var ctr := Vector2((q[2].x + 0.5) * L.size, (q[2].y + 0.5) * L.size)
		q[0] = ctr.distance_to(cp) - L.size * 0.5 + q[1] * 60.0
	queue.sort_custom(func(a, b): return a[0] < b[0])


var post := []
var smax := [0, 0, 0, 0, 0]


func _work(budget: int) -> void:
	var t0 := Time.get_ticks_usec()
	while Time.get_ticks_usec() - t0 < budget:
		if not post.is_empty():
			var pj = post.pop_front()
			var Lp: Level = levels[pj[0]]
			if Lp.chunks.has(pj[1]):
				var a := Time.get_ticks_usec()
				_post(pj)
				var st := int(pj[3])
				smax[st] = maxi(smax[st], Time.get_ticks_usec() - a)
			continue
		if jobs.is_empty():
			if queue.is_empty():
				break
			var q = queue.pop_front()
			var L: Level = levels[q[1]]
			if not L.chunks.has(q[2]) or L.chunks[q[2]].ready:
				continue
			var k: Vector2i = q[2]
			var job = source.begin_chunk(q[1], k.x * L.size, k.y * L.size, L.step, L.n)
			jobs.append([q[1], k, job])
		var j = jobs[0]
		var L2: Level = levels[j[0]]
		if not L2.chunks.has(j[1]):
			jobs.pop_front()
			continue
		var left := budget - (Time.get_ticks_usec() - t0)
		var a2 := Time.get_ticks_usec()
		var done: bool = j[2].run(maxi(left, 300))
		smax[3] = maxi(smax[3], Time.get_ticks_usec() - a2 - maxi(left, 300))
		if done:
			jobs.pop_front()
			post.append([j[0], j[1], j[2], 0])
	stat_us = Time.get_ticks_usec() - t0


## Generate everything that is wanted right now (loading screens, tests).
func flush(cam_pos: Vector3, max_ms := 20000) -> void:
	cam = cam_pos
	last_plan = cam
	_plan()
	var t0 := Time.get_ticks_msec()
	while busy() and Time.get_ticks_msec() - t0 < max_ms:
		_work(200000)


# ------------------------------------------------------------------ chunk meshes
func _indices(n: int) -> PackedInt32Array:
	if idx_cache.has(n):
		return idx_cache[n]
	var w := n + 1
	var idx := PackedInt32Array()
	idx.resize(n * n * 6 + n * 4 * 6)
	var k := 0
	for j in n:
		for i in n:
			var a := j * w + i
			# alternate the diagonal for a less regular look
			if (i + j) % 2 == 0:
				idx[k] = a; idx[k + 1] = a + 1; idx[k + 2] = a + w
				idx[k + 3] = a + 1; idx[k + 4] = a + w + 1; idx[k + 5] = a + w
			else:
				idx[k] = a; idx[k + 1] = a + w + 1; idx[k + 2] = a + w
				idx[k + 3] = a; idx[k + 4] = a + 1; idx[k + 5] = a + w + 1
			k += 6
	# skirt: ring of vertices after the grid, in the order top edge, right edge, bottom edge, left edge
	var base := w * w
	var edges := []
	for i in w:
		edges.append(i)  # top row (j = 0)
	for j in w:
		edges.append(j * w + n)  # right column
	for i in w:
		edges.append(n * w + (n - i))  # bottom row reversed
	for j in w:
		edges.append((n - j) * w)  # left column reversed
	for e in 4:
		for s in n:
			var a: int = edges[e * w + s]
			var b: int = edges[e * w + s + 1]
			var sa: int = base + e * w + s
			var sb: int = base + e * w + s + 1
			# winding so the skirt faces outward
			idx[k] = a; idx[k + 1] = sa; idx[k + 2] = b
			idx[k + 3] = b; idx[k + 4] = sa; idx[k + 5] = sb
			k += 6
	idx.resize(k)
	idx_cache[n] = idx
	idx_cache["edges%d" % n] = edges
	return idx


func _finish(li: int, k: Vector2i, job) -> void:
	var L: Level = levels[li]
	var c: Dictionary = L.chunks[k]
	var n := L.n
	var w := n + 1
	var b := n + 3
	var st := L.step
	var x0 := k.x * L.size
	var z0 := k.y * L.size
	var h: PackedFloat32Array = job.h
	var verts := PackedVector3Array()
	var norms := PackedVector3Array()
	var tans := PackedFloat32Array()
	var cols := PackedColorArray()
	var uvs := PackedVector2Array()
	var uv2s := PackedVector2Array()
	var tot := w * w + 4 * w
	verts.resize(tot)
	norms.resize(tot)
	tans.resize(tot * 4)
	cols.resize(tot)
	uvs.resize(tot)
	uv2s.resize(tot)
	var v := 0
	var s2 := 2.0 * st
	for j in w:
		var row := (j + 1) * b + 1
		var zz := z0 + j * st
		for i in w:
			var kk := row + i
			var hh := h[kk]
			verts[v] = Vector3(x0 + i * st, hh, zz)
			var dx := h[kk - 1] - h[kk + 1]
			var dz := h[kk - b] - h[kk + b]
			norms[v] = Vector3(dx, s2, dz).normalized()
			var tl := sqrt(s2 * s2 + dx * dx)
			tans[v * 4] = s2 / tl
			tans[v * 4 + 1] = -dx / tl
			tans[v * 4 + 2] = 0.0
			tans[v * 4 + 3] = 1.0
			v += 1
	cols = job.mcol.duplicate() if "mcol" in job and not job.mcol.is_empty() else job.col.duplicate()
	uvs = job.uv.duplicate()
	uv2s = job.uv2.duplicate()
	cols.resize(tot)
	uvs.resize(tot)
	uv2s.resize(tot)
	_indices(n)
	var edges: Array = idx_cache["edges%d" % n]
	for e in edges.size():
		var src: int = edges[e]
		verts[w * w + e] = verts[src] - Vector3(0, L.skirt, 0)
		norms[w * w + e] = norms[src]
		tans[(w * w + e) * 4] = tans[src * 4]
		tans[(w * w + e) * 4 + 1] = tans[src * 4 + 1]
		tans[(w * w + e) * 4 + 3] = 1.0
		cols[w * w + e] = cols[src]
		uvs[w * w + e] = uvs[src]
		uv2s[w * w + e] = uv2s[src]
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = verts
	arr[Mesh.ARRAY_NORMAL] = norms
	arr[Mesh.ARRAY_TANGENT] = tans
	arr[Mesh.ARRAY_COLOR] = cols
	arr[Mesh.ARRAY_TEX_UV] = uvs
	arr[Mesh.ARRAY_TEX_UV2] = uv2s
	arr[Mesh.ARRAY_INDEX] = idx_cache[n]
	var mesh := ArrayMesh.new()
	mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	var mi := MeshInstance3D.new()
	mi.mesh = mesh
	mi.material_override = L.mat
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if shadows and li == 0 else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	mi.visible = false
	add_child(mi)
	c.mi = mi


func _post(pj: Array) -> void:
	var li: int = pj[0]
	var k: Vector2i = pj[1]
	var job = pj[2]
	var L: Level = levels[li]
	var c: Dictionary = L.chunks[k]
	match int(pj[3]):
		0:
			_finish(li, k, job)
			post.push_front([li, k, job, 1])
		1:
			if water_on and job.min_h < sea + 0.6:
				c.water = _make_water(L, k.x * L.size, k.y * L.size, job.h, L.n)
			c.mi.visible = true
			c.ready = true
			built_count += 1
			if L.mask_img != null:
				_mask_set(li, k, true)
			if li == 0:
				c.job = job
			if source.has_method("chunk_built"):
				source.chunk_built(li, k, job)
			if li == 0 and grass_count > 0:
				post.append([li, k, job, 2])
		2:
			if not c.has("grass"):
				if _make_grass(L, k, c, job, pj):
					pass
				else:
					post.append(pj)


func _make_water(L: Level, x0: float, z0: float, h: PackedFloat32Array, n: int) -> MeshInstance3D:
	var sub := 2 if n >= 16 else 1
	var m := n / sub
	var w := m + 1
	var b := n + 3
	var st := L.step * sub
	var verts := PackedVector3Array()
	var uvs := PackedVector2Array()
	verts.resize(w * w)
	uvs.resize(w * w)
	var v := 0
	var dry := PackedByteArray()
	dry.resize(w * w)
	for j in w:
		for i in w:
			var hh := h[(j * sub + 1) * b + i * sub + 1]
			verts[v] = Vector3(x0 + i * st, sea, z0 + j * st)
			uvs[v] = Vector2(sea - hh, 0.0)
			dry[v] = 1 if hh > sea + 1.2 else 0
			v += 1
	var idx := PackedInt32Array()
	for j in m:
		for i in m:
			var a := j * w + i
			if dry[a] and dry[a + 1] and dry[a + w] and dry[a + w + 1]:
				continue
			idx.append_array([a, a + 1, a + w, a + 1, a + w + 1, a + w])
	if idx.is_empty():
		return null
	var arr := []
	arr.resize(Mesh.ARRAY_MAX)
	arr[Mesh.ARRAY_VERTEX] = verts
	var nr := PackedVector3Array()
	nr.resize(w * w)
	nr.fill(Vector3.UP)
	arr[Mesh.ARRAY_NORMAL] = nr
	arr[Mesh.ARRAY_TEX_UV] = uvs
	arr[Mesh.ARRAY_INDEX] = idx
	var mesh := ArrayMesh.new()
	mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arr)
	mesh.custom_aabb = AABB(Vector3(x0, sea - 1.0, z0), Vector3(L.size, 2.0, L.size))
	var mi := MeshInstance3D.new()
	mi.mesh = mesh
	mi.material_override = L.wmat
	mi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mi)
	return mi


func _free_chunk(L: Level, k: Vector2i) -> void:
	var c: Dictionary = L.chunks[k]
	for key in ["mi", "water", "grass"]:
		if c.has(key) and c[key] != null and is_instance_valid(c[key]):
			c[key].queue_free()
	if c.get("ready", false) and L.mask_img != null:
		_mask_set(levels.find(L), k, false)
	if source.has_method("chunk_freed"):
		source.chunk_freed(levels.find(L), k)


# ------------------------------------------------------------------ hole masks
func _recenter_mask(li: int) -> void:
	var L: Level = levels[li]
	if L.mask_img == null:
		return
	var half := L.mask_res / 2
	var cc := Vector2i(int(floor(cam.x / L.size)), int(floor(cam.z / L.size)))
	var org := cc - Vector2i(half, half)
	if absi(org.x - L.mask_org.x) < half / 2 and absi(org.y - L.mask_org.y) < half / 2:
		return
	L.mask_org = org
	L.mask_img.fill(Color(0, 0, 0))
	for k in L.chunks:
		if L.chunks[k].ready:
			var p: Vector2i = k - org
			if p.x >= 0 and p.y >= 0 and p.x < L.mask_res and p.y < L.mask_res:
				L.mask_img.set_pixel(p.x, p.y, Color(1, 0, 0))
	L.mask_tex.update(L.mask_img)
	var coarse: Level = levels[li + 1]
	var win := Vector4(org.x * L.size, org.y * L.size, L.size, L.mask_res)
	coarse.mat.set_shader_parameter("hole_win", win)
	coarse.wmat.set_shader_parameter("hole_win", win)


func _mask_set(li: int, k: Vector2i, on: bool) -> void:
	var L: Level = levels[li]
	var p: Vector2i = k - L.mask_org
	if p.x >= 0 and p.y >= 0 and p.x < L.mask_res and p.y < L.mask_res:
		L.mask_img.set_pixel(p.x, p.y, Color(1, 0, 0) if on else Color(0, 0, 0))
		L.mask_tex.update(L.mask_img)


# ------------------------------------------------------------------ grass
func _grass_tuft() -> ArrayMesh:
	## a clump of 9 curved blades; vertex height is in metres (used by the wind and shading)
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)
	var rng := RandomNumberGenerator.new()
	rng.seed = 3
	for b in 9:
		var a := rng.randf() * TAU
		var r := rng.randf_range(0.0, 0.22)
		var base := Vector3(cos(a) * r, 0, sin(a) * r)
		var lean := Vector3(cos(a), 0, sin(a)) * rng.randf_range(0.08, 0.3)
		var ha := rng.randf() * TAU
		var side := Vector3(cos(ha), 0, sin(ha))
		var hgt := rng.randf_range(0.28, 0.62)
		var wid := rng.randf_range(0.035, 0.06)
		var pts := []
		for s in 4:
			var t := s / 3.0
			var c := base + lean * t * t + Vector3(0, hgt * t, 0)
			var ww := wid * (1.0 - t) + 0.004
			pts.append([c - side * ww, c + side * ww])
		var nrm := side.cross(Vector3.UP).normalized()
		for s in 3:
			var a0: Vector3 = pts[s][0]
			var a1: Vector3 = pts[s][1]
			var b0: Vector3 = pts[s + 1][0]
			var b1: Vector3 = pts[s + 1][1]
			for p in [a0, a1, b1, a0, b1, b0]:
				st.set_normal(nrm)
				st.add_vertex(p)
	return st.commit()


## Builds the grass in slices of 500 candidates; returns true when finished. pj (optional) keeps the state.
func _make_grass(L: Level, k: Vector2i, c: Dictionary, job, pj = null) -> bool:
	var col: PackedColorArray = job.col
	var h: PackedFloat32Array = job.h
	var n := L.n
	var w := n + 1
	var b := n + 3
	var st := L.step
	var state: Dictionary
	if pj != null and pj.size() > 4:
		state = pj[4]
	else:
		state = {"rng": RandomNumberGenerator.new(), "buf": PackedFloat32Array(), "cnt": 0, "t": 0}
		state.rng.seed = hash(k) + 77
		state.buf.resize(grass_count * 16)
		if pj != null:
			pj.append(state)
	var rng: RandomNumberGenerator = state.rng
	var buf: PackedFloat32Array = state.buf
	var cnt: int = state.cnt
	var t_end := mini(grass_count, int(state.t) + (500 if pj != null else grass_count))
	for t in range(int(state.t), t_end):
		var fx := rng.randf() * n
		var fz := rng.randf() * n
		var i := int(fx)
		var j := int(fz)
		var ax := fx - i
		var az := fz - j
		var ci := j * w + i
		var g := col[ci].a * (1.0 - ax) * (1.0 - az) + col[ci + 1].a * ax * (1.0 - az) + col[ci + w].a * (1.0 - ax) * az + col[ci + w + 1].a * ax * az
		if rng.randf() > g * g * 1.2:
			continue
		var hi := (j + 1) * b + i + 1
		var hh := h[hi] * (1.0 - ax) * (1.0 - az) + h[hi + 1] * ax * (1.0 - az) + h[hi + b] * (1.0 - ax) * az + h[hi + b + 1] * ax * az
		var tint: Color = col[ci]
		var s := rng.randf_range(0.7, 1.35) * (0.6 + 0.5 * g)
		var rot := rng.randf() * TAU
		var cs := cos(rot) * s
		var sn := sin(rot) * s
		var o := cnt * 16
		buf[o] = cs; buf[o + 1] = 0.0; buf[o + 2] = sn; buf[o + 3] = k.x * L.size + fx * st
		buf[o + 4] = 0.0; buf[o + 5] = s; buf[o + 6] = 0.0; buf[o + 7] = hh - 0.03
		buf[o + 8] = -sn; buf[o + 9] = 0.0; buf[o + 10] = cs; buf[o + 11] = k.y * L.size + fz * st
		var v := rng.randf_range(0.85, 1.12)
		buf[o + 12] = tint.r * v * 1.05; buf[o + 13] = tint.g * v * 1.08; buf[o + 14] = tint.b * v * 0.9; buf[o + 15] = 1.0
		cnt += 1
	state.cnt = cnt
	state.t = t_end
	if t_end < grass_count:
		return false
	if cnt == 0:
		return true
	buf.resize(cnt * 16)
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_colors = true
	mm.mesh = grass_mesh
	mm.instance_count = cnt
	mm.buffer = buf
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = mm
	mmi.material_override = grass_mat
	mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	mmi.visibility_range_end = grass_r + L.size
	add_child(mmi)
	c.grass = mmi
	return true

