extends Control
## Multi-touch driving controls for iPad, plus small tap buttons (pause, camera, reset, horn) for everyone.

var game
var main
var held := {}
var touches := {}
var flash := {}
const HOLD := ["gas", "brake", "left", "right", "drift", "nitro"]


func _ready() -> void:
	set_anchors_preset(Control.PRESET_FULL_RECT)
	mouse_filter = Control.MOUSE_FILTER_IGNORE


func _active() -> bool:
	return game != null and game.driving() and not game.paused and game.state != "done"


func _process(dt: float) -> void:
	visible = _active()
	if not visible:
		if not touches.is_empty():
			touches.clear()
			held.clear()
			_sync()
		return
	for k in flash.keys():
		flash[k] -= dt
		if flash[k] <= 0.0:
			flash.erase(k)
	queue_redraw()


func _layout() -> Dictionary:
	var vs := get_viewport_rect().size
	var W := vs.x
	var H := vs.y
	var L := {}
	var touch_ui: bool = G.is_touch
	if touch_ui:
		L["left"] = [Vector2(105, H - 115), 74.0]
		L["right"] = [Vector2(265, H - 115), 74.0]
		L["gas"] = [Vector2(W - 112, H - 122), 84.0]
		L["brake"] = [Vector2(W - 285, H - 78), 56.0]
		L["drift"] = [Vector2(W - 275, H - 212), 64.0]
		L["nitro"] = [Vector2(W - 118, H - 300), 56.0]
	L["pause"] = [Vector2(W - 228, 46), 30.0]
	L["camera"] = [Vector2(W - 296, 46), 30.0]
	L["reset"] = [Vector2(W - 364, 46), 30.0]
	L["horn"] = [Vector2(W - 432, 46), 30.0]
	L["lights"] = [Vector2(W - 500, 46), 30.0]
	return L


func _hit(p: Vector2) -> String:
	var L := _layout()
	var best := ""
	var bd := 1e9
	for k in L:
		var c: Vector2 = L[k][0]
		var r: float = L[k][1]
		var d := p.distance_to(c)
		var reach := r * (1.25 if k in HOLD else 1.15)
		if d < reach and d < bd:
			bd = d
			best = k
	if best == "" and G.is_touch:
		# generous steering zone: anywhere in the lower-left corner
		var vs := get_viewport_rect().size
		if p.x < 380 and p.y > vs.y * 0.55:
			best = "left" if p.x < 185 else "right"
	return best


func _input(e: InputEvent) -> void:
	if not _active():
		return
	if e is InputEventScreenTouch:
		if e.pressed:
			var b := _hit(e.position)
			if b != "":
				touches[e.index] = b
				_press(b)
				get_viewport().set_input_as_handled()
		else:
			if touches.has(e.index):
				var b: String = touches[e.index]
				touches.erase(e.index)
				_release(b)
	elif e is InputEventScreenDrag:
		if touches.has(e.index):
			var old: String = touches[e.index]
			if old in HOLD:
				var b := _hit(e.position)
				if b != old and b in HOLD:
					touches[e.index] = b
					_release(old)
					_press(b)


func _press(b: String) -> void:
	if b in HOLD:
		held[b] = true
		G.is_touch = true
		_sync()
		return
	flash[b] = 0.2
	match b:
		"pause":
			main.toggle_pause()
		"camera":
			game.cycle_camera()
		"reset":
			game.reset_car()
		"horn":
			game.honk()
		"lights":
			game.player.set_lights(not game.player.lights_on)


func _release(b: String) -> void:
	if b in HOLD:
		var still := false
		for i in touches:
			if touches[i] == b:
				still = true
		if not still:
			held.erase(b)
		_sync()


func _sync() -> void:
	for k in HOLD:
		game.touch[k] = held.has(k)


func _draw() -> void:
	var L := _layout()
	for k in L:
		var c: Vector2 = L[k][0]
		var r: float = L[k][1]
		var on := held.has(k) or flash.has(k)
		var base := Color(0.02, 0.08, 0.13, 0.45)
		var ring := Color(1, 1, 1, 0.55)
		match k:
			"gas":
				base = Color(0.2, 0.75, 0.3, 0.55)
			"brake":
				base = Color(0.85, 0.2, 0.2, 0.5)
			"drift":
				base = Color(1.0, 0.55, 0.1, 0.6)
			"nitro":
				base = Color(0.25, 0.55, 1.0, 0.55)
		if on:
			base = base.lightened(0.35)
			base.a = 0.85
		draw_circle(c, r, base)
		draw_arc(c, r, 0, TAU, 40, ring, 4.0, true)
		var ic := Color(1, 1, 1, 0.95)
		match k:
			"left":
				_tri(c, r * 0.45, PI, ic)
			"right":
				_tri(c, r * 0.45, 0.0, ic)
			"gas":
				G.draw_text_c(self, c, "GAS", 30, ic, G.font_title, 6)
			"brake":
				G.draw_text_c(self, c, "BRAKE", 17, ic, G.font_title, 5)
			"drift":
				G.draw_text_c(self, c, "DRIFT", 22, ic, G.font_title, 6)
			"nitro":
				var n: float = game.player.nitro
				draw_arc(c, r - 6, -PI / 2, -PI / 2 + TAU * n, 40, Color(0.6, 0.9, 1.0, 0.95), 8.0, true)
				G.draw_text_c(self, c, "NITRO", 16, ic, G.font_title, 5)
			"pause":
				draw_rect(Rect2(c + Vector2(-9, -11), Vector2(6, 22)), ic)
				draw_rect(Rect2(c + Vector2(3, -11), Vector2(6, 22)), ic)
			"camera":
				draw_rect(Rect2(c + Vector2(-13, -8), Vector2(20, 16)), ic)
				_tri(c + Vector2(10, 0), 8.0, 0.0, ic)
			"reset":
				draw_arc(c, 11, 0.6, TAU - 0.3, 20, ic, 4.0, true)
				_tri(c + Vector2(11, -3), 6.0, PI * 0.5, ic)
			"lights":
				draw_circle(c + Vector2(-4, 0), 9, ic)
				for kk in 3:
					draw_line(c + Vector2(7, -8 + kk * 8), c + Vector2(15, -8 + kk * 8), ic, 3.0)
			"horn":
				var pts := PackedVector2Array([c + Vector2(-12, -5), c + Vector2(-4, -5), c + Vector2(8, -13), c + Vector2(8, 13), c + Vector2(-4, 5), c + Vector2(-12, 5)])
				draw_colored_polygon(pts, ic)


func _tri(c: Vector2, s: float, ang: float, col: Color) -> void:
	var pts := PackedVector2Array([c + Vector2(s, 0).rotated(ang), c + Vector2(-s * 0.6, -s * 0.9).rotated(ang), c + Vector2(-s * 0.6, s * 0.9).rotated(ang)])
	draw_colored_polygon(pts, col)

files.scripts/veg.gd:
extends Node3D
## Instanced vegetation in square cells. Each cell holds one far MultiMesh per species (light meshes). One global
## near MultiMesh per species holds the detailed meshes of everything within the near radius; the shader shows
## each instance in exactly one of the two (decided on the GPU from the instance position and the camera),
## so the swap is seamless and the near set only needs rebuilding every few metres of camera movement.

const Flora = preload("res://scripts/flora.gd")
const STRIDE := 20

const VEG_SHADER := """
shader_type spatial;
render_mode cull_disabled;
uniform sampler2D atlas : source_color, filter_linear_mipmap, repeat_disable;
uniform sampler2D bark_t : source_color, filter_linear_mipmap, repeat_enable;
uniform vec3 cam_pos = vec3(0.0);
uniform float near_r = 80.0;
uniform float far_r = 900.0;
uniform float is_near = 1.0;
uniform float is_leaf = 0.0;
uniform float use_bark = 0.0;
uniform float sway = 1.0;
uniform float wet = 0.0;
uniform float snow = 0.0;
uniform float tint_solid = 0.0;
varying vec4 vc;
varying float hgt;
void vertex() {
	vec3 ip = MODEL_MATRIX[3].xyz;
	float d = length(ip.xz - cam_pos.xz);
	float s;
	if (is_near > 0.5) {
		s = d < near_r ? 1.0 : 0.0;
	} else {
		s = d >= near_r ? 1.0 - smoothstep(far_r * 0.82, far_r, d) : 0.0;
	}
	hgt = VERTEX.y;
	float h = max(VERTEX.y, 0.0);
	float ph = ip.x * 0.07 + ip.z * 0.05 + INSTANCE_CUSTOM.a * 6.28;
	float w = sway * (sin(TIME * 1.05 + ph) * 0.6 + sin(TIME * 2.4 + ph * 1.7) * 0.22);
	VERTEX.x += w * 0.0045 * h * h;
	VERTEX.z += w * 0.003 * h * h;
	if (is_leaf > 0.5) {
		VERTEX += NORMAL * sin(TIME * 5.0 + VERTEX.x * 3.0 + VERTEX.z * 2.0 + ph) * 0.025 * sway * min(h, 6.0);
	}
	VERTEX *= s;
	vc = vec4(COLOR.rgb * mix(vec3(1.0), INSTANCE_CUSTOM.rgb, max(is_leaf, tint_solid)), COLOR.a);
}
void fragment() {
	vec3 c = vc.rgb;
	float a = 1.0;
	if (is_leaf > 0.5) {
		vec4 t = texture(atlas, UV);
		c *= t.rgb * 1.25;
		a = t.a;
		BACKLIGHT = c * 0.6;
	} else if (use_bark > 0.5) {
		float bl = dot(texture(bark_t, vec2(UV.x * 2.0, UV.y * 0.5)).rgb, vec3(0.333));
		c *= mix(1.0, bl / 0.075, 0.85);
	}
	float up = clamp(NORMAL.y, 0.0, 1.0);
	c = mix(c, vec3(0.9, 0.93, 0.97), snow * smoothstep(0.55, 0.85, up) * (is_leaf > 0.5 ? 0.6 : 0.8));
	ALBEDO = c * (1.0 - wet * 0.2);
	ALPHA = a;
	ALPHA_SCISSOR_THRESHOLD = 0.45;
	ROUGHNESS = mix(vc.a, 0.4, wet);
	SPECULAR = 0.35;
}
"""

class Species:
	var name := ""
	var hq: ArrayMesh
	var lo: ArrayMesh
	var near_mmi: MultiMeshInstance3D
	var near_mats := []
	var far_mats := []
	var shadow := true
	var sway := 1.0

var species := {}
var cells := {}
var buckets := {}
const BUCKET := 64.0
var cell_size := 128.0
var cam := Vector3.ZERO
var last_near := Vector3(1e9, 0, 1e9)
var near_r := 80.0
var far_r := 900.0
var near_on := true
var shader: Shader
var atlas: Texture2D
var bark: Texture2D
var shadows := true
var dirty := false


func setup(atlas_tex: Texture2D, bark_tex: Texture2D) -> void:
	atlas = atlas_tex
	bark = bark_tex
	shader = Shader.new()
	shader.code = VEG_SHADER


func add_species(name: String, hq: ArrayMesh, lo: ArrayMesh, sway := 1.0, shadow := true, bark_tex := false, tint_solid := false) -> void:
	var s := Species.new()
	s.name = name
	s.hq = hq
	s.lo = lo
	s.sway = sway
	s.shadow = shadow
	for near in [true, false]:
		var mats := []
		for surf in 2:
			var m := ShaderMaterial.new()
			m.shader = shader
			m.set_shader_parameter("atlas", atlas)
			m.set_shader_parameter("bark_t", bark)
			m.set_shader_parameter("is_near", 1.0 if near else 0.0)
			m.set_shader_parameter("is_leaf", 1.0 if surf == 1 else 0.0)
			m.set_shader_parameter("use_bark", 1.0 if bark_tex and surf == 0 else 0.0)
			m.set_shader_parameter("sway", sway)
			m.set_shader_parameter("tint_solid", 1.0 if tint_solid else 0.0)
			mats.append(m)
		if near:
			s.near_mats = mats
		else:
			s.far_mats = mats
	var mm := MultiMesh.new()
	mm.transform_format = MultiMesh.TRANSFORM_3D
	mm.use_custom_data = true
	mm.use_colors = true
	mm.mesh = hq
	mm.instance_count = 0
	var mmi := MultiMeshInstance3D.new()
	mmi.multimesh = mm
	_apply_mats(mmi, hq, s.near_mats)
	mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if shadow else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	add_child(mmi)
	s.near_mmi = mmi
	species[name] = s


func _apply_mats(_mmi: MultiMeshInstance3D, mesh: Mesh, mats: Array) -> void:
	## MultiMeshInstance3D has no per-surface overrides: the materials live on the (per-species) meshes
	for i in mesh.get_surface_count():
		mesh.surface_set_material(i, mats[mini(i, 1)])


func configure(gfx: int) -> void:
	near_on = gfx > 0
	near_r = [0.0, 75.0, 130.0][gfx]
	far_r = [520.0, 850.0, 1250.0][gfx]
	shadows = gfx > 0
	for s: Species in species.values():
		for m in s.near_mats + s.far_mats:
			m.set_shader_parameter("near_r", near_r)
			m.set_shader_parameter("far_r", far_r)
		s.near_mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_ON if s.shadow and shadows else GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
	for key in cells:
		for mmi in cells[key].far.values():
			mmi.visibility_range_end = far_r + cell_size
	last_near = Vector3(1e9, 0, 1e9)


func set_param(name: String, v) -> void:
	for s: Species in species.values():
		for m in s.near_mats + s.far_mats:
			m.set_shader_parameter(name, v)


## items: {species_name: PackedFloat32Array of 20 floats per instance (12 transform + 4 colour + 4 custom)}
## (instance colours are always on: the Compatibility renderer reads them even when disabled)
func add_cell(key, items: Dictionary) -> void:
	remove_cell(key)
	var c := {"items": items, "far": {}}
	for sp in items:
		var buf: PackedFloat32Array = items[sp]
		if buf.is_empty() or not species.has(sp):
			continue
		var s: Species = species[sp]
		var mm := MultiMesh.new()
		mm.transform_format = MultiMesh.TRANSFORM_3D
		mm.use_custom_data = true
		mm.use_colors = true
		mm.mesh = s.lo
		mm.instance_count = buf.size() / STRIDE
		mm.buffer = buf
		var mmi := MultiMeshInstance3D.new()
		mmi.multimesh = mm
		_apply_mats(mmi, s.lo, s.far_mats)
		# far trees do not cast shadows: the shadow range is covered by the detailed near set
		mmi.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		mmi.visibility_range_end = far_r + cell_size
		mmi.set_meta("sp", sp)
		add_child(mmi)
		c.far[sp] = mmi
	# split into small buckets so the near set can be rebuilt quickly
	var bkeys := []
	for sp in items:
		var buf: PackedFloat32Array = items[sp]
		var n := buf.size() / STRIDE
		for i in n:
			var o := i * STRIDE
			var bk := Vector2i(int(floor(buf[o + 3] / BUCKET)), int(floor(buf[o + 11] / BUCKET)))
			if not buckets.has(bk):
				buckets[bk] = {}
				bkeys.append(bk)
			var bd: Dictionary = buckets[bk]
			if not bd.has(sp):
				bd[sp] = PackedFloat32Array()
			bd[sp].append_array(buf.slice(o, o + STRIDE))
	c.bkeys = bkeys
	cells[key] = c
	dirty = true


func remove_cell(key) -> void:
	if not cells.has(key):
		return
	for mmi in cells[key].far.values():
		mmi.queue_free()
	for bk in cells[key].bkeys:
		buckets.erase(bk)
	cells.erase(key)
	dirty = true


func clear() -> void:
	for k in cells.keys():
		remove_cell(k)
	for s: Species in species.values():
		s.near_mmi.multimesh.instance_count = 0


func update(cam_pos: Vector3) -> void:
	cam = cam_pos
	for s: Species in species.values():
		for m in s.near_mats:
			m.set_shader_parameter("cam_pos", cam)
		for m in s.far_mats:
			m.set_shader_parameter("cam_pos", cam)
	if not near_on:
		if last_near.x < 1e8:
			for s: Species in species.values():
				s.near_mmi.multimesh.instance_count = 0
			last_near = Vector3(1e9, 0, 1e9)
		return
	if dirty or Vector2(cam.x - last_near.x, cam.z - last_near.z).length() > 6.0:
		dirty = false
		last_near = cam
		_rebuild_near()


func _rebuild_near() -> void:
	var r := near_r + 12.0
	var r2 := r * r
	var out := {}
	for sp in species:
		out[sp] = PackedFloat32Array()
	var c0 := int(floor((cam.x - r) / BUCKET))
	var c1 := int(floor((cam.x + r) / BUCKET))
	var z0 := int(floor((cam.z - r) / BUCKET))
	var z1 := int(floor((cam.z + r) / BUCKET))
	for cz in range(z0, z1 + 1):
		for cx in range(c0, c1 + 1):
			var key := Vector2i(cx, cz)
			if not buckets.has(key):
				continue
			var items: Dictionary = buckets[key]
			for sp in items:
				if not out.has(sp):
					continue
				var buf: PackedFloat32Array = items[sp]
				var dst: PackedFloat32Array = out[sp]
				var n := buf.size() / STRIDE
				for i in n:
					var o := i * STRIDE
					var dx := buf[o + 3] - cam.x
					var dz := buf[o + 11] - cam.z
					if dx * dx + dz * dz < r2:
						dst.append_array(buf.slice(o, o + STRIDE))
				out[sp] = dst
	for sp in out:
		var s: Species = species[sp]
		var buf: PackedFloat32Array = out[sp]
		var mm := s.near_mmi.multimesh
		mm.instance_count = buf.size() / STRIDE
		if buf.size() > 0:
			mm.buffer = buf


## Helper: packs one instance into a buffer. rot = yaw, s = uniform scale, tint = leaf colour, rnd = 0..1 phase.
static func pack(buf: PackedFloat32Array, pos: Vector3, rot: float, s: float, tint: Color, rnd: float, tilt := 0.0) -> void:
	var b := Basis(Vector3.UP, rot).scaled(Vector3(s, s, s))
	if tilt != 0.0:
		b = Basis(Vector3(cos(rot), 0, -sin(rot)), tilt) * b
	buf.append_array([b.x.x, b.y.x, b.z.x, pos.x, b.x.y, b.y.y, b.z.y, pos.y, b.x.z, b.y.z, b.z.z, pos.z, 1.0, 1.0, 1.0, 1.0, tint.r, tint.g, tint.b, rnd])

files.tools/carcount.gd:
extends SceneTree
func _count(n: Node, acc: Dictionary) -> void:
	if n is MeshInstance3D and n.mesh != null:
		acc.mi += 1
		acc.surf += n.mesh.get_surface_count()
		acc.tris += n.mesh.get_faces().size() / 3
		if n.cast_shadow != GeometryInstance3D.SHADOW_CASTING_SETTING_OFF:
			acc.shadow_surf += n.mesh.get_surface_count()
	for c in n.get_children():
		_count(c, acc)
func _init():
	var CB = load("res://scripts/carbake.gd")
	var CM = load("res://scripts/carmodel.gd")
	for id in ["rally", "buggy", "drifter", "patrol", "muscle", "falcon"]:
		var d0: Dictionary = CM.build(id, Color(0.5, 0.5, 0.5), true, false)
		var a0 := {"mi": 0, "surf": 0, "tris": 0, "shadow_surf": 0}
		_count(d0.root, a0)
		var t0 := Time.get_ticks_msec()
		CB.merge_static(d0)
		var a1 := {"mi": 0, "surf": 0, "tris": 0, "shadow_surf": 0}
		_count(d0.root, a1)
		print(id, " player before ", a0, " after ", a1, " merge ms ", Time.get_ticks_msec() - t0)
	for id in ["rally", "buggy", "drifter", "patrol", "muscle", "falcon"]:
		for mid in [true, false]:
			var t0 := Time.get_ticks_msec()
			var d: Dictionary = CB.build(id, Color(0.5, 0.5, 0.5), mid)
			var acc := {"mi": 0, "surf": 0, "tris": 0, "shadow_surf": 0}
			_count(d.root, acc)
			print(id, " baked ", "mid" if mid else "low", " ", acc, " ms ", Time.get_ticks_msec() - t0)
	quit()

